CREATE OR REPLACE FUNCTION bob_dashboard_private.approval_requester_name_v1(target_club uuid, p_request uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  requester uuid;
  requester_name text;
begin
  if auth.uid() is null
    or not public.has_club_access(target_club)
    or not public.financial_manager_v1(target_club) then
    raise exception 'Sem autorização para consultar aprovações.' using errcode = '42501';
  end if;
  -- Accept a request ID, never an arbitrary profile ID. Only the pending
  -- approval context of this club can legitimize access to this single name.
  select r.requested_by into requester
  from public.financial_requests r
  where r.club_id = target_club and r.id = p_request
    and r.status in ('pending_review','awaiting_validation');
  if not found then
    raise exception 'Pedido não acessível neste contexto.' using errcode = '42501';
  end if;
  if requester is null then return null; end if;
  select nullif(btrim(p.full_name),'') into requester_name
  from public.profiles p where p.id = requester;
  return requester_name;
end;
$function$

CREATE OR REPLACE FUNCTION bob_dinner_private.guard_bar_sale_reversal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ begin
  if TG_OP='INSERT' then
    if new.status='reversed' then raise exception 'A anulação exige uma venda concluída.'; end if;
    return new;
  end if;
  if old.status='reversed' then raise exception 'Uma venda anulada é imutável.'; end if;
  if TG_OP='DELETE' then
    if old.status='completed' then raise exception 'Não é permitido apagar uma venda concluída.'; end if;
    return old;
  end if;
  if old.status='completed' and new.status not in ('completed','reversed') then
    raise exception 'Utiliza Anular venda para reverter uma venda concluída.';
  end if;
  -- Fail closed for every current/future business column. Audit stamping only
  -- changes updated_by/updated_at; original creation metadata remains protected.
  if old.status='completed' and new.status='completed' then
    if (to_jsonb(new)-array['updated_by','updated_at','weekly_dinner_id'])
      is distinct from (to_jsonb(old)-array['updated_by','updated_at','weekly_dinner_id']) then
      raise exception 'Os dados de uma venda concluída são imutáveis.';
    end if;
    if new.weekly_dinner_id is distinct from old.weekly_dinner_id then
      -- Match assign_bar_sale_dinner_v1 exactly: auth/club, financial reporting
      -- and financial_manager_v1. manageBar table UPDATE alone is insufficient.
      -- The existing dinner guard still locks/checks both dinners and their close.
      perform bob_dinner_private.require_access(old.club_id,true);
    end if;
  end if;
  if new.status='reversed' then
    if (to_jsonb(new)-array['status','updated_by','updated_at'])
      is distinct from (to_jsonb(old)-array['status','updated_by','updated_at']) then
      raise exception 'A anulação não pode alterar os dados originais da venda.';
    end if;
    if old.status<>'completed' or new.club_id is distinct from old.club_id
      or new.treasury_transaction_id is distinct from old.treasury_transaction_id
      or new.weekly_dinner_id is distinct from old.weekly_dinner_id
      or not exists(select 1 from public.bar_sale_reversals r
        where r.club_id=old.club_id and r.sale_id=old.id and r.original_transaction_id=old.treasury_transaction_id) then
      raise exception 'Utiliza a operação autorizada Anular venda.';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION bob_dinner_private.guard_sale()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d uuid; c uuid; ids uuid[]; s text;
begin
  if TG_OP='DELETE' then ids:=array[old.weekly_dinner_id]; c:=old.club_id;
  elsif TG_OP='UPDATE' then ids:=array[old.weekly_dinner_id,new.weekly_dinner_id]; c:=new.club_id;
  else ids:=array[new.weekly_dinner_id]; c:=new.club_id; end if;
  -- Lock dinner rows in deterministic order: close and sale completion serialize.
  for d in select distinct x from unnest(ids) x where x is not null order by x loop
    perform 1 from public.weekly_dinners where id=d and club_id=c for update;
    if not found then raise exception 'Jantar inválido para este clube.'; end if;
    select financial_status into s from public.weekly_dinner_finances where dinner_id=d;
    if s='closed' then raise exception 'Reabre o fecho financeiro antes de alterar as vendas.'; end if;
  end loop;
  if TG_OP='DELETE' then return old; end if;
  if new.weekly_dinner_id is not null and exists(select 1 from public.weekly_dinners
    where id=new.weekly_dinner_id and (status='cancelled' or (status='closed' and new.status='draft'))) then
    raise exception 'Jantar cancelado ou encerrado operacionalmente.';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION bob_dinner_private.snapshot_line()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s public.bar_sales%rowtype; product public.products%rowtype; is_meal boolean;
begin
  if TG_OP in ('UPDATE','DELETE') and exists(
    select 1 from public.bar_sales where id=old.sale_id and status in ('completed','reversed')) then
    raise exception 'As linhas de uma venda concluída são imutáveis.';
  end if;
  select * into s from public.bar_sales where id=case when TG_OP='DELETE' then old.sale_id else new.sale_id end;
  if s.status in ('completed','reversed') then
    raise exception 'As linhas de uma venda concluída são imutáveis.';
  end if;
  if TG_OP='DELETE' then return old; end if;
  if s.club_id is distinct from new.club_id then raise exception 'Clube da venda inválido.'; end if;
  -- V2 takes the product lock before insertion. This trigger snapshots the SAME
  -- weighted-average consumption unit cost, including doses/conversion factors.
  -- It also protects new sales completed by legacy V2 clients, without overloads.
  if new.item_kind='stock' then
    select * into product from public.products where id=new.product_id and club_id=new.club_id for update;
    if not found then raise exception 'Produto inválido.'; end if;
    new.unit_cost_snapshot:=product.cost;
    new.cost_total_snapshot:=round(new.quantity*coalesce(new.stock_quantity_per_unit,1)*product.cost,2);
    new.dinner_component_snapshot:='bar';
  elsif new.item_kind='preset' then
    select counts_as_dinner_meal into is_meal from public.bar_sale_presets
      where id=new.preset_id and club_id=new.club_id;
    if not found then raise exception 'Preset inválido.'; end if;
    new.unit_cost_snapshot:=null; new.cost_total_snapshot:=null;
    new.dinner_component_snapshot:=case when is_meal then 'meal' else 'excluded' end;
  else
    -- Explicitly excluded: neither a meal nor a stock beverage. Display the
    -- excluded revenue separately; never silently inflate beverage revenue.
    new.unit_cost_snapshot:=null; new.cost_total_snapshot:=null;
    new.dinner_component_snapshot:='excluded';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.acknowledge_event_task_v1(p_assignment uuid, p_complete boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v public.event_task_assignees%rowtype;
  v_profile uuid;
begin
  if (select auth.uid()) is null then
    raise exception 'Autenticação necessária.';
  end if;
  select * into v
  from public.event_task_assignees
  where id = p_assignment
  for update;
  if not found then
    raise exception 'Atribuição não encontrada.';
  end if;
  if v.member_id is not null then
    select m.profile_id into v_profile
    from public.members m
    where m.id = v.member_id;
    if v_profile is distinct from (select auth.uid())
       and not public.has_club_permission(v.club_id, 'manageEventOperations') then
      raise exception 'Sem permissão para atualizar esta tarefa.';
    end if;
  elsif not public.has_club_permission(v.club_id, 'manageEventOperations') then
    raise exception 'Sem permissão para atualizar esta tarefa.';
  end if;
  update public.event_task_assignees
  set acknowledged_at = coalesce(acknowledged_at, now()),
      completed_at = case when p_complete then now() else completed_at end
  where id = p_assignment;
  if p_complete then
    update public.event_tasks
    set status = 'done',
        completed_at = coalesce(completed_at, now()),
        updated_at = now()
    where id = v.task_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.activity_event_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d text;
begin
  d:=case when new.starts_at is null then coalesce(new.location,'') else to_char(new.starts_at at time zone 'Europe/Lisbon','DD/MM/YYYY HH24:MI')||case when new.location is null or trim(new.location)='' then '' else ' · '||new.location end end;
  if tg_op='INSERT' then
    perform public.emit_domain_event(new.club_id,'EventCreated','event',new.id,
      jsonb_build_object('title','Novo evento: '||new.name,'description',d,'route','events','priority','high','push',true));
  elsif new.name is distinct from old.name or new.starts_at is distinct from old.starts_at or new.location is distinct from old.location or new.status is distinct from old.status then
    perform public.emit_domain_event(new.club_id,'EventUpdated','event',new.id,
      jsonb_build_object('title','Evento atualizado: '||new.name,'description',d,'route','events','priority','normal','push',true));
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.activity_fee_payment_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_name text;
begin
  select full_name into v_name from public.members where id=new.member_id and club_id=new.club_id;
  perform public.emit_domain_event(new.club_id,'FeePaid','fee',new.id,jsonb_build_object('title','Quotas recebidas','description',coalesce(v_name,'Membro')||' · '||to_char(new.amount,'FM999999990D00')||' €','route','fees','priority','normal','amount',new.amount));
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.activity_stock_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_name text;
begin
  select name into v_name from public.products where id=new.product_id;
  perform public.emit_domain_event(new.club_id,'InventoryMovementCreated','inventory',new.id,
    jsonb_build_object('title','Movimento de inventário','description',coalesce(v_name,'Artigo')||' · '||new.quantity::text,'route','inventory','priority','low'));
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.activity_user_permission_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_club uuid; v_profile uuid;
begin
  if tg_op='DELETE' then
    v_club:=old.club_id; v_profile:=old.profile_id;
  else
    v_club:=new.club_id; v_profile:=new.profile_id;
  end if;
  perform public.emit_domain_event(v_club,'UserPermissionOverrideUpdated','permission',null,
    jsonb_build_object('title','Permissão individual atualizada','description','Foi alterada uma exceção individual de acesso.','route','settings','priority','low','profile_id',v_profile));
  if tg_op='DELETE' then return old; end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.add_fee_credit_adjustment_v1(target_club uuid, p_member uuid, p_amount numeric, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_balance numeric;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageFees') then raise exception 'Sem autorização para ajustar créditos.'; end if;
  if p_amount is null or p_amount=0 then raise exception 'O ajuste não pode ser zero.'; end if;
  if length(trim(coalesce(p_reason,'')))<3 then raise exception 'Indica o motivo do ajuste.'; end if;
  if not exists(select 1 from public.members where id=p_member and club_id=target_club) then raise exception 'Membro inválido.'; end if;
  select coalesce(sum(amount),0) into v_balance from public.fee_credits where club_id=target_club and member_id=p_member;
  if p_amount<0 and abs(p_amount)>v_balance then raise exception 'O ajuste deixaria o crédito negativo.'; end if;
  insert into public.fee_credits(club_id,member_id,amount,entry_type,reason) values(target_club,p_member,p_amount,'manual_adjustment',trim(p_reason)) returning id into v_id;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.add_financial_attachment_v1(target_club uuid, p_request uuid, p_kind text, p_storage_path text, p_original_file_name text, p_mime_type text, p_file_size bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.financial_requests%rowtype; v_id uuid; own_member uuid; manager boolean;
begin
  select * into r from public.financial_requests where id=p_request and club_id=target_club;
  if not found then raise exception 'Pedido não encontrado.'; end if;
  manager:=public.financial_manager_v1(target_club); own_member:=public.current_financial_member_v1(target_club);
  if not manager and r.member_id is distinct from own_member then raise exception 'Sem autorização.'; end if;
  if p_kind not in ('receipt','member_payment_proof','club_payment_proof','other') then raise exception 'Tipo de anexo inválido.'; end if;
  if p_file_size is null or p_file_size<=0 or p_file_size>20971520 then raise exception 'O ficheiro deve ter entre 1 byte e 20 MB.'; end if;
  if p_storage_path not like target_club::text||'/'||p_request::text||'/%' then raise exception 'Caminho de armazenamento inválido.'; end if;
  if p_kind='receipt' then
    if r.request_type<>'reimbursement' or r.status not in ('draft','needs_info') then raise exception 'Não é possível adicionar talões neste estado.'; end if;
  elsif p_kind='member_payment_proof' then
    if r.request_type<>'charge' or r.status<>'awaiting_payment' or r.member_id is distinct from own_member then raise exception 'Não é possível adicionar este comprovativo.'; end if;
  elsif p_kind='club_payment_proof' then
    if r.request_type<>'reimbursement' or r.status<>'approved' or not manager then raise exception 'O comprovativo de pagamento só pode ser anexado após aprovação.'; end if;
  elsif r.status in ('paid','rejected','cancelled') then raise exception 'O processo está encerrado.';
  end if;
  insert into public.financial_request_attachments(club_id,request_id,kind,storage_path,original_file_name,mime_type,file_size)
  values(target_club,p_request,p_kind,p_storage_path,coalesce(nullif(btrim(p_original_file_name),''),'ficheiro'),nullif(btrim(coalesce(p_mime_type,'')),''),p_file_size) returning id into v_id;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.add_financial_transaction_document_v1(target_club uuid, p_transaction uuid, p_document_type text, p_storage_path text, p_original_file_name text, p_mime_type text, p_file_size bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if auth.uid() is null or not (
    public.has_club_permission(target_club,'createTreasuryMovement')
    or public.has_club_permission(target_club,'approveExpenseRequests')
  ) then raise exception 'Sem autorização para gerir documentos financeiros.'; end if;

  if not exists(
    select 1 from public.treasury_transactions t
    where t.id=p_transaction and t.club_id=target_club
  ) then raise exception 'Movimento financeiro não encontrado.'; end if;

  if p_document_type not in ('receipt','payment_proof','invoice_other') then
    raise exception 'Categoria de documento inválida.';
  end if;
  if p_file_size is null or p_file_size<=0 or p_file_size>20971520 then
    raise exception 'O ficheiro deve ter entre 1 byte e 20 MB.';
  end if;
  if p_storage_path not like target_club::text||'/transactions/'||p_transaction::text||'/%' then
    raise exception 'Caminho de armazenamento inválido.';
  end if;

  insert into public.financial_transaction_documents(
    club_id,transaction_id,document_type,origin,storage_path,
    original_file_name,mime_type,file_size,is_primary
  ) values (
    target_club,p_transaction,p_document_type,'direct',p_storage_path,
    coalesce(nullif(btrim(p_original_file_name),''),'ficheiro'),
    nullif(btrim(coalesce(p_mime_type,'')),''),p_file_size,false
  ) returning id into v_id;

  perform public.refresh_financial_transaction_primary_v1(p_transaction);
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_fee_adjustment_v1(target_club uuid, p_obligation uuid, p_amount numeric, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.fee_obligations%rowtype; v_outstanding numeric; v_id uuid;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageFees') then raise exception 'Sem autorização para ajustar quotas.'; end if;
  if p_amount is null or p_amount=0 then raise exception 'O ajuste não pode ser zero.'; end if;
  if length(trim(coalesce(p_reason,'')))<3 then raise exception 'Indica o motivo do ajuste.'; end if;
  select * into v from public.fee_obligations where id=p_obligation and club_id=target_club for update;
  if not found then raise exception 'Quota não encontrada.'; end if;
  if v.status in('cancelled','exempt') then raise exception 'A quota não aceita ajustes.'; end if;
  v_outstanding:=public.fee_obligation_outstanding_v1(v);
  if p_amount<0 and abs(p_amount)>v_outstanding then raise exception 'A redução excede o saldo pendente.'; end if;
  insert into public.fee_adjustments(club_id,member_id,obligation_id,amount,reason)
  values(target_club,v.member_id,p_obligation,p_amount,trim(p_reason)) returning id into v_id;
  update public.fee_obligations set adjustment_amount=adjustment_amount+p_amount where id=p_obligation;
  perform public.refresh_fee_obligation_status_v1(p_obligation); return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_fee_credit_v1(target_club uuid, p_member uuid, p_obligation uuid, p_amount numeric, p_reason text DEFAULT NULL::text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_obligation public.fee_obligations%rowtype; v_outstanding numeric; v_balance numeric; v_remaining numeric:=coalesce(p_amount,0); v_use numeric; r record;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageFees') then raise exception 'Sem autorização para aplicar créditos.'; end if;
  if v_remaining<=0 then raise exception 'O valor deve ser superior a zero.'; end if;
  select * into v_obligation from public.fee_obligations where id=p_obligation and club_id=target_club and member_id=p_member for update;
  if not found then raise exception 'Quota não encontrada.'; end if;
  if v_obligation.status in('paid','exempt','cancelled') then raise exception 'A quota não aceita crédito.'; end if;
  v_outstanding:=public.fee_obligation_outstanding_v1(v_obligation);
  if v_remaining>v_outstanding then raise exception 'O crédito excede o saldo da quota.'; end if;
  select coalesce(sum(amount),0) into v_balance from public.fee_credits where club_id=target_club and member_id=p_member;
  if v_remaining>v_balance then raise exception 'Crédito disponível insuficiente.'; end if;
  for r in select c.id,c.amount+coalesce((select sum(x.amount) from public.fee_credits x where x.source_credit_id=c.id),0) available from public.fee_credits c
    where c.club_id=target_club and c.member_id=p_member and c.amount>0 and c.entry_type in('payment_excess','manual_adjustment') order by c.created_at,c.id for update
  loop
    exit when v_remaining<=0; if r.available<=0 then continue; end if; v_use:=least(v_remaining,r.available);
    insert into public.fee_credits(club_id,member_id,amount,entry_type,obligation_id,source_credit_id,reason)
    values(target_club,p_member,-v_use,'application',p_obligation,r.id,coalesce(nullif(trim(coalesce(p_reason,'')),''),'Aplicação de crédito em quota'));
    v_remaining:=v_remaining-v_use;
  end loop;
  if v_remaining>0 then raise exception 'Não foi possível consumir o crédito solicitado.'; end if;
  update public.fee_obligations set paid_amount=paid_amount+p_amount where id=p_obligation;
  perform public.refresh_fee_obligation_status_v1(p_obligation); return p_amount;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_fee_exemption_v1(target_club uuid, p_obligation uuid, p_amount numeric, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.fee_obligations%rowtype; v_outstanding numeric; v_id uuid;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageFees') then raise exception 'Sem autorização para aplicar isenções.'; end if;
  if p_amount is null or p_amount<=0 then raise exception 'O valor deve ser superior a zero.'; end if;
  if length(trim(coalesce(p_reason,'')))<3 then raise exception 'Indica o motivo da isenção.'; end if;
  select * into v from public.fee_obligations where id=p_obligation and club_id=target_club for update;
  if not found then raise exception 'Quota não encontrada.'; end if;
  if v.status in('paid','exempt','cancelled') then raise exception 'A quota não aceita isenção.'; end if;
  v_outstanding:=public.fee_obligation_outstanding_v1(v);
  if p_amount>v_outstanding then raise exception 'A isenção excede o saldo da quota.'; end if;
  insert into public.fee_exemptions(club_id,member_id,obligation_id,amount,reason)
  values(target_club,v.member_id,p_obligation,p_amount,trim(p_reason)) returning id into v_id;
  update public.fee_obligations set exempt_amount=exempt_amount+p_amount where id=p_obligation;
  perform public.refresh_fee_obligation_status_v1(p_obligation); return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_import_v1(target_club uuid, p_import uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_import public.imports%rowtype; r public.import_rows%rowtype; v_id uuid; v_updated timestamptz; v_count integer:=0; v_data jsonb;
begin
  if auth.uid() is null then raise exception 'Autenticação necessária.'; end if;
  select * into v_import from public.imports where id=p_import and club_id=target_club for update;
  if not found then raise exception 'Importação não encontrada.'; end if;
  if not public.import_target_allowed_v1(target_club,v_import.target) then raise exception 'Sem permissão.'; end if;
  if v_import.status<>'ready' or v_import.invalid_rows<>0 or v_import.total_rows<1 then raise exception 'A importação ainda não está pronta.'; end if;
  begin
    for r in select * from public.import_rows where import_id=p_import order by row_number loop
      v_data:=r.mapped_data;
      case v_import.target
        when 'members' then
          insert into public.members(club_id,member_number,full_name,nickname,email,phone,birth_date,joined_at,status,prospect_joined_at,full_colors_at,created_by,updated_by)
          values(target_club,nullif(btrim(v_data->>'member_number'),'')::integer,btrim(v_data->>'full_name'),nullif(btrim(v_data->>'nickname'),''),nullif(btrim(v_data->>'email'),''),nullif(btrim(v_data->>'phone'),''),public.import_parse_date_v1(v_data->>'birth_date'),public.import_parse_date_v1(v_data->>'joined_at'),coalesce(nullif(btrim(v_data->>'status'),''),'active')::public.member_status,public.import_parse_date_v1(v_data->>'prospect_joined_at'),public.import_parse_date_v1(v_data->>'full_colors_at'),auth.uid(),auth.uid()) returning id,updated_at into v_id,v_updated;
        when 'inventory_products' then
          insert into public.products(club_id,name,sku,category,unit,cost,sale_price,minimum_stock,active,inventory_area,description,supplier,institutional_delivery,purchase_unit,consumption_unit,units_per_purchase,purchase_cost,created_by,updated_by)
          values(target_club,btrim(v_data->>'name'),nullif(btrim(v_data->>'sku'),''),nullif(btrim(v_data->>'category'),''),coalesce(nullif(btrim(v_data->>'unit'),''),'unit'),public.import_parse_numeric_v1(v_data->>'cost',0),public.import_parse_numeric_v1(v_data->>'sale_price',0),public.import_parse_numeric_v1(v_data->>'minimum_stock',0),public.import_parse_boolean_v1(v_data->>'active',true),coalesce(nullif(btrim(v_data->>'inventory_area'),''),'shop'),nullif(btrim(v_data->>'description'),''),nullif(btrim(v_data->>'supplier'),''),public.import_parse_boolean_v1(v_data->>'institutional_delivery',false),nullif(btrim(v_data->>'purchase_unit'),''),nullif(btrim(v_data->>'consumption_unit'),''),public.import_parse_numeric_v1(v_data->>'units_per_purchase',1),public.import_parse_numeric_v1(v_data->>'purchase_cost',0),auth.uid(),auth.uid()) returning id,updated_at into v_id,v_updated;
        when 'events' then
          insert into public.events(club_id,name,description,location,starts_at,ends_at,status,capacity,budget,event_mode_enabled,created_by,updated_by)
          values(target_club,btrim(v_data->>'name'),nullif(btrim(v_data->>'description'),''),nullif(btrim(v_data->>'location'),''),public.import_parse_timestamptz_v1(v_data->>'starts_at'),public.import_parse_timestamptz_v1(v_data->>'ends_at'),coalesce(nullif(btrim(v_data->>'status'),''),'draft')::public.event_status,nullif(btrim(v_data->>'capacity'),'')::integer,public.import_parse_numeric_v1(v_data->>'budget',0),false,auth.uid(),auth.uid()) returning id,updated_at into v_id,v_updated;
        when 'fee_plans' then
          insert into public.fee_plans(club_id,name,amount,frequency,due_day,active,created_by,updated_by)
          values(target_club,btrim(v_data->>'name'),public.import_parse_numeric_v1(v_data->>'amount',0),coalesce(nullif(btrim(v_data->>'frequency'),''),'monthly'),nullif(btrim(v_data->>'due_day'),'')::integer,public.import_parse_boolean_v1(v_data->>'active',true),auth.uid(),auth.uid()) returning id,updated_at into v_id,v_updated;
        else raise exception 'Destino inválido.';
      end case;
      update public.import_rows set target_row_id=v_id,applied_snapshot=jsonb_build_object('updated_at_epoch',extract(epoch from v_updated)),applied_at=now(),updated_at=now() where id=r.id;
      v_count:=v_count+1;
    end loop;
  exception when others then
    update public.imports set status='failed',error_code='apply_failed',updated_at=now() where id=p_import;
    insert into public.audit_log(club_id,actor_id,entity_type,entity_id,action,after_data,data) values(target_club,auth.uid(),'import',p_import::text,'import_failed',jsonb_build_object('error_code','apply_failed'),jsonb_build_object('import_id',p_import));
    return jsonb_build_object('success',false,'error_code','apply_failed');
  end;
  update public.import_rows set source_data='{}'::jsonb where import_id=p_import;
  update public.imports set status='applied',applied_rows=v_count,error_code=null,applied_at=now(),updated_at=now() where id=p_import;
  insert into public.audit_log(club_id,actor_id,entity_type,entity_id,action,after_data,data) values(target_club,auth.uid(),'import',p_import::text,'import_applied',jsonb_build_object('target',v_import.target,'applied_rows',v_count),jsonb_build_object('import_id',p_import));
  return jsonb_build_object('success',true,'applied_rows',v_count);
end; $function$

CREATE OR REPLACE FUNCTION public.approve_cash_session_v1(target_club uuid, p_session uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_session public.cash_sessions%rowtype;
  v_transaction uuid;
  v_kind public.transaction_kind;
  v_amount numeric;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'approveCashDifferences') then
    raise exception 'Sem permissão para aprovar diferenças de caixa.';
  end if;
  if length(trim(coalesce(p_reason,'')))<3 then raise exception 'Indica o motivo da aprovação.'; end if;
  select * into v_session from public.cash_sessions
    where id=p_session and club_id=target_club for update;
  if not found then raise exception 'Sessão de caixa não encontrada.'; end if;
  if v_session.status<>'pending_approval' then raise exception 'A sessão não aguarda aprovação.'; end if;

  v_amount := abs(coalesce(v_session.difference_amount,0));
  if v_amount<0.005 then raise exception 'A sessão não tem diferença a regularizar.'; end if;
  v_kind := case when v_session.difference_amount>0 then 'income'::public.transaction_kind else 'expense'::public.transaction_kind end;

  insert into public.treasury_transactions(
    club_id,kind,account_id,transaction_date,description,amount,payment_method,
    notes,source_type,source_id,created_by
  ) values (
    target_club,v_kind,v_session.account_id,current_date,
    'Ajuste de caixa — sessão '||p_session::text,v_amount,'Dinheiro',trim(p_reason),
    'cash_session',p_session,auth.uid()
  ) returning id into v_transaction;

  update public.cash_sessions
    set status='closed',approved_at=now(),approved_by=auth.uid(),
        closing_notes=concat_ws(E'\n',closing_notes,'Aprovação: '||trim(p_reason))
    where id=p_session;
  return v_transaction;
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_event_proposal_v1(p_proposal uuid, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v public.event_proposals%rowtype;
  v_event uuid;
begin
  if (select auth.uid()) is null then raise exception 'Autenticação necessária.'; end if;
  select * into v from public.event_proposals where id = p_proposal for update;
  if not found then raise exception 'Proposta não encontrada.'; end if;
  if not public.has_club_permission(v.club_id, 'approveEventProposals') then
    raise exception 'Sem permissão para aprovar propostas.';
  end if;
  if v.status <> 'submitted' then raise exception 'A proposta já foi processada.'; end if;

  insert into public.events(
    club_id, name, description, location, starts_at, ends_at, status,
    event_mode_enabled, event_kind, is_private, created_by, updated_by
  ) values (
    v.club_id, v.name, v.description, v.location, coalesce(v.starts_at, now()), v.ends_at,
    'draft'::public.event_status, v.event_kind <> 'general', v.event_kind, true,
    (select auth.uid()), (select auth.uid())
  ) returning id into v_event;

  update public.event_proposals
  set status='approved', decision_notes=nullif(btrim(p_notes), ''), decided_by=(select auth.uid()),
      decided_at=now(), approved_event_id=v_event, updated_at=now(), updated_by=(select auth.uid())
  where id=p_proposal;
  return v_event;
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_member_motorcycle_v1(target_club uuid, p_member uuid, p_motorcycle uuid, p_retired_on date DEFAULT CURRENT_DATE)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_allowed boolean;
  v_was_primary boolean;
  v_next uuid;
begin
  if auth.uid() is null then raise exception 'Autenticação necessária.'; end if;
  select exists(
    select 1 from public.members m
    where m.id=p_member and m.club_id=target_club
      and (
        public.has_club_permission(target_club,'manageMembers')
        or (m.profile_id=auth.uid() and public.has_club_permission(target_club,'editOwnMemberProfile'))
      )
  ) into v_allowed;
  if not v_allowed then raise exception 'Sem permissão para gerir as motas deste membro.'; end if;

  select primary_motorcycle into v_was_primary
  from public.member_motorcycles
  where id=p_motorcycle and club_id=target_club and member_id=p_member and active=true
  for update;
  if not found then raise exception 'Mota ativa não encontrada.'; end if;

  update public.member_motorcycles
  set active=false,primary_motorcycle=false,retired_on=coalesce(p_retired_on,current_date),
      updated_at=now(),updated_by=auth.uid()
  where id=p_motorcycle;

  if v_was_primary then
    select id into v_next from public.member_motorcycles
    where club_id=target_club and member_id=p_member and active=true
    order by acquired_on desc nulls last,created_at desc
    limit 1;
    if v_next is not null then
      update public.member_motorcycles
      set primary_motorcycle=true,updated_at=now(),updated_by=auth.uid()
      where id=v_next;
    end if;
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.asset_loan_v1(target_club uuid, p_asset uuid, p_borrower_type text, p_member uuid DEFAULT NULL::uuid, p_event uuid DEFAULT NULL::uuid, p_external_name text DEFAULT NULL::text, p_expected_return timestamp with time zone DEFAULT NULL::timestamp with time zone, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_name text; begin
if not public.has_club_permission(target_club,'manageAssets') then raise exception 'Sem autorização para gerir património.'; end if;
select name into v_name from public.inventory_assets where id=p_asset and club_id=target_club and active=true for update;
if v_name is null then raise exception 'Bem patrimonial inválido.'; end if;
if exists(select 1 from public.asset_loans where asset_id=p_asset and returned_at is null) then raise exception 'Este bem já se encontra emprestado ou associado.'; end if;
if p_borrower_type not in ('member','external','event') then raise exception 'Tipo de destinatário inválido.'; end if;
insert into public.asset_loans(club_id,asset_id,borrower_type,member_id,event_id,external_name,expected_return_at,notes,created_by)
values(target_club,p_asset,p_borrower_type,p_member,p_event,nullif(trim(coalesce(p_external_name,'')),''),p_expected_return,nullif(trim(coalesce(p_notes,'')),''),auth.uid()) returning id into v_id;
insert into public.asset_events(club_id,asset_id,event_type,title,description,metadata,created_by)
values(target_club,p_asset,'loan','Bem emprestado / associado',nullif(trim(coalesce(p_notes,'')),''),jsonb_build_object('loan_id',v_id,'borrower_type',p_borrower_type,'expected_return_at',p_expected_return),auth.uid());
return v_id; end; $function$

CREATE OR REPLACE FUNCTION public.asset_maintenance_v1(target_club uuid, p_asset uuid, p_type text, p_date date, p_description text DEFAULT NULL::text, p_cost numeric DEFAULT 0, p_supplier text DEFAULT NULL::text, p_next_due date DEFAULT NULL::date, p_account uuid DEFAULT NULL::uuid, p_payment_method text DEFAULT NULL::text, p_post_financial boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_name text; v_tx uuid; v_account uuid; begin
if not public.has_club_permission(target_club,'manageAssets') then raise exception 'Sem autorização para gerir património.'; end if;
select name into v_name from public.inventory_assets where id=p_asset and club_id=target_club and active=true for update;
if v_name is null then raise exception 'Bem patrimonial inválido.'; end if;
if p_type not in ('maintenance','inspection','repair') then raise exception 'Tipo de intervenção inválido.'; end if;
if p_post_financial and coalesce(p_cost,0)>0 then
  if p_account is not null then select id into v_account from public.treasury_accounts where id=p_account and club_id=target_club and active=true;
  else select id into v_account from public.treasury_accounts where club_id=target_club and active=true and lower(name)='caixa' limit 1; end if;
  if v_account is null then raise exception 'Conta financeira inválida.'; end if;
  insert into public.treasury_transactions(club_id,kind,account_id,transaction_date,description,amount,payment_method,source_type,source_id,created_by)
  values(target_club,'expense',v_account,p_date,'Património - '||v_name,coalesce(p_cost,0),p_payment_method,'asset_maintenance',p_asset,auth.uid()) returning id into v_tx;
end if;
insert into public.asset_maintenance(club_id,asset_id,maintenance_date,maintenance_type,description,cost,supplier,next_due_date,account_id,payment_method,treasury_transaction_id,created_by)
values(target_club,p_asset,p_date,p_type,nullif(trim(coalesce(p_description,'')),''),coalesce(p_cost,0),nullif(trim(coalesce(p_supplier,'')),''),p_next_due,v_account,p_payment_method,v_tx,auth.uid()) returning id into v_id;
if p_type='inspection' then update public.inventory_assets set last_inspection_at=p_date,next_inspection_at=p_next_due,updated_at=now() where id=p_asset;
else update public.inventory_assets set last_maintenance_at=p_date,next_maintenance_at=p_next_due,condition=case when condition='maintenance' then 'good' else condition end,updated_at=now() where id=p_asset; end if;
insert into public.asset_events(club_id,asset_id,event_type,title,description,metadata,created_by)
values(target_club,p_asset,p_type,case p_type when 'inspection' then 'Inspeção registada' when 'repair' then 'Reparação registada' else 'Manutenção registada' end,nullif(trim(coalesce(p_description,'')),''),jsonb_build_object('maintenance_id',v_id,'cost',coalesce(p_cost,0),'next_due',p_next_due),auth.uid());
return v_id; end; $function$

CREATE OR REPLACE FUNCTION public.asset_return_v1(target_club uuid, p_loan uuid, p_condition text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_asset uuid; begin
if not public.has_club_permission(target_club,'manageAssets') then raise exception 'Sem autorização para gerir património.'; end if;
select asset_id into v_asset from public.asset_loans where id=p_loan and club_id=target_club and returned_at is null for update;
if v_asset is null then raise exception 'Empréstimo ativo não encontrado.'; end if;
update public.asset_loans set returned_at=now(),returned_condition=p_condition,return_notes=nullif(trim(coalesce(p_notes,'')),''),updated_at=now() where id=p_loan;
if p_condition in ('excellent','good','regular','maintenance','damaged') then update public.inventory_assets set condition=p_condition,updated_at=now() where id=v_asset; end if;
insert into public.asset_events(club_id,asset_id,event_type,title,description,metadata,created_by)
values(target_club,v_asset,'return','Bem devolvido',nullif(trim(coalesce(p_notes,'')),''),jsonb_build_object('loan_id',p_loan,'condition',p_condition),auth.uid());
end; $function$

CREATE OR REPLACE FUNCTION public.assign_bar_sale_dinner_v1(target_club uuid, p_sale uuid, p_dinner uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform bob_dinner_private.require_access(target_club,true);
  if p_dinner is not null and not exists(
    select 1 from public.weekly_dinners where id=p_dinner and club_id=target_club
  ) then raise exception 'Jantar inválido.'; end if;
  if not exists(select 1 from public.bar_sales where id=p_sale and club_id=target_club and status='completed') then
    raise exception 'Venda concluída não encontrada.';
  end if;
  -- trg_dinner_sale_guard locks both affected dinners and rejects closed ones.
  -- trg_audit_capture_v1 records the association update and actor.
  update public.bar_sales set weekly_dinner_id=p_dinner,updated_by=auth.uid(),updated_at=now()
    where id=p_sale and club_id=target_club;
end $function$

CREATE OR REPLACE FUNCTION public.attach_bar_ocr_source_v1(target_club uuid, p_job uuid, p_storage_path text, p_original_file_name text, p_mime_type text, p_file_size bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare j public.financial_ocr_jobs%rowtype;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageBar') then raise exception 'Sem autorização para usar OCR no Bar.'; end if;
  select * into j from public.financial_ocr_jobs where id=p_job and club_id=target_club and source_kind='bar_import' for update;
  if not found then raise exception 'Pedido OCR não encontrado.'; end if;
  if j.status not in ('draft','failed','unconfigured') then raise exception 'O pedido OCR já não aceita outro ficheiro.'; end if;
  if p_file_size is null or p_file_size<=0 or p_file_size>20971520 then raise exception 'O ficheiro deve ter entre 1 byte e 20 MB.'; end if;
  if lower(coalesce(p_mime_type,'')) not in ('image/jpeg','image/png','image/webp','application/pdf') then raise exception 'Formato OCR não suportado. Usa JPG, PNG, WEBP ou PDF.'; end if;
  if p_storage_path not like target_club::text||'/ocr/'||p_job::text||'/%' then raise exception 'Caminho OCR inválido.'; end if;
  update public.financial_ocr_jobs set storage_path=p_storage_path,original_file_name=coalesce(nullif(btrim(p_original_file_name),''),'documento'),mime_type=lower(p_mime_type),file_size=p_file_size,status='pending',error_message=null,started_at=null,completed_at=null where id=p_job;
end; $function$

CREATE OR REPLACE FUNCTION public.audit_capture_row_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_old jsonb; v_new jsonb; v_club uuid; v_actor uuid:=auth.uid(); v_entity_id text; v_action text;
begin
  v_old:=case when tg_op in ('UPDATE','DELETE') then public.audit_redact_json_v1(to_jsonb(old)) else null end;
  v_new:=case when tg_op in ('INSERT','UPDATE') then public.audit_redact_json_v1(to_jsonb(new)) else null end;
  v_club:=coalesce(nullif(v_new->>'club_id','')::uuid,nullif(v_old->>'club_id','')::uuid);
  if v_club is null then if tg_op='DELETE' then return old; else return new; end if; end if;
  v_entity_id:=coalesce(v_new->>'id',v_old->>'id',v_new->>'profile_id',v_old->>'profile_id',v_new->>'member_id',v_old->>'member_id',v_new->>'permission_key',v_old->>'permission_key',v_new->>'module_code',v_old->>'module_code');
  v_action:=case tg_op when 'INSERT' then 'created' when 'UPDATE' then 'updated' when 'DELETE' then 'deleted' else lower(tg_op) end;
  insert into public.audit_log(club_id,actor_id,action,entity_type,entity_id,before_data,after_data,created_at)
  values(v_club,v_actor,v_action,tg_table_name,v_entity_id,v_old,v_new,now());
  if tg_op='DELETE' then return old; end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.audit_stamp_row_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();
begin
  if tg_op='INSERT' then
    new.created_at:=now();
    if v_actor is not null then new.created_by:=v_actor; new.updated_by:=v_actor; end if;
    new.updated_at:=now();
    return new;
  end if;
  new.created_at:=old.created_at;
  new.created_by:=old.created_by;
  new.updated_at:=now();
  if v_actor is not null then new.updated_by:=v_actor; else new.updated_by:=old.updated_by; end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.bank_reconciliation_item_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_account uuid;
  v_period_start date;
  v_period_end date;
  v_status text;
  v_transaction_account uuid;
  v_transaction_destination uuid;
  v_transaction_date date;
begin
  select account_id, period_start, period_end, status
    into v_account, v_period_start, v_period_end, v_status
  from public.bank_reconciliations
  where id=new.reconciliation_id
    and club_id=new.club_id;

  if not found then
    raise exception 'A reconciliação não pertence ao clube.';
  end if;
  if v_status <> 'draft' then
    raise exception 'A reconciliação já está fechada.';
  end if;

  select account_id, destination_account_id, transaction_date
    into v_transaction_account, v_transaction_destination, v_transaction_date
  from public.treasury_transactions
  where id=new.transaction_id
    and club_id=new.club_id;

  if not found then
    raise exception 'O movimento não pertence ao clube.';
  end if;
  if v_transaction_date < v_period_start or v_transaction_date > v_period_end then
    raise exception 'O movimento está fora do período da reconciliação.';
  end if;
  if v_transaction_account is distinct from v_account
     and v_transaction_destination is distinct from v_account then
    raise exception 'O movimento não pertence à conta da reconciliação.';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.bar_operation_v1(target_club uuid, p_product uuid, p_operation text, p_quantity numeric, p_event uuid DEFAULT NULL::uuid, p_purchase_units numeric DEFAULT NULL::numeric, p_unit_price numeric DEFAULT NULL::numeric, p_payment_method text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_post_financial boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_product public.products%rowtype;
  v_delta numeric;
  v_new_stock numeric;
  v_total numeric:=0;
  v_kind public.stock_movement_kind;
  v_account uuid;
  v_cost_center uuid;
  v_tx uuid;
  v_desc text;
  v_purchase_unit_cost numeric;
  v_new_average_cost numeric;
begin
  if not public.has_club_permission(target_club,'manageBar') then raise exception 'Sem autorização para gerir o Bar.'; end if;
  if p_quantity<=0 then raise exception 'A quantidade deve ser superior a zero.'; end if;

  select * into v_product
  from public.products
  where id=p_product and club_id=target_club and inventory_area='bar' and active=true
  for update;
  if not found then raise exception 'Artigo de Bar não encontrado ou inativo.'; end if;

  if p_event is not null and not exists(select 1 from public.events where id=p_event and club_id=target_club) then
    raise exception 'Evento inválido.';
  end if;

  if p_operation in ('purchase','adjustment_in') then v_delta:=p_quantity; else v_delta:=-p_quantity; end if;
  v_new_stock:=coalesce(v_product.current_stock,0)+v_delta;
  if v_new_stock<0 then raise exception 'Stock insuficiente. Disponível: %',coalesce(v_product.current_stock,0); end if;

  if p_operation='purchase' then
    v_kind:='purchase';
  elsif p_operation='sale' then
    v_kind:='sale';
  elsif p_operation='waste' then
    v_kind:='loss';
  elsif p_operation in ('offer','internal') then
    v_kind:='event_consumption';
  else
    v_kind:='adjustment';
  end if;

  v_total:=case
    when p_operation='purchase' then coalesce(p_purchase_units,0)*coalesce(p_unit_price,v_product.purchase_cost,0)
    when p_operation='sale' then p_quantity*coalesce(p_unit_price,v_product.sale_price,0)
    else 0
  end;

  if p_operation='purchase' then
    if coalesce(v_product.units_per_purchase,0)<=0 then raise exception 'Conversão da unidade de compra inválida.'; end if;
    v_purchase_unit_cost:=coalesce(p_unit_price,v_product.purchase_cost,0) / v_product.units_per_purchase;
    if v_new_stock>0 then
      v_new_average_cost:=((coalesce(v_product.current_stock,0)*coalesce(v_product.cost,0)) + (p_quantity*v_purchase_unit_cost)) / v_new_stock;
    else
      v_new_average_cost:=v_purchase_unit_cost;
    end if;
    update public.products
      set current_stock=v_new_stock,
          purchase_cost=coalesce(p_unit_price,purchase_cost),
          cost=v_new_average_cost
      where id=v_product.id;
  else
    update public.products set current_stock=v_new_stock where id=v_product.id;
  end if;

  insert into public.stock_movements(club_id,product_id,event_id,kind,quantity,unit_cost,notes,created_by)
  values(
    target_club,p_product,p_event,v_kind,v_delta,
    case when p_operation='purchase' then v_purchase_unit_cost else coalesce(v_product.cost,0) end,
    nullif(trim(coalesce(p_notes,'')),''),auth.uid()
  );

  v_desc:=case p_operation
    when 'purchase' then 'Compra Bar - '
    when 'sale' then 'Venda Bar - '
    when 'offer' then 'Oferta Bar - '
    when 'internal' then 'Consumo interno Bar - '
    when 'waste' then 'Quebra Bar - '
    else 'Ajuste Bar - '
  end || v_product.name;

  if p_post_financial and p_operation in ('purchase','sale') and v_total>0 then
    select id into v_account from public.treasury_accounts
      where club_id=target_club and active=true and lower(name)=lower('Club House') limit 1;
    if v_account is null then raise exception 'Conta Club House não encontrada.'; end if;
    select id into v_cost_center from public.cost_centers
      where club_id=target_club and active=true and lower(name)=lower('Club House') limit 1;
    insert into public.treasury_transactions(
      club_id,kind,account_id,cost_center_id,event_id,transaction_date,description,amount,payment_method,source_type,source_id,created_by
    ) values(
      target_club,
      case when p_operation='sale' then 'income'::public.transaction_kind else 'expense'::public.transaction_kind end,
      v_account,v_cost_center,p_event,current_date,v_desc,v_total,p_payment_method,'bar_operation',p_product,auth.uid()
    ) returning id into v_tx;
  end if;

  insert into public.bar_operations(
    club_id,product_id,event_id,operation_type,purchase_units,consumption_quantity,unit_price,total_amount,payment_method,notes,treasury_transaction_id,created_by
  ) values(
    target_club,p_product,p_event,p_operation,p_purchase_units,p_quantity,coalesce(p_unit_price,0),v_total,p_payment_method,
    nullif(trim(coalesce(p_notes,'')),''),v_tx,auth.uid()
  );

  perform public.emit_domain_event(
    target_club,'BarOperationRecorded','inventory',p_product,
    jsonb_build_object(
      'title',v_desc,
      'description',p_quantity::text||' '||coalesce(v_product.consumption_unit,v_product.unit,'unid.'),
      'module_code','inventory','route','inventory',
      'priority',case when v_new_stock<=coalesce(v_product.minimum_stock,0) then 'medium' else 'low' end
    )
  );

  return jsonb_build_object(
    'product_id',p_product,
    'current_stock',v_new_stock,
    'average_unit_cost',case when p_operation='purchase' then v_new_average_cost else coalesce(v_product.cost,0) end,
    'transaction_id',v_tx
  );
end; $function$

CREATE OR REPLACE FUNCTION public.bar_operation_v2(target_club uuid, p_product uuid, p_operation text, p_quantity numeric, p_event uuid DEFAULT NULL::uuid, p_purchase_units numeric DEFAULT NULL::numeric, p_unit_price numeric DEFAULT NULL::numeric, p_payment_method text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_post_financial boolean DEFAULT true, p_account uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_product public.products%rowtype;
  v_delta numeric;
  v_new_stock numeric;
  v_total numeric:=0;
  v_kind public.stock_movement_kind;
  v_account uuid;
  v_cost_center uuid;
  v_tx uuid;
  v_desc text;
  v_purchase_unit_cost numeric;
  v_new_average_cost numeric;
begin
  if not public.has_club_permission(target_club,'manageBar') then
    raise exception 'Sem autorização para gerir o Bar.';
  end if;
  if p_quantity<=0 then raise exception 'A quantidade deve ser superior a zero.'; end if;

  select * into v_product
  from public.products
  where id=p_product and club_id=target_club and inventory_area='bar' and active=true
  for update;
  if not found then raise exception 'Artigo de Bar não encontrado ou inativo.'; end if;

  if p_event is not null and not exists(select 1 from public.events where id=p_event and club_id=target_club) then
    raise exception 'Evento inválido.';
  end if;

  if p_operation in ('purchase','adjustment_in') then v_delta:=p_quantity; else v_delta:=-p_quantity; end if;
  v_new_stock:=coalesce(v_product.current_stock,0)+v_delta;
  if v_new_stock<0 then raise exception 'Stock insuficiente. Disponível: %',coalesce(v_product.current_stock,0); end if;

  if p_operation='purchase' then v_kind:='purchase';
  elsif p_operation='sale' then v_kind:='sale';
  elsif p_operation='waste' then v_kind:='loss';
  elsif p_operation in ('offer','internal') then v_kind:='event_consumption';
  else v_kind:='adjustment'; end if;

  v_total:=case
    when p_operation='purchase' then coalesce(p_purchase_units,0)*coalesce(p_unit_price,v_product.purchase_cost,0)
    when p_operation='sale' then p_quantity*coalesce(p_unit_price,v_product.sale_price,0)
    else 0
  end;

  if p_operation='purchase' then
    if coalesce(v_product.units_per_purchase,0)<=0 then raise exception 'Conversão da embalagem de compra inválida.'; end if;
    v_purchase_unit_cost:=coalesce(p_unit_price,v_product.purchase_cost,0)/v_product.units_per_purchase;
    if v_new_stock>0 then
      v_new_average_cost:=((coalesce(v_product.current_stock,0)*coalesce(v_product.cost,0))+(p_quantity*v_purchase_unit_cost))/v_new_stock;
    else
      v_new_average_cost:=v_purchase_unit_cost;
    end if;
    update public.products
      set current_stock=v_new_stock,
          purchase_cost=coalesce(p_unit_price,purchase_cost),
          cost=v_new_average_cost
      where id=v_product.id;
  else
    update public.products set current_stock=v_new_stock where id=v_product.id;
  end if;

  insert into public.stock_movements(club_id,product_id,event_id,kind,quantity,unit_cost,notes,created_by)
  values(target_club,p_product,p_event,v_kind,v_delta,
    case when p_operation='purchase' then v_purchase_unit_cost else coalesce(v_product.cost,0) end,
    nullif(trim(coalesce(p_notes,'')),''),auth.uid());

  v_desc:=case p_operation
    when 'purchase' then 'Compra Bar - '
    when 'sale' then 'Venda Bar - '
    when 'offer' then 'Oferta Bar - '
    when 'internal' then 'Consumo interno Bar - '
    when 'waste' then 'Quebra Bar - '
    else 'Ajuste Bar - '
  end || v_product.name;

  if p_post_financial and p_operation in ('purchase','sale') and v_total>0 then
    if p_account is not null then
      if not public.has_club_permission(target_club,'selectBarFinancialAccount') then
        raise exception 'Sem autorização para escolher a conta financeira do Bar.';
      end if;
      select id into v_account from public.treasury_accounts
      where id=p_account and club_id=target_club and active=true;
      if v_account is null then raise exception 'Conta financeira inválida ou inativa.'; end if;
    else
      select id into v_account from public.treasury_accounts
      where club_id=target_club and active=true and lower(name)=lower('Caixa') limit 1;
      if v_account is null then
        select id into v_account from public.treasury_accounts
        where club_id=target_club and active=true order by created_at limit 1;
      end if;
      if v_account is null then raise exception 'Não existe nenhuma conta financeira ativa.'; end if;
    end if;

    select id into v_cost_center from public.cost_centers
    where club_id=target_club and active=true and lower(name)=lower('Club House') limit 1;

    insert into public.treasury_transactions(
      club_id,kind,account_id,cost_center_id,event_id,transaction_date,description,amount,payment_method,source_type,source_id,created_by
    ) values(
      target_club,
      case when p_operation='sale' then 'income'::public.transaction_kind else 'expense'::public.transaction_kind end,
      v_account,v_cost_center,p_event,current_date,v_desc,v_total,p_payment_method,'bar_operation',p_product,auth.uid()
    ) returning id into v_tx;
  end if;

  insert into public.bar_operations(
    club_id,product_id,event_id,operation_type,purchase_units,consumption_quantity,unit_price,total_amount,payment_method,notes,treasury_transaction_id,created_by
  ) values(
    target_club,p_product,p_event,p_operation,p_purchase_units,p_quantity,coalesce(p_unit_price,0),v_total,p_payment_method,
    nullif(trim(coalesce(p_notes,'')),''),v_tx,auth.uid()
  );

  perform public.emit_domain_event(
    target_club,'BarOperationRecorded','bar',p_product,
    jsonb_build_object('title',v_desc,'description',p_quantity::text||' '||coalesce(v_product.consumption_unit,v_product.unit,'unid.'),
      'module_code','bar','route','bar','priority',case when v_new_stock<=coalesce(v_product.minimum_stock,0) then 'medium' else 'low' end)
  );

  return jsonb_build_object(
    'product_id',p_product,'current_stock',v_new_stock,
    'average_unit_cost',case when p_operation='purchase' then v_new_average_cost else coalesce(v_product.cost,0) end,
    'transaction_id',v_tx,'account_id',v_account
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.begin_club_export_v1(target_club uuid, p_modules text[], p_include_sensitive boolean DEFAULT false, p_include_files boolean DEFAULT false, p_manifest_version text DEFAULT 'bob-export-v1'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_export uuid;
  v_modules text[];
  v_version text := coalesce(nullif(btrim(p_manifest_version), ''), 'bob-export-v1');
  v_allowed constant text[] := array[
    'members','treasury','financial','fees','lottery','events','inventory',
    'documents','communication','agenda','weekly_officer','configuration','audit'
  ]::text[];
begin
  if auth.uid() is null then
    raise exception 'Autenticação necessária.';
  end if;

  if not public.has_club_role(
    target_club,
    array['president','vice_president','admin','administrator','super_admin']::text[]
  ) then
    raise exception 'Sem permissão para exportação integral.';
  end if;

  select array_agg(module_key order by module_key)
    into v_modules
  from (
    select distinct btrim(value) as module_key
    from unnest(coalesce(p_modules, array[]::text[])) as value
    where value is not null and btrim(value) <> ''
  ) normalized;

  if coalesce(cardinality(v_modules), 0) = 0 then
    raise exception 'Seleciona pelo menos uma área para exportar.';
  end if;

  if exists (
    select 1
    from unnest(v_modules) as module_key
    where not (module_key = any(v_allowed))
  ) then
    raise exception 'A exportação contém uma área inválida.';
  end if;

  if length(v_version) > 32 or v_version !~ '^[A-Za-z0-9._-]+$' then
    raise exception 'Versão do manifesto inválida.';
  end if;

  if coalesce(p_include_sensitive, false) and not (
    public.has_club_permission(target_club, 'viewEmergencyData')
    and public.has_club_permission(target_club, 'viewSensitiveDocuments')
  ) then
    raise exception 'Sem permissão para incluir dados altamente sensíveis.';
  end if;

  insert into public.exports (
    club_id, requested_by, status, modules, include_sensitive, include_files,
    manifest_version
  ) values (
    target_club, auth.uid(), 'running', v_modules,
    coalesce(p_include_sensitive, false), coalesce(p_include_files, false),
    v_version
  )
  returning id into v_export;

  insert into public.audit_log (
    club_id, actor_id, action, entity_type, entity_id, after_data, data, created_at
  ) values (
    target_club,
    auth.uid(),
    'club_export_started',
    'club_export',
    v_export::text,
    jsonb_build_object(
      'status', 'running',
      'modules', to_jsonb(v_modules),
      'include_sensitive', coalesce(p_include_sensitive, false),
      'include_files', coalesce(p_include_files, false),
      'manifest_version', v_version
    ),
    jsonb_build_object('export_id', v_export),
    now()
  );

  return v_export;
end;
$function$

CREATE OR REPLACE FUNCTION public.begin_import_v1(target_club uuid, p_target text, p_source_filename text, p_source_format text, p_mapping jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_name text:=left(coalesce(nullif(btrim(p_source_filename),''),'importacao'),180); v_format text:=lower(coalesce(nullif(btrim(p_source_format),''),''));
begin
  if auth.uid() is null then raise exception 'Autenticação necessária.'; end if;
  if not public.import_target_allowed_v1(target_club,p_target) then raise exception 'Sem permissão para este destino de importação.'; end if;
  if v_format not in ('csv','xlsx') then raise exception 'Formato de importação inválido.'; end if;
  if p_mapping is null or jsonb_typeof(p_mapping)<>'object' then raise exception 'Mapeamento inválido.'; end if;
  insert into public.imports(club_id,requested_by,target,source_filename,source_format,mapping) values(target_club,auth.uid(),p_target,v_name,v_format,p_mapping) returning id into v_id;
  insert into public.audit_log(club_id,actor_id,entity_type,entity_id,action,after_data,data) values(target_club,auth.uid(),'import',v_id::text,'import_started',jsonb_build_object('target',p_target,'source_format',v_format),jsonb_build_object('import_id',v_id));
  return v_id;
end; $function$

CREATE OR REPLACE FUNCTION public.bootstrap_document_version_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if new.storage_path is null or new.storage_path='' then return new; end if;
  insert into public.document_versions(club_id,document_id,version_no,version_label,storage_path,original_file_name,mime_type,file_size,created_by)
  values(new.club_id,new.id,1,coalesce(nullif(new.version,''),'1.0'),new.storage_path,new.original_file_name,new.mime_type,coalesce(new.file_size,0),coalesce(new.created_by,(select auth.uid())))
  returning id into v_id;
  update public.documents set current_version_id=v_id,version=coalesce(nullif(new.version,''),'1.0') where id=new.id;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_agenda_item_v1(target_club uuid, p_item uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_old jsonb; v_new jsonb;
begin
  if not public.can_manage_agenda_v1(target_club) then raise exception 'Sem autorização para gerir a Agenda.'; end if;
  select to_jsonb(a) into v_old from public.agenda_items a where a.id=p_item and a.club_id=target_club;
  if v_old is null then raise exception 'Item da Agenda não encontrado.'; end if;
  update public.agenda_items set status='cancelled',updated_at=now(),updated_by=(select auth.uid()) where id=p_item and club_id=target_club;
  select to_jsonb(a) into v_new from public.agenda_items a where a.id=p_item;
  perform public.audit_event(target_club,'agenda_item_cancelled','agenda_item',p_item::text,v_old,v_new,p_reason);
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_reported_fee_payment_v1(target_club uuid, p_report uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.reported_payments%rowtype;
begin
  if auth.uid() is null then raise exception 'Sessão inválida.'; end if;
  select * into v from public.reported_payments where id=p_report and club_id=target_club for update;
  if not found then raise exception 'Pagamento comunicado não encontrado.'; end if;
  if v.status<>'pending' then raise exception 'Só é possível cancelar pagamentos pendentes.'; end if;
  if not exists(select 1 from public.members m where m.id=v.member_id and m.club_id=target_club and m.profile_id=auth.uid()) and not public.has_club_permission(target_club,'manageFees') then raise exception 'Sem autorização para cancelar este pagamento.'; end if;
  update public.reported_payments set status='cancelled' where id=p_report;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_treasury_obligation_v1(target_club uuid, p_obligation_type text, p_obligation uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_settled numeric;
  v_status text;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageTreasuryPlanning') then
    raise exception 'Sem permissão para cancelar obrigações financeiras.';
  end if;
  if length(trim(coalesce(p_reason,''))) < 3 then raise exception 'Indica o motivo do cancelamento.'; end if;

  if p_obligation_type='payable' then
    select settled_amount,status into v_settled,v_status from public.payables
      where id=p_obligation and club_id=target_club for update;
    if not found then raise exception 'Conta a pagar não encontrada.'; end if;
    if v_settled > 0 then raise exception 'Uma obrigação com liquidações não pode ser cancelada.'; end if;
    if v_status='cancelled' then return; end if;
    update public.payables
      set status='cancelled',cancelled_at=now(),cancelled_by=auth.uid(),
          notes=concat_ws(E'\n',notes,'Cancelado: '||trim(p_reason))
      where id=p_obligation;
  elsif p_obligation_type='receivable' then
    select settled_amount,status into v_settled,v_status from public.receivables
      where id=p_obligation and club_id=target_club for update;
    if not found then raise exception 'Conta a receber não encontrada.'; end if;
    if v_settled > 0 then raise exception 'Uma obrigação com liquidações não pode ser cancelada.'; end if;
    if v_status='cancelled' then return; end if;
    update public.receivables
      set status='cancelled',cancelled_at=now(),cancelled_by=auth.uid(),
          notes=concat_ws(E'\n',notes,'Cancelado: '||trim(p_reason))
      where id=p_obligation;
  else
    raise exception 'Tipo de obrigação inválido.';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_weekly_officer_swap_v1(target_club uuid, p_request uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_member uuid; v_row public.weekly_officer_swap_requests%rowtype;
begin
  v_member:=public.current_weekly_officer_member_v1(target_club);
  select * into v_row from public.weekly_officer_swap_requests where id=p_request and club_id=target_club and status='pending' for update;
  if not found then raise exception 'Pedido pendente não encontrado.'; end if;
  if v_member is distinct from v_row.requester_member_id and not public.can_manage_weekly_officer_v1(target_club) then raise exception 'Sem autorização para cancelar este pedido.'; end if;
  update public.weekly_officer_swap_requests set status='cancelled',updated_at=now(),updated_by=(select auth.uid()) where id=p_request;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_push_delivery_v1(p_delivery uuid, p_dispatch_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.push_deliveries%rowtype;
declare n public.notifications%rowtype;
declare dev public.push_devices%rowtype;
declare v_push_enabled boolean;
begin
  select * into d from public.push_deliveries
   where id=p_delivery and dispatch_token=p_dispatch_token
   for update;
  if d.id is null or d.status<>'pending' then return null; end if;

  select * into n from public.notifications where id=d.notification_id;
  select * into dev from public.push_devices where id=d.push_device_id;

  if n.id is null or dev.id is null or not dev.active or nullif(btrim(coalesce(dev.push_token,'')),'') is null then
    update public.push_deliveries set status='skipped',last_error='Dispositivo push indisponivel.',updated_at=now() where id=d.id;
    return null;
  end if;

  select coalesce((
    select np.push_enabled from public.notification_preferences np
     where np.club_id=d.club_id and np.profile_id=d.profile_id and np.module_code=coalesce(n.module_code,'general')
  ),true) into v_push_enabled;
  if not v_push_enabled then
    update public.push_deliveries set status='skipped',last_error='Push desativado nas preferencias.',updated_at=now() where id=d.id;
    return null;
  end if;

  update public.push_deliveries
     set status='processing',attempt_count=attempt_count+1,last_error=null,updated_at=now()
   where id=d.id;

  return jsonb_build_object(
    'delivery_id',d.id,
    'notification_id',n.id,
    'push_device_id',dev.id,
    'push_token',dev.push_token,
    'title',n.title,
    'body',n.body,
    'priority',n.priority,
    'module_code',coalesce(n.module_code,'general'),
    'entity_type',n.entity_type,
    'entity_id',n.entity_id,
    'action_route',n.action_route
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.classify_weekly_dinner_sale_item_v1(target_club uuid, p_dinner uuid, p_sale_item uuid, p_component text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare item public.bar_sale_items%rowtype; begin
  perform bob_dinner_private.require_access(target_club,true);
  -- Share the dinner lock with close/reopen and sale association changes.
  -- Do not lock sale rows after dinner rows: sale triggers use the reverse order.
  perform 1 from public.weekly_dinners where id=p_dinner and club_id=target_club for update;
  if not found then raise exception 'Jantar não encontrado neste clube.'; end if;
  if exists(select 1 from public.weekly_dinner_finances where dinner_id=p_dinner and financial_status='closed') then
    raise exception 'Reabre o fecho financeiro antes de alterar classificações.'; end if;
  select i.* into item from public.bar_sale_items i join public.bar_sales s
    on s.id=i.sale_id and s.club_id=i.club_id
    where i.id=p_sale_item and i.club_id=target_club and s.weekly_dinner_id=p_dinner and s.status='completed';
  if not found then raise exception 'Linha de venda não encontrada neste jantar.'; end if;
  if item.dinner_component_snapshot is distinct from 'excluded' or item.line_total<=0 then
    raise exception 'Apenas receita originalmente por classificar pode ser corrigida.'; end if;
  if p_component is null then
    delete from public.weekly_dinner_sale_item_classifications
      where club_id=target_club and dinner_id=p_dinner and sale_item_id=p_sale_item;
    return;
  end if;
  if p_component not in ('meal','bar') then raise exception 'Classificação financeira inválida.'; end if;
  if p_component='bar' and (item.cost_total_snapshot is null or item.cost_total_snapshot<0
    or item.cost_total_snapshot::text in ('NaN','Infinity','-Infinity')) then
    raise exception 'Não é possível classificar como BAR sem custo histórico de stock fiável.'; end if;
  insert into public.weekly_dinner_sale_item_classifications(club_id,dinner_id,sale_item_id,component_override,created_by,updated_by)
    values(target_club,p_dinner,p_sale_item,p_component,auth.uid(),auth.uid())
    on conflict(dinner_id,sale_item_id) do update set component_override=excluded.component_override,
      updated_at=now(),updated_by=auth.uid();
end $function$

CREATE OR REPLACE FUNCTION public.close_bank_reconciliation_v1(target_club uuid, p_reconciliation uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rec public.bank_reconciliations%rowtype;
  v_book numeric;
  v_difference numeric;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageTreasuryPlanning') then
    raise exception 'Sem permissão para fechar reconciliações.';
  end if;
  select * into v_rec from public.bank_reconciliations
    where id=p_reconciliation and club_id=target_club for update;
  if not found then raise exception 'Reconciliação não encontrada.'; end if;
  if v_rec.status<>'draft' then raise exception 'A reconciliação já está fechada.'; end if;

  select a.opening_balance + coalesce(sum(
    case
      when t.kind='income' and t.account_id=a.id then t.amount
      when t.kind='expense' and t.account_id=a.id then -t.amount
      when t.kind='transfer' and t.account_id=a.id then -t.amount
      when t.kind='transfer' and t.destination_account_id=a.id then t.amount
      else 0
    end
  ),0)
  into v_book
  from public.treasury_accounts a
  left join public.treasury_transactions t
    on t.club_id=a.club_id
   and t.transaction_date<=v_rec.period_end
   and (t.account_id=a.id or t.destination_account_id=a.id)
  where a.id=v_rec.account_id and a.club_id=target_club
  group by a.id,a.opening_balance;

  v_difference := v_rec.statement_closing_balance-coalesce(v_book,0);
  update public.bank_reconciliations
    set book_closing_balance=coalesce(v_book,0),difference_amount=v_difference,
        status='closed',closed_at=now(),closed_by=auth.uid()
    where id=p_reconciliation;
  return v_difference;
end;
$function$

CREATE OR REPLACE FUNCTION public.close_cash_session_v1(target_club uuid, p_session uuid, p_counted_amount numeric, p_notes text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_session public.cash_sessions%rowtype;
  v_expected numeric;
  v_difference numeric;
  v_status text;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageCashSessions') then
    raise exception 'Sem permissão para fechar caixa.';
  end if;
  if p_counted_amount is null then raise exception 'Indica o valor contado no fecho.'; end if;
  select * into v_session from public.cash_sessions
    where id=p_session and club_id=target_club for update;
  if not found then raise exception 'Sessão de caixa não encontrada.'; end if;
  if v_session.status<>'open' then raise exception 'A sessão já não está aberta.'; end if;

  v_expected := public.treasury_account_balance_v1(v_session.account_id);
  v_difference := p_counted_amount-coalesce(v_expected,0);
  v_status := case when abs(v_difference)<0.005 then 'closed' else 'pending_approval' end;

  update public.cash_sessions
    set expected_amount=coalesce(v_expected,0),counted_amount=p_counted_amount,
        difference_amount=v_difference,closing_notes=p_notes,status=v_status,
        closed_at=now(),closed_by=auth.uid()
    where id=p_session;
  return v_status;
end;
$function$

