    when 'configuracao/excecoes_permissoes.csv' then
      v_section := 'configuration';
      v_sensitive := false;
      v_sql := 'select to_jsonb(row_data) from (select t.profile_id,t.permission_key,t.allowed,t.updated_at,t.created_at from public.user_permission_overrides t where t.club_id = $1 offset $2 limit $3) row_data';
    when 'auditoria/audit_log.csv' then
      v_section := 'audit';
      v_sensitive := false;
      v_sql := 'select to_jsonb(row_data) from (select t.id,t.actor_id,t.entity_type,t.entity_id,t.action,t.created_at from public.audit_log t where t.club_id = $1 order by t.created_at, t.id offset $2 limit $3) row_data';
    when 'auditoria/atividade.csv' then
      v_section := 'audit';
      v_sensitive := false;
      v_sql := 'select to_jsonb(row_data) from (select t.id,t.actor_id,t.activity_type,t.title,t.description,t.entity_type,t.entity_id,t.created_at from public.activity_feed t where t.club_id = $1 order by t.created_at, t.id offset $2 limit $3) row_data';
    else
      raise exception 'Dataset de exportação inválido.';
  end case;

  if not (v_section = any(v_export.modules)) then
    raise exception 'Dataset fora das áreas selecionadas.';
  end if;

  if v_sensitive and not v_export.include_sensitive then
    raise exception 'Dados sensíveis não autorizados nesta exportação.';
  end if;

  if v_sensitive and not (
    public.has_club_permission(target_club, 'viewEmergencyData')
    and public.has_club_permission(target_club, 'viewSensitiveDocuments')
  ) then
    raise exception 'Sem permissão para dados altamente sensíveis.';
  end if;

  return query execute v_sql using target_club, v_offset, v_limit;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_bar_sale_v1(target_club uuid, p_sale uuid, p_lines jsonb, p_payment_method text, p_account uuid DEFAULT NULL::uuid, p_customer_label text DEFAULT NULL::text, p_event uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_sale public.bar_sales%rowtype;
  r jsonb;
  v_kind text;
  v_product_id uuid;
  v_preset_id uuid;
  v_product public.products%rowtype;
  v_preset public.bar_sale_presets%rowtype;
  v_description text;
  v_quantity numeric;
  v_unit_price numeric;
  v_line_total numeric;
  v_total numeric:=0;
  v_account uuid;
  v_cost_center uuid;
  v_tx uuid;
  v_new_stock numeric;
  v_event uuid;
  v_customer text;
  v_notes text;
  v_line_count integer:=0;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageBar') then
    raise exception 'Sem autorização para concluir vendas no Bar.';
  end if;
  if p_lines is null or jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then
    raise exception 'Adiciona pelo menos um artigo à venda.';
  end if;
  if nullif(btrim(coalesce(p_payment_method,'')),'') is null then
    raise exception 'Seleciona o método de pagamento.';
  end if;

  select * into v_sale
  from public.bar_sales
  where id=p_sale and club_id=target_club
  for update;
  if not found then raise exception 'Venda do Bar não encontrada.'; end if;
  if v_sale.status<>'draft' then raise exception 'Esta venda já não está em rascunho.'; end if;

  v_event:=coalesce(p_event,v_sale.event_id);
  if v_event is not null and not exists(
    select 1 from public.events where id=v_event and club_id=target_club
  ) then raise exception 'Evento inválido.'; end if;
  v_customer:=nullif(btrim(coalesce(p_customer_label,v_sale.customer_label,'')),'');
  v_notes:=nullif(btrim(coalesce(p_notes,v_sale.notes,'')),'');

  for r in select value from jsonb_array_elements(p_lines)
  loop
    v_kind:=coalesce(nullif(btrim(r->>'kind'),''),'stock');
    begin
      v_quantity:=(r->>'quantity')::numeric;
    exception when others then
      raise exception 'Quantidade inválida numa linha da venda.';
    end;
    if v_quantity is null or v_quantity<=0 then
      raise exception 'Todas as quantidades têm de ser superiores a zero.';
    end if;

    if v_kind='stock' then
      begin v_product_id:=(r->>'product_id')::uuid;
      exception when others then raise exception 'Artigo de stock inválido.'; end;
      select * into v_product
      from public.products
      where id=v_product_id and club_id=target_club and inventory_area='bar' and active=true;
      if not found then raise exception 'Artigo do Bar inválido ou inativo.'; end if;
      v_unit_price:=coalesce(v_product.sale_price,0);
      v_description:=v_product.name;
    elsif v_kind='preset' then
      begin v_preset_id:=(r->>'preset_id')::uuid;
      exception when others then raise exception 'Item fixo inválido.'; end;
      select * into v_preset
      from public.bar_sale_presets
      where id=v_preset_id and club_id=target_club and active=true;
      if not found then raise exception 'Item fixo do Bar inválido ou inativo.'; end if;
      if coalesce(v_preset.unit_price,0)<=0 then
        raise exception 'Define primeiro o preço de %.',v_preset.name;
      end if;
      v_unit_price:=v_preset.unit_price;
      v_description:=v_preset.name;
    elsif v_kind='other' then
      v_description:=nullif(btrim(coalesce(r->>'description','')),'');
      if v_description is null then raise exception 'Indica a descrição do item Outro.'; end if;
      begin v_unit_price:=(r->>'unit_price')::numeric;
      exception when others then raise exception 'Preço inválido no item Outro.'; end;
      if v_unit_price is null or v_unit_price<0 then raise exception 'Preço inválido no item Outro.'; end if;
    else
      raise exception 'Tipo de linha de venda inválido.';
    end if;

    v_line_total:=round(v_quantity*v_unit_price,2);
    v_total:=v_total+v_line_total;
    v_line_count:=v_line_count+1;
  end loop;

  if v_total<=0 then raise exception 'O total da venda tem de ser superior a zero.'; end if;

  if p_account is not null then
    if not public.has_club_permission(target_club,'selectBarFinancialAccount') then
      raise exception 'Sem autorização para escolher a conta financeira do Bar.';
    end if;
    select id into v_account
    from public.treasury_accounts
    where id=p_account and club_id=target_club and active=true;
    if v_account is null then raise exception 'Conta financeira inválida ou inativa.'; end if;
  else
    select id into v_account
    from public.treasury_accounts
    where club_id=target_club and active=true and lower(name)=lower('Caixa')
    limit 1;
    if v_account is null then
      select id into v_account
      from public.treasury_accounts
      where club_id=target_club and active=true
      order by created_at
      limit 1;
    end if;
    if v_account is null then raise exception 'Não existe nenhuma conta financeira ativa.'; end if;
  end if;

  select id into v_cost_center
  from public.cost_centers
  where club_id=target_club and active=true and lower(name)=lower('Club House')
  limit 1;

  insert into public.treasury_transactions(
    club_id,kind,account_id,cost_center_id,event_id,transaction_date,
    description,amount,payment_method,notes,source_type,source_id,created_by
  ) values (
    target_club,'income'::public.transaction_kind,v_account,v_cost_center,v_event,current_date,
    case when v_customer is null then 'Venda Bar' else 'Venda Bar - '||v_customer end,
    v_total,p_payment_method,v_notes,'bar_sale',p_sale,auth.uid()
  ) returning id into v_tx;

  delete from public.bar_sale_items where sale_id=p_sale and club_id=target_club;

  for r in select value from jsonb_array_elements(p_lines)
  loop
    v_kind:=coalesce(nullif(btrim(r->>'kind'),''),'stock');
    v_quantity:=(r->>'quantity')::numeric;
    v_product_id:=null;
    v_preset_id:=null;

    if v_kind='stock' then
      v_product_id:=(r->>'product_id')::uuid;
      select * into v_product
      from public.products
      where id=v_product_id and club_id=target_club and inventory_area='bar' and active=true
      for update;
      if not found then raise exception 'Artigo do Bar inválido ou inativo.'; end if;
      v_new_stock:=coalesce(v_product.current_stock,0)-v_quantity;
      if v_new_stock<0 then
        raise exception 'Stock insuficiente de %. Disponível: %',v_product.name,coalesce(v_product.current_stock,0);
      end if;
      v_unit_price:=coalesce(v_product.sale_price,0);
      v_description:=v_product.name;
      v_line_total:=round(v_quantity*v_unit_price,2);

      update public.products set current_stock=v_new_stock where id=v_product.id;
      insert into public.stock_movements(
        club_id,product_id,event_id,kind,quantity,unit_cost,notes,created_by
      ) values (
        target_club,v_product.id,v_event,'sale',-v_quantity,coalesce(v_product.cost,0),
        concat_ws(' | ','Venda Bar',v_customer,'Venda '||p_sale::text),auth.uid()
      );
      insert into public.bar_operations(
        club_id,product_id,event_id,operation_type,purchase_units,consumption_quantity,
        unit_price,total_amount,payment_method,notes,treasury_transaction_id,created_by
      ) values (
        target_club,v_product.id,v_event,'sale',null,v_quantity,v_unit_price,v_line_total,
        p_payment_method,concat_ws(' | ',v_customer,'Venda '||p_sale::text),v_tx,auth.uid()
      );
    elsif v_kind='preset' then
      v_preset_id:=(r->>'preset_id')::uuid;
      select * into v_preset
      from public.bar_sale_presets
      where id=v_preset_id and club_id=target_club and active=true;
      if not found then raise exception 'Item fixo do Bar inválido ou inativo.'; end if;
      v_unit_price:=v_preset.unit_price;
      v_description:=v_preset.name;
      v_line_total:=round(v_quantity*v_unit_price,2);
    else
      v_description:=nullif(btrim(coalesce(r->>'description','')),'');
      v_unit_price:=(r->>'unit_price')::numeric;
      v_line_total:=round(v_quantity*v_unit_price,2);
    end if;

    insert into public.bar_sale_items(
      club_id,sale_id,item_kind,product_id,preset_id,description,quantity,unit_price,line_total
    ) values (
      target_club,p_sale,v_kind,v_product_id,v_preset_id,v_description,v_quantity,v_unit_price,v_line_total
    );
  end loop;

  update public.bar_sales
  set event_id=v_event,
      customer_label=v_customer,
      payment_method=p_payment_method,
      total_amount=v_total,
      treasury_transaction_id=v_tx,
      notes=v_notes,
      status='completed',
      completed_by=auth.uid(),
      completed_at=now(),
      updated_by=auth.uid(),
      updated_at=now()
  where id=p_sale;

  perform public.emit_domain_event(
    target_club,'BarSaleCompleted','bar',p_sale,
    jsonb_build_object(
      'title','Venda Bar concluída',
      'description',coalesce(v_customer,'Venda')||' · '||to_char(v_total,'FM999999990.00')||' €',
      'module_code','bar','route','bar','priority','low',
      'sale_id',p_sale,'transaction_id',v_tx
    )
  );

  return jsonb_build_object(
    'sale_id',p_sale,'transaction_id',v_tx,'account_id',v_account,
    'line_count',v_line_count,'total',v_total
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_bar_sale_v2(target_club uuid, p_sale uuid, p_lines jsonb, p_payment_method text, p_account uuid DEFAULT NULL::uuid, p_customer_label text DEFAULT NULL::text, p_customer_type text DEFAULT 'public'::text, p_member uuid DEFAULT NULL::uuid, p_event uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_sale public.bar_sales%rowtype;
  r jsonb;
  v_kind text;
  v_product_id uuid;
  v_preset_id uuid;
  v_option_id uuid;
  v_product public.products%rowtype;
  v_preset public.bar_sale_presets%rowtype;
  v_option public.bar_product_sale_options%rowtype;
  v_description text;
  v_quantity numeric;
  v_stock_per_unit numeric;
  v_stock_total numeric;
  v_unit_price numeric;
  v_line_total numeric;
  v_total numeric:=0;
  v_account uuid;
  v_cost_center uuid;
  v_tx uuid;
  v_new_stock numeric;
  v_event uuid;
  v_customer text;
  v_notes text;
  v_line_count integer:=0;
  v_member_label text;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageBar') then
    raise exception 'Sem autorização para concluir vendas no Bar.';
  end if;
  if p_lines is null or jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then
    raise exception 'Adiciona pelo menos um artigo à venda.';
  end if;
  if nullif(btrim(coalesce(p_payment_method,'')),'') is null then raise exception 'Seleciona o método de pagamento.'; end if;
  if p_customer_type not in ('public','member') then raise exception 'Tipo de cliente inválido.'; end if;

  select * into v_sale from public.bar_sales
  where id=p_sale and club_id=target_club for update;
  if not found then raise exception 'Venda do Bar não encontrada.'; end if;
  if v_sale.status<>'draft' then raise exception 'Esta venda já não está em rascunho.'; end if;

  if p_member is not null then
    if p_customer_type<>'member' then raise exception 'Um membro só pode ser associado a preço de membro.'; end if;
    select coalesce(nullif(btrim(nickname),''),full_name) into v_member_label
    from public.members
    where id=p_member and club_id=target_club and status::text in ('active','full_color','honorary');
    if v_member_label is null then raise exception 'Membro inválido ou sem acesso ao preço de membro.'; end if;
  end if;

  v_event:=coalesce(p_event,v_sale.event_id);
  if v_event is not null and not exists(select 1 from public.events where id=v_event and club_id=target_club) then
    raise exception 'Evento inválido.';
  end if;
  v_customer:=coalesce(nullif(btrim(coalesce(p_customer_label,'')),''),v_member_label,v_sale.customer_label);
  if p_customer_type='member' and p_member is null and nullif(btrim(coalesce(v_customer,'')),'') is null then
    raise exception 'Indica o membro ou o nome da conta de grupo.';
  end if;
  v_notes:=nullif(btrim(coalesce(p_notes,v_sale.notes,'')),'');

  for r in select value from jsonb_array_elements(p_lines)
  loop
    v_kind:=coalesce(nullif(btrim(r->>'kind'),''),'stock');
    begin v_quantity:=(r->>'quantity')::numeric;
    exception when others then raise exception 'Quantidade inválida numa linha da venda.'; end;
    if v_quantity is null or v_quantity<=0 then raise exception 'Todas as quantidades têm de ser superiores a zero.'; end if;

    if v_kind='stock' then
      begin
        v_product_id:=(r->>'product_id')::uuid;
        v_option_id:=(r->>'sale_option_id')::uuid;
      exception when others then raise exception 'Artigo ou forma de venda inválida.'; end;
      select * into v_product from public.products
      where id=v_product_id and club_id=target_club and inventory_area='bar' and active=true;
      if not found then raise exception 'Artigo do Bar inválido ou inativo.'; end if;
      select * into v_option from public.bar_product_sale_options
      where id=v_option_id and product_id=v_product_id and club_id=target_club and active=true;
      if not found then raise exception 'Forma de venda inválida ou inativa para %.',v_product.name; end if;
      v_stock_per_unit:=v_option.stock_quantity;
      v_unit_price:=case when p_customer_type='member' then v_option.member_price else v_option.public_price end;
      v_description:=v_product.name||' · '||v_option.name;
    elsif v_kind='preset' then
      begin v_preset_id:=(r->>'preset_id')::uuid;
      exception when others then raise exception 'Item fixo inválido.'; end;
      select * into v_preset from public.bar_sale_presets
      where id=v_preset_id and club_id=target_club and active=true;
      if not found then raise exception 'Item fixo do Bar inválido ou inativo.'; end if;
      if coalesce(v_preset.unit_price,0)<=0 then raise exception 'Define primeiro o preço de %.',v_preset.name; end if;
      v_stock_per_unit:=null;
      v_unit_price:=v_preset.unit_price;
      v_description:=v_preset.name;
    elsif v_kind='other' then
      v_description:=nullif(btrim(coalesce(r->>'description','')),'');
      if v_description is null then raise exception 'Indica a descrição do item Outro.'; end if;
      begin v_unit_price:=(r->>'unit_price')::numeric;
      exception when others then raise exception 'Preço inválido no item Outro.'; end;
      if v_unit_price is null or v_unit_price<0 then raise exception 'Preço inválido no item Outro.'; end if;
      v_stock_per_unit:=null;
    else
      raise exception 'Tipo de linha de venda inválido.';
    end if;

    v_line_total:=round(v_quantity*v_unit_price,2);
    v_total:=v_total+v_line_total;
    v_line_count:=v_line_count+1;
  end loop;
  if v_total<=0 then raise exception 'O total da venda tem de ser superior a zero.'; end if;

  if p_account is not null then
    if not public.has_club_permission(target_club,'selectBarFinancialAccount') then
      raise exception 'Sem autorização para escolher a conta financeira do Bar.';
    end if;
    select id into v_account from public.treasury_accounts
    where id=p_account and club_id=target_club and active=true;
    if v_account is null then raise exception 'Conta financeira inválida ou inativa.'; end if;
  else
    select id into v_account from public.treasury_accounts
    where club_id=target_club and active=true and lower(name)=lower('Caixa') limit 1;
    if v_account is null then
      select id into v_account from public.treasury_accounts
      where club_id=target_club and active=true order by created_at limit 1;
    end if;
    if v_account is null then raise exception 'Não existe nenhuma conta financeira ativa.'; end if;
  end if;

  select id into v_cost_center from public.cost_centers
  where club_id=target_club and active=true and lower(name)=lower('Club House') limit 1;

  insert into public.treasury_transactions(
    club_id,kind,account_id,cost_center_id,event_id,transaction_date,
    description,amount,payment_method,notes,source_type,source_id,created_by
  ) values (
    target_club,'income'::public.transaction_kind,v_account,v_cost_center,v_event,current_date,
    case when v_customer is null then 'Venda Bar' else 'Venda Bar - '||v_customer end,
    v_total,p_payment_method,v_notes,'bar_sale',p_sale,auth.uid()
  ) returning id into v_tx;

  delete from public.bar_sale_items where sale_id=p_sale and club_id=target_club;

  for r in select value from jsonb_array_elements(p_lines)
  loop
    v_kind:=coalesce(nullif(btrim(r->>'kind'),''),'stock');
    v_quantity:=(r->>'quantity')::numeric;
    v_product_id:=null; v_preset_id:=null; v_option_id:=null; v_stock_per_unit:=null;

    if v_kind='stock' then
      v_product_id:=(r->>'product_id')::uuid;
      v_option_id:=(r->>'sale_option_id')::uuid;
      select * into v_product from public.products
      where id=v_product_id and club_id=target_club and inventory_area='bar' and active=true for update;
      if not found then raise exception 'Artigo do Bar inválido ou inativo.'; end if;
      select * into v_option from public.bar_product_sale_options
      where id=v_option_id and product_id=v_product_id and club_id=target_club and active=true;
      if not found then raise exception 'Forma de venda inválida ou inativa para %.',v_product.name; end if;
      v_stock_per_unit:=v_option.stock_quantity;
      v_stock_total:=v_quantity*v_stock_per_unit;
      v_new_stock:=coalesce(v_product.current_stock,0)-v_stock_total;
      if v_new_stock<0 then
        raise exception 'Stock insuficiente de %. Disponível: % %',v_product.name,coalesce(v_product.current_stock,0),coalesce(v_product.consumption_unit,'unid.');
      end if;
      v_unit_price:=case when p_customer_type='member' then v_option.member_price else v_option.public_price end;
      v_description:=v_product.name||' · '||v_option.name;
      v_line_total:=round(v_quantity*v_unit_price,2);

      update public.products set current_stock=v_new_stock,updated_by=auth.uid(),updated_at=now() where id=v_product.id;
      insert into public.stock_movements(
        club_id,product_id,event_id,kind,quantity,unit_cost,notes,created_by
      ) values (
        target_club,v_product.id,v_event,'sale',-v_stock_total,coalesce(v_product.cost,0),
        concat_ws(' | ','Venda Bar',v_option.name,v_customer,'Venda '||p_sale::text),auth.uid()
      );
      insert into public.bar_operations(
        club_id,product_id,event_id,operation_type,purchase_units,consumption_quantity,
        unit_price,total_amount,payment_method,notes,treasury_transaction_id,created_by,
        sale_id,sale_option_id,sale_option_name,customer_type
      ) values (
        target_club,v_product.id,v_event,'sale',null,v_stock_total,v_unit_price,v_line_total,
        p_payment_method,concat_ws(' | ',v_option.name,v_customer,'Venda '||p_sale::text),v_tx,auth.uid(),
        p_sale,v_option.id,v_option.name,p_customer_type
      );
    elsif v_kind='preset' then
      v_preset_id:=(r->>'preset_id')::uuid;
      select * into v_preset from public.bar_sale_presets
      where id=v_preset_id and club_id=target_club and active=true;
      if not found then raise exception 'Item fixo do Bar inválido ou inativo.'; end if;
      v_unit_price:=v_preset.unit_price;
      v_description:=v_preset.name;
      v_line_total:=round(v_quantity*v_unit_price,2);
    else
      v_description:=nullif(btrim(coalesce(r->>'description','')),'');
      v_unit_price:=(r->>'unit_price')::numeric;
      v_line_total:=round(v_quantity*v_unit_price,2);
    end if;

    insert into public.bar_sale_items(
      club_id,sale_id,item_kind,product_id,preset_id,sale_option_id,sale_option_name,
      stock_quantity_per_unit,price_tier,description,quantity,unit_price,line_total
    ) values (
      target_club,p_sale,v_kind,v_product_id,v_preset_id,v_option_id,
      case when v_kind='stock' then v_option.name else null end,
      v_stock_per_unit,p_customer_type,v_description,v_quantity,v_unit_price,v_line_total
    );
  end loop;

  update public.bar_sales set
    event_id=v_event,customer_label=v_customer,customer_type=p_customer_type,member_id=p_member,
    payment_method=p_payment_method,total_amount=v_total,treasury_transaction_id=v_tx,notes=v_notes,
    status='completed',completed_by=auth.uid(),completed_at=now(),updated_by=auth.uid(),updated_at=now()
  where id=p_sale;

  perform public.emit_domain_event(
    target_club,'BarSaleCompleted','bar',p_sale,
    jsonb_build_object(
      'title','Venda Bar concluída',
      'description',coalesce(v_customer,'Venda')||' · '||to_char(v_total,'FM999999990.00')||' €',
      'module_code','bar','route','bar','priority','low','sale_id',p_sale,'transaction_id',v_tx
    )
  );

  return jsonb_build_object(
    'sale_id',p_sale,'transaction_id',v_tx,'account_id',v_account,
    'line_count',v_line_count,'total',v_total,'customer_type',p_customer_type,'member_id',p_member
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_club_export_v1(target_club uuid, p_export uuid, p_dataset_count integer, p_row_count integer, p_file_count integer, p_byte_size bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.exports%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Autenticação necessária.';
  end if;

  if not public.has_club_role(
    target_club,
    array['president','vice_president','admin','administrator','super_admin']::text[]
  ) then
    raise exception 'Sem permissão para exportação integral.';
  end if;

  if coalesce(p_dataset_count, -1) < 0
     or coalesce(p_row_count, -1) < 0
     or coalesce(p_file_count, -1) < 0
     or coalesce(p_byte_size, -1) < 0 then
    raise exception 'Métricas de exportação inválidas.';
  end if;

  select * into v_row
  from public.exports
  where id = p_export
    and club_id = target_club
    and requested_by = auth.uid()
  for update;

  if not found then
    raise exception 'Exportação não encontrada.';
  end if;
  if v_row.status <> 'running' then
    raise exception 'A exportação já foi finalizada.';
  end if;

  update public.exports
  set status = 'completed',
      dataset_count = p_dataset_count,
      row_count = p_row_count,
      file_count = p_file_count,
      byte_size = p_byte_size,
      error_code = null,
      completed_at = now()
  where id = p_export;

  insert into public.audit_log (
    club_id, actor_id, action, entity_type, entity_id, after_data, data, created_at
  ) values (
    target_club,
    auth.uid(),
    'club_export_completed',
    'club_export',
    p_export::text,
    jsonb_build_object(
      'status', 'completed',
      'dataset_count', p_dataset_count,
      'row_count', p_row_count,
      'file_count', p_file_count,
      'byte_size', p_byte_size
    ),
    jsonb_build_object('export_id', p_export),
    now()
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_bar_ocr_purchase_v1(target_club uuid, p_job uuid, p_lines jsonb, p_event uuid DEFAULT NULL::uuid, p_account uuid DEFAULT NULL::uuid, p_payment_method text DEFAULT 'Dinheiro'::text, p_total numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  j public.financial_ocr_jobs%rowtype;
  r jsonb;
  v_product public.products%rowtype;
  v_product_id uuid;
  v_purchase_units numeric;
  v_unit_price numeric;
  v_quantity numeric;
  v_new_stock numeric;
  v_purchase_unit_cost numeric;
  v_new_average_cost numeric;
  v_line_total numeric;
  v_lines_total numeric:=0;
  v_account uuid;
  v_cost_center uuid;
  v_tx uuid;
  v_desc text;
  v_note text;
  v_line_count integer:=0;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageBar') then
    raise exception 'Sem autorização para confirmar compras OCR no Bar.';
  end if;
  if p_lines is null or jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then
    raise exception 'Seleciona pelo menos uma linha do documento para entrada em stock.';
  end if;

  select * into j
  from public.financial_ocr_jobs
  where id=p_job and club_id=target_club and source_kind='bar_import'
  for update;
  if not found then raise exception 'Pedido OCR do Bar não encontrado.'; end if;
  if j.status not in ('ready','reviewed') then raise exception 'O OCR tem de estar pronto/revisto antes da confirmação.'; end if;
  if j.storage_path is null or j.file_size<=0 then raise exception 'Pedido OCR sem documento original.'; end if;

  if p_event is not null and not exists(select 1 from public.events where id=p_event and club_id=target_club) then raise exception 'Evento inválido.'; end if;

  if p_account is not null then
    if not public.has_club_permission(target_club,'selectBarFinancialAccount') then raise exception 'Sem autorização para escolher a conta financeira do Bar.'; end if;
    select id into v_account from public.treasury_accounts where id=p_account and club_id=target_club and active=true;
    if v_account is null then raise exception 'Conta financeira inválida ou inativa.'; end if;
  else
    select id into v_account from public.treasury_accounts where club_id=target_club and active=true and lower(name)=lower('Caixa') limit 1;
    if v_account is null then select id into v_account from public.treasury_accounts where club_id=target_club and active=true order by created_at limit 1; end if;
    if v_account is null then raise exception 'Não existe nenhuma conta financeira ativa.'; end if;
  end if;

  select id into v_cost_center from public.cost_centers where club_id=target_club and active=true and lower(name)=lower('Club House') limit 1;

  for r in select value from jsonb_array_elements(p_lines)
  loop
    begin
      v_product_id:=(r->>'product_id')::uuid;
      v_purchase_units:=(r->>'purchase_units')::numeric;
      v_unit_price:=(r->>'unit_price')::numeric;
    exception when others then
      raise exception 'Linha OCR com produto, quantidade ou preço inválido.';
    end;
    if v_purchase_units<=0 or v_unit_price<0 then raise exception 'Quantidade e preço das linhas OCR têm de ser válidos.'; end if;
    select * into v_product from public.products where id=v_product_id and club_id=target_club and inventory_area='bar' and active=true;
    if not found then raise exception 'Artigo de Bar inválido numa linha OCR.'; end if;
    if coalesce(v_product.units_per_purchase,0)<=0 then raise exception 'Conversão inválida no artigo %.',v_product.name; end if;
    v_lines_total:=v_lines_total+(v_purchase_units*v_unit_price);
    v_line_count:=v_line_count+1;
  end loop;

  if p_total is null or p_total<=0 then p_total:=v_lines_total; end if;
  if p_total<=0 then raise exception 'Total financeiro inválido.'; end if;

  v_desc:='Compra Bar OCR';
  if coalesce(nullif(btrim(j.supplier_name),''),'')<>'' then v_desc:=v_desc||' - '||j.supplier_name; end if;
  v_note:=nullif(btrim(coalesce(p_notes,'')),'');
  if abs(p_total-v_lines_total)>0.01 then
    v_note:=concat_ws(' | ',v_note,'OCR: total do documento '||to_char(p_total,'FM999999990.00')||' €; linhas de stock '||to_char(v_lines_total,'FM999999990.00')||' €');
  end if;

  insert into public.treasury_transactions(
    club_id,kind,account_id,cost_center_id,event_id,transaction_date,description,amount,payment_method,notes,source_type,source_id,created_by
  ) values (
    target_club,'expense'::public.transaction_kind,v_account,v_cost_center,p_event,coalesce(j.document_date,current_date),v_desc,p_total,p_payment_method,v_note,'bar_ocr',j.id,auth.uid()
  ) returning id into v_tx;

  for r in select value from jsonb_array_elements(p_lines)
  loop
    v_product_id:=(r->>'product_id')::uuid;
    v_purchase_units:=(r->>'purchase_units')::numeric;
    v_unit_price:=(r->>'unit_price')::numeric;

    select * into v_product from public.products where id=v_product_id and club_id=target_club and inventory_area='bar' and active=true for update;
    v_quantity:=v_purchase_units*v_product.units_per_purchase;
    v_new_stock:=coalesce(v_product.current_stock,0)+v_quantity;
    v_purchase_unit_cost:=v_unit_price/v_product.units_per_purchase;
    v_new_average_cost:=case when v_new_stock>0 then ((coalesce(v_product.current_stock,0)*coalesce(v_product.cost,0))+(v_quantity*v_purchase_unit_cost))/v_new_stock else v_purchase_unit_cost end;
    v_line_total:=v_purchase_units*v_unit_price;

    update public.products set current_stock=v_new_stock,purchase_cost=v_unit_price,cost=v_new_average_cost where id=v_product.id;

    insert into public.stock_movements(club_id,product_id,event_id,kind,quantity,unit_cost,notes,created_by)
    values(target_club,v_product.id,p_event,'purchase',v_quantity,v_purchase_unit_cost,concat_ws(' | ','Entrada via OCR',nullif(r->>'description','')),auth.uid());

    insert into public.bar_operations(
      club_id,product_id,event_id,operation_type,purchase_units,consumption_quantity,unit_price,total_amount,payment_method,notes,treasury_transaction_id,created_by
    ) values (
      target_club,v_product.id,p_event,'purchase',v_purchase_units,v_quantity,v_unit_price,v_line_total,p_payment_method,concat_ws(' | ','OCR',nullif(r->>'description','')),v_tx,auth.uid()
    );
  end loop;

  insert into public.financial_transaction_documents(
    club_id,transaction_id,document_type,origin,storage_path,original_file_name,mime_type,file_size,is_primary
  ) values (
    target_club,v_tx,'receipt','bar_ocr',j.storage_path,coalesce(j.original_file_name,'documento'),j.mime_type,j.file_size,true
  ) on conflict(transaction_id,storage_path) do nothing;

  perform public.refresh_financial_transaction_primary_v1(v_tx);

  update public.financial_ocr_jobs
  set status='confirmed',confirmed_at=now(),confirmed_by=auth.uid(),confirmed_transaction_id=v_tx,confirmed_lines=p_lines,transaction_id=v_tx
  where id=j.id;

  perform public.emit_domain_event(
    target_club,'BarOcrPurchaseConfirmed','bar',v_product_id,
    jsonb_build_object('title',v_desc,'description',v_line_count::text||' linhas · '||to_char(p_total,'FM999999990.00')||' €','module_code','bar','route','bar','priority','normal','ocr_job_id',j.id,'transaction_id',v_tx)
  );

  return jsonb_build_object('job_id',j.id,'transaction_id',v_tx,'account_id',v_account,'line_count',v_line_count,'lines_total',v_lines_total,'financial_total',p_total);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_bar_ocr_job_v1(target_club uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageBar') then raise exception 'Sem autorização para usar OCR no Bar.'; end if;
  insert into public.financial_ocr_jobs(club_id,source_kind,status,provider) values(target_club,'bar_import','draft','openai') returning id into v_id;
  return v_id;
end; $function$

CREATE OR REPLACE FUNCTION public.create_bar_sale_v1(target_club uuid, p_customer_label text DEFAULT NULL::text, p_source_mode text DEFAULT 'manual'::text, p_event uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageBar') then
    raise exception 'Sem autorização para criar vendas no Bar.';
  end if;
  if p_source_mode not in ('manual','ocr') then
    raise exception 'Modo de venda inválido.';
  end if;
  if p_event is not null and not exists(
    select 1 from public.events where id=p_event and club_id=target_club
  ) then
    raise exception 'Evento inválido.';
  end if;

  insert into public.bar_sales(
    club_id,event_id,source_mode,status,customer_label,notes,created_by,updated_by
  ) values (
    target_club,p_event,p_source_mode,'draft',nullif(btrim(coalesce(p_customer_label,'')),''),
    nullif(btrim(coalesce(p_notes,'')),''),auth.uid(),auth.uid()
  ) returning id into v_id;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_bar_sale_v2(target_club uuid, p_customer_label text DEFAULT NULL::text, p_customer_type text DEFAULT 'public'::text, p_member uuid DEFAULT NULL::uuid, p_source_mode text DEFAULT 'manual'::text, p_event uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  v_label text;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageBar') then
    raise exception 'Sem autorização para criar vendas no Bar.';
  end if;
  if p_source_mode not in ('manual','ocr') then raise exception 'Modo de venda inválido.'; end if;
  if p_customer_type not in ('public','member') then raise exception 'Tipo de cliente inválido.'; end if;
  if p_event is not null and not exists(select 1 from public.events where id=p_event and club_id=target_club) then
    raise exception 'Evento inválido.';
  end if;
  if p_member is not null then
    if p_customer_type<>'member' then raise exception 'Um membro só pode ser associado a preço de membro.'; end if;
    select coalesce(nullif(btrim(nickname),''),full_name) into v_label
    from public.members
    where id=p_member and club_id=target_club and status::text in ('active','full_color','honorary');
    if v_label is null then raise exception 'Membro inválido ou sem acesso ao preço de membro.'; end if;
  end if;
  v_label:=coalesce(nullif(btrim(coalesce(p_customer_label,'')),''),v_label);
  if p_customer_type='member' and p_member is null and v_label is null then
    raise exception 'Indica o membro ou o nome da conta de grupo.';
  end if;

  insert into public.bar_sales(
    club_id,event_id,source_mode,status,customer_label,customer_type,member_id,
    notes,created_by,updated_by
  ) values (
    target_club,p_event,p_source_mode,'draft',v_label,p_customer_type,p_member,
    nullif(btrim(coalesce(p_notes,'')),''),auth.uid(),auth.uid()
  ) returning id into v_id;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_member_charges_v1(target_club uuid, p_member_ids uuid[], p_category text, p_amount numeric, p_description text, p_due_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_batch uuid:=gen_random_uuid(); v_member uuid; v_request uuid; n integer:=0; member_profile uuid; member_name text; ids jsonb:='[]'::jsonb;
begin
  if not public.financial_manager_v1(target_club) then raise exception 'Sem autorização para criar cobranças.'; end if;
  if p_category not in ('fee','euromillions','bar','other') then raise exception 'Tipo de cobrança inválido.'; end if;
  if p_amount is null or p_amount<=0 then raise exception 'O valor deve ser superior a zero.'; end if;
  if nullif(btrim(p_description),'') is null then raise exception 'A descrição é obrigatória.'; end if;
  if coalesce(array_length(p_member_ids,1),0)=0 then raise exception 'Seleciona pelo menos um membro.'; end if;
  for v_member in select distinct unnest(p_member_ids) loop
    select m.profile_id,coalesce(nullif(m.nickname,''),m.full_name) into member_profile,member_name
    from public.members m where m.id=v_member and m.club_id=target_club and m.status::text in ('active','prospect','full_color','honorary');
    if not found then raise exception 'Existe um membro não elegível na seleção.'; end if;
    insert into public.financial_requests(club_id,member_id,request_type,category,batch_id,amount,description,due_date,status,requested_by)
    values(target_club,v_member,'charge',p_category,v_batch,round(p_amount,2),btrim(p_description),p_due_date,'awaiting_payment',auth.uid()) returning id into v_request;
    n:=n+1; ids:=ids||to_jsonb(v_request);
    perform public.notify_financial_profile_v1(target_club,member_profile,v_request,'Nova cobrança',btrim(p_description)||' · '||to_char(p_amount,'FM999999990.00')||' €','high');
  end loop;
  perform public.financial_activity_v1(target_club,null,'Cobranças emitidas',n||' cobrança(s) de '||to_char(p_amount,'FM999999990.00')||' € · '||btrim(p_description));
  return jsonb_build_object('batch_id',v_batch,'count',n,'request_ids',ids);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_member_with_position(target_club uuid, new_member_number integer, new_full_name text, new_nickname text, new_email text, new_phone text, new_joined_at date, position_ref uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare member_id uuid;
begin
  if not public.has_club_permission(target_club,'manageMembers') then raise exception 'Sem autorização para criar membros.'; end if;
  insert into public.members(club_id,member_number,full_name,nickname,email,phone,joined_at,status)
  values(target_club,new_member_number,new_full_name,new_nickname,new_email,new_phone,new_joined_at,'active') returning id into member_id;
  if position_ref is not null then insert into public.member_positions(club_id,member_id,position_id,is_primary,starts_at) values(target_club,member_id,position_ref,true,new_joined_at); end if;
  return member_id;
end; $function$

CREATE OR REPLACE FUNCTION public.create_reimbursement_draft_v1(target_club uuid, p_member uuid, p_amount numeric, p_description text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_member uuid; v_request uuid; v_own uuid;
begin
  if not public.has_club_access(target_club) then raise exception 'Sem acesso ao clube.'; end if;
  if p_amount is null or p_amount<=0 then raise exception 'O valor deve ser superior a zero.'; end if;
  if nullif(btrim(p_description),'') is null then raise exception 'A descrição é obrigatória.'; end if;
  v_own:=public.current_financial_member_v1(target_club);
  if public.financial_manager_v1(target_club) and p_member is not null then v_member:=p_member;
  else
    v_member:=v_own;
    if p_member is not null and p_member is distinct from v_own then raise exception 'Só podes criar pedidos para o teu próprio perfil.'; end if;
  end if;
  if v_member is null then raise exception 'O utilizador não está associado a um membro do clube.'; end if;
  if not exists(select 1 from public.members m where m.id=v_member and m.club_id=target_club and m.status::text not in ('former','deceased')) then raise exception 'Membro inválido para este pedido.'; end if;
  insert into public.financial_requests(club_id,member_id,request_type,category,amount,description,status,requested_by)
  values(target_club,v_member,'reimbursement','reimbursement',round(p_amount,2),btrim(p_description),'draft',auth.uid()) returning id into v_request;
  return v_request;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_reported_fee_payment_v1(target_club uuid, p_amount numeric, p_paid_on date, p_payment_method text, p_notes text, p_proof_path text, p_proof_name text, p_proof_mime_type text, p_proof_size bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_member uuid; v_id uuid; v_prefix text;
begin
  if auth.uid() is null then raise exception 'Sessão inválida.'; end if;
  select m.id into v_member from public.members m join public.club_memberships cm on cm.club_id=m.club_id and cm.profile_id=m.profile_id and cm.active=true
  where m.club_id=target_club and m.profile_id=auth.uid() limit 1;
  if v_member is null then raise exception 'Não existe membro associado ao utilizador.'; end if;
  if p_amount is null or p_amount<=0 then raise exception 'O valor deve ser superior a zero.'; end if;
  if p_paid_on is null then raise exception 'Indica a data do pagamento.'; end if;
  if nullif(trim(coalesce(p_payment_method,'')),'') is null then raise exception 'Indica o método de pagamento.'; end if;
  if nullif(trim(coalesce(p_proof_path,'')),'') is null or nullif(trim(coalesce(p_proof_name,'')),'') is null then raise exception 'É obrigatório anexar o comprovativo.'; end if;
  v_prefix:=target_club::text||'/'||auth.uid()::text||'/';
  if left(p_proof_path,length(v_prefix))<>v_prefix then raise exception 'Caminho do comprovativo inválido.'; end if;
  insert into public.reported_payments(club_id,member_id,amount,paid_on,payment_method,notes,proof_path,proof_name,proof_mime_type,proof_size,status,created_by)
  values(target_club,v_member,p_amount,p_paid_on,trim(p_payment_method),nullif(trim(coalesce(p_notes,'')),''),p_proof_path,p_proof_name,p_proof_mime_type,p_proof_size,'pending',auth.uid()) returning id into v_id;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_shop_order_v1(target_club uuid, p_product uuid, p_variant uuid, p_quantity numeric, p_unit_price numeric, p_member uuid DEFAULT NULL::uuid, p_external_name text DEFAULT NULL::text, p_external_contact text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_order uuid; v_product public.products%rowtype; v_variant public.product_variants%rowtype;
begin
  if not public.has_club_permission(target_club,'manageMerchandising') then raise exception 'Sem autorização para gerir encomendas.'; end if;
  if p_quantity<=0 or p_unit_price<0 then raise exception 'Quantidade/preço inválidos.'; end if;
  if p_member is null and nullif(trim(coalesce(p_external_name,'')),'') is null then raise exception 'Indique o membro ou o nome do cliente.'; end if;
  select * into v_product from public.products where id=p_product and club_id=target_club and inventory_area='shop' and active=true;
  if not found then raise exception 'Artigo não encontrado.'; end if;
  if p_variant is not null then
    select * into v_variant from public.product_variants where id=p_variant and product_id=p_product and active=true;
    if not found then raise exception 'Variante não encontrada.'; end if;
  end if;
  insert into public.shop_orders(club_id,member_id,external_name,external_contact,total_amount,notes,created_by)
  values(target_club,p_member,nullif(trim(coalesce(p_external_name,'')),''),nullif(trim(coalesce(p_external_contact,'')),''),p_quantity*p_unit_price,nullif(trim(coalesce(p_notes,'')),''),auth.uid()) returning id into v_order;
  insert into public.shop_order_items(order_id,product_id,variant_id,quantity,unit_price) values(v_order,p_product,p_variant,p_quantity,p_unit_price);
  perform public.emit_domain_event(target_club,'ShopOrderCreated','product',p_product,jsonb_build_object('title','Nova encomenda de Loja','description',v_product.name||case when p_variant is not null then ' — '||v_variant.name else '' end||' × '||p_quantity::text,'module_code','inventory','priority','normal','route','inventory'));
  return v_order;
end; $function$

CREATE OR REPLACE FUNCTION public.create_transaction_v1(target_club uuid, p_kind text, p_account uuid, p_destination_account uuid, p_description text, p_amount numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare result_id uuid;
begin
  if p_kind='transfer' then
    if not public.has_club_permission(target_club,'transferBetweenAccounts') then raise exception 'Sem autorização para transferir entre contas.'; end if;
  else
    if not public.has_club_permission(target_club,'createTreasuryMovement') then raise exception 'Sem autorização para criar movimentos.'; end if;
  end if;
  if p_kind not in ('income','expense','transfer') then raise exception 'Tipo de movimento inválido.'; end if;
  if p_amount is null or p_amount<=0 then raise exception 'O valor deve ser superior a zero.'; end if;
  if p_description is null or btrim(p_description)='' then raise exception 'A descrição é obrigatória.'; end if;
  insert into public.treasury_transactions(club_id,kind,account_id,destination_account_id,transaction_date,description,amount,created_by)
  values(target_club,p_kind::public.transaction_kind,p_account,case when p_kind='transfer' then p_destination_account else null end,current_date,btrim(p_description),p_amount,auth.uid()) returning id into result_id;
  return result_id;
end; $function$

CREATE OR REPLACE FUNCTION public.create_treasury_transaction(target_club uuid, transaction_kind transaction_kind, source_account uuid, destination_account uuid, category uuid, cost_center uuid, event_ref uuid, movement_date date, movement_description text, movement_amount numeric, movement_payment_method text, movement_notes text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare transaction_id uuid;
begin
  if transaction_kind='transfer' then
    if not public.has_club_permission(target_club,'transferBetweenAccounts') then raise exception 'Sem autorização para transferir entre contas.'; end if;
  else
    if not public.has_club_permission(target_club,'createTreasuryMovement') then raise exception 'Sem autorização para criar movimentos.'; end if;
