  perform public.rebuild_weekly_officer_future_internal_v1(target_club,greatest(current_date,v_start));
end;
$function$

CREATE OR REPLACE FUNCTION public.deliver_member_patch_v1(target_club uuid, p_award uuid, p_location uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  a public.member_patch_awards%rowtype;
  v_product public.products%rowtype;
  v_variant public.product_variants%rowtype;
  v_location_name text;
  v_cost numeric:=0;
begin
  if not public.has_club_permission(target_club,'manageInventory') then
    raise exception 'Sem permissão de Inventário para confirmar a entrega.';
  end if;
  select * into a from public.member_patch_awards
  where id=p_award and club_id=target_club and status='approved'
  for update;
  if not found then raise exception 'Patch não aprovado ou já entregue.'; end if;

  select * into v_product from public.products
  where id=a.product_id and club_id=target_club and active=true
  for update;
  if not found then raise exception 'Artigo institucional indisponível.'; end if;

  if a.variant_id is not null then
    select * into v_variant from public.product_variants
    where id=a.variant_id and product_id=a.product_id and active=true
    for update;
    if not found then raise exception 'Variante indisponível.'; end if;
    v_cost:=coalesce(v_variant.cost,v_product.cost,0);
  else
    v_cost:=coalesce(v_product.cost,0);
  end if;

  select name into v_location_name from public.inventory_locations
  where id=p_location and club_id=target_club and active=true;
  if v_location_name is null then raise exception 'Local de inventário inválido.'; end if;

  perform set_config('bob.skip_stock_balance_sync','1',true);
  perform public.inventory_balance_apply_internal_v1(target_club,a.product_id,a.variant_id,p_location,-1,0);

  if a.variant_id is null then
    update public.products p
    set current_stock=(
      select coalesce(sum(b.quantity),0) from public.inventory_stock_balances b
      where b.club_id=target_club and b.product_id=p.id and b.variant_id is null
    ),updated_at=now(),updated_by=auth.uid()
    where p.id=a.product_id and p.club_id=target_club;
  else
    update public.product_variants pv
    set current_stock=(
      select coalesce(sum(b.quantity),0) from public.inventory_stock_balances b
      where b.club_id=target_club and b.product_id=a.product_id and b.variant_id=pv.id
    )
    where pv.id=a.variant_id and pv.product_id=a.product_id;
    update public.products p
    set current_stock=(
      select coalesce(sum(pv.current_stock),0) from public.product_variants pv
      where pv.product_id=p.id and pv.active=true
    ),updated_at=now(),updated_by=auth.uid()
    where p.id=a.product_id and p.club_id=target_club;
  end if;
  perform set_config('bob.skip_stock_balance_sync','0',true);

  insert into public.stock_movements(
    club_id,product_id,variant_id,kind,quantity,unit_cost,notes,created_by,from_location_id
  ) values (
    target_club,a.product_id,a.variant_id,'adjustment',-1,v_cost,
    'Entrega institucional de patch a membro '||a.member_id::text,auth.uid(),p_location
  );

  update public.member_patch_awards
  set status='delivered',delivered_at=now(),delivered_by=auth.uid(),
      inventory_location_id=p_location,delivery_location_name=v_location_name,
      updated_at=now(),updated_by=auth.uid()
  where id=a.id;
end
$function$

CREATE OR REPLACE FUNCTION public.emit_domain_event(target_club uuid, event_name text, aggregate_type text, aggregate_id uuid, payload jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare new_id uuid; v_module text; v_permission text; v_title text; v_body text; v_priority text; r record;
begin
  if auth.uid() is null or not public.has_club_access(target_club) then raise exception 'Sem acesso ao clube.'; end if;
  v_module:=public.notification_module_code(aggregate_type);
  v_permission:=public.notification_module_permission(aggregate_type);
  v_title:=coalesce(nullif(payload->>'title',''),event_name);
  v_body:=coalesce(nullif(payload->>'description',''),v_title);
  v_priority:=case when payload->>'priority' in ('low','normal','high','urgent') then payload->>'priority' else 'normal' end;
  insert into public.domain_events(club_id,event_name,aggregate_type,aggregate_id,actor_id,payload) values(target_club,event_name,aggregate_type,aggregate_id,auth.uid(),coalesce(payload,'{}'::jsonb)) returning id into new_id;
  insert into public.activity_feed(club_id,actor_id,activity_type,title,description,entity_type,entity_id,metadata) values(target_club,auth.uid(),v_module,v_title,payload->>'description',aggregate_type,aggregate_id,coalesce(payload,'{}'::jsonb)||jsonb_build_object('event_name',event_name,'module_code',v_module,'domain_event_id',new_id));
  for r in select cm.profile_id from public.club_memberships cm where cm.club_id=target_club and cm.active=true loop
    if v_permission is null or public.profile_has_club_permission(target_club,r.profile_id,v_permission) then
      if coalesce((select np.in_app_enabled from public.notification_preferences np where np.club_id=target_club and np.profile_id=r.profile_id and np.module_code=v_module),true) then
        insert into public.notifications(club_id,profile_id,title,body,notification_type,module_code,priority,entity_type,entity_id,action_route,metadata,domain_event_id) values(target_club,r.profile_id,v_title,v_body,event_name,v_module,v_priority,aggregate_type,aggregate_id,payload->>'route',coalesce(payload,'{}'::jsonb),new_id);
      end if;
    end if;
  end loop;
  return new_id;
end
$function$

CREATE OR REPLACE FUNCTION public.enforce_event_capacity_seat_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event_id uuid;
  v_capacity integer;
  v_occupancy bigint;
  v_required_seats integer := 1;
begin
  if tg_table_name = 'event_registrations' then
    v_event_id := new.event_id;
    if nullif(btrim(new.guest_name), '') is not null then
      v_required_seats := 2;
    end if;
  elsif tg_table_name = 'event_registration_guests' then
    select er.event_id
      into v_event_id
    from public.event_registrations er
    where er.id = new.registration_id;

    if v_event_id is null then
      return new;
    end if;
  else
    raise exception using
      errcode = 'P0001',
      message = 'EVENT_CAPACITY_INVALID_TRIGGER';
  end if;

  select e.capacity
    into v_capacity
  from public.events e
  where e.id = v_event_id
  for update;

  if not found or v_capacity is null then
    return new;
  end if;

  select
    (
      select count(*)
      from public.event_registrations er
      where er.event_id = v_event_id
    )
    + (
      select count(*)
      from public.event_registrations er
      where er.event_id = v_event_id
        and nullif(btrim(er.guest_name), '') is not null
    )
    + (
      select count(*)
      from public.event_registration_guests g
      join public.event_registrations er on er.id = g.registration_id
      where er.event_id = v_event_id
    )
    into v_occupancy;

  if v_occupancy + v_required_seats > v_capacity then
    raise exception using
      errcode = 'P0001',
      message = 'EVENT_CAPACITY_REACHED',
      detail = format(
        'Capacidade: %s; ocupação atual: %s; lugares pedidos: %s.',
        v_capacity,
        v_occupancy,
        v_required_seats
      );
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_event_child_club_v1()
 RETURNS trigger
