CREATE OR REPLACE FUNCTION public.enforce_personal_document_quota_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_scope text;
  v_owner uuid;
  v_used bigint;
  v_limit constant bigint := 524288000;
begin
  select d.scope,d.owner_profile_id into v_scope,v_owner
  from public.documents d where d.id=new.document_id;
  if v_scope <> 'personal' then return new; end if;
  if v_owner is null then raise exception 'Documento pessoal sem proprietário.'; end if;
  perform pg_advisory_xact_lock(hashtextextended(v_owner::text,0));
  select coalesce(sum(v.file_size),0)::bigint into v_used
  from public.document_versions v
  join public.documents d on d.id=v.document_id
  where d.scope='personal' and d.owner_profile_id=v_owner;
  if v_used + coalesce(new.file_size,0) > v_limit then
    raise exception 'Limite pessoal de 500 MB excedido.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_weekly_officer_schedule_v1(target_club uuid, p_year integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_start date;
  v_end date;
  v_first date;
  v_inserted integer := 0;
  v_current_year integer;
begin
  if (select auth.uid()) is null or not public.has_club_access(target_club) then
    raise exception 'Sem acesso ao clube.';
  end if;
  if p_year < 2020 or p_year > 2100 then
    raise exception 'Ano inválido.';
  end if;

  v_current_year := extract(year from current_date)::integer;
  if p_year < v_current_year then
    return 0;
  end if;

  v_start := make_date(p_year,1,1);
  v_end := make_date(p_year,12,31);
  if p_year=v_current_year then
    v_start := greatest(v_start,current_date);
  end if;
  v_first := v_start + ((4-extract(dow from v_start)::integer+7)%7);

  insert into public.weekly_dinners
    (club_id,dinner_date,dinner_kind,status,assignment_source,generated)
  select target_club,gs::date,'regular','planned','auto',true
  from generate_series(v_first::timestamp,v_end::timestamp,interval '7 day') gs
  on conflict (club_id,dinner_date,dinner_kind) do nothing;
  get diagnostics v_inserted=row_count;
  perform public.rebuild_weekly_officer_schedule_internal_v1(target_club,v_first,v_end);
  return v_inserted;
end;
$function$

CREATE OR REPLACE FUNCTION public.fail_club_export_v1(target_club uuid, p_export uuid, p_error_code text DEFAULT 'generation_failed'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.exports%rowtype;
  v_code text := left(
    regexp_replace(
      lower(coalesce(nullif(btrim(p_error_code), ''), 'generation_failed')),
      '[^a-z0-9._-]+', '_', 'g'
    ),
    80
  );
begin
  if auth.uid() is null then
    raise exception 'Autenticação necessária.';
  end if;

  if not public.has_club_role(
    target_club,
    array['president','vice_president','admin','administrator','super_admin']::text[]
  ) then
    raise exception 'Sem permissão para exportação integral.';
  end if;

  select * into v_row
  from public.exports
  where id = p_export
    and club_id = target_club
    and requested_by = auth.uid()
  for update;

  if not found then
    raise exception 'Exportação não encontrada.';
  end if;
  if v_row.status <> 'running' then
    return;
  end if;

  update public.exports
  set status = 'failed',
      error_code = v_code,
      completed_at = now()
  where id = p_export;

  insert into public.audit_log (
    club_id, actor_id, action, entity_type, entity_id, after_data, data, created_at
  ) values (
    target_club,
    auth.uid(),
    'club_export_failed',
    'club_export',
    p_export::text,
    jsonb_build_object('status', 'failed', 'error_code', v_code),
    jsonb_build_object('export_id', p_export),
    now()
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.fee_credit_balance_v1(target_club uuid, p_member uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_total numeric;
begin
  if auth.uid() is null or not(public.has_club_permission(target_club,'manageFees') or exists(
    select 1 from public.members m where m.id=p_member and m.club_id=target_club and m.profile_id=auth.uid()
  )) then raise exception 'Sem acesso ao saldo de crédito.'; end if;
  select coalesce(sum(c.amount),0) into v_total from public.fee_credits c where c.club_id=target_club and c.member_id=p_member;
  return greatest(0,v_total);
end;
$function$

CREATE OR REPLACE FUNCTION public.fee_operational_reference_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v jsonb:=to_jsonb(new);
  v_id uuid;
  v_member uuid;
  v_payment_member uuid;
  v_obligation_member uuid;
begin
  if nullif(v->>'member_id','') is not null then
    v_member:=(v->>'member_id')::uuid;
    if not exists(select 1 from public.members m where m.id=v_member and m.club_id=new.club_id) then
      raise exception 'O membro não pertence ao clube.';
    end if;
  end if;

  if nullif(v->>'obligation_id','') is not null then
    v_id:=(v->>'obligation_id')::uuid;
    select o.member_id into v_obligation_member
    from public.fee_obligations o
    where o.id=v_id and o.club_id=new.club_id;
    if v_obligation_member is null or (v_member is not null and v_obligation_member<>v_member) then
      raise exception 'A quota não pertence ao membro/clube.';
    end if;
  end if;

  if nullif(v->>'payment_id','') is not null then
    v_id:=(v->>'payment_id')::uuid;
    select p.member_id into v_payment_member
    from public.fee_payments p
    where p.id=v_id and p.club_id=new.club_id;
    if v_payment_member is null or (v_member is not null and v_payment_member<>v_member) then
      raise exception 'O pagamento não pertence ao membro/clube.';
    end if;
  end if;

  if v_payment_member is not null and v_obligation_member is not null and v_payment_member<>v_obligation_member then
    raise exception 'Pagamento e quota pertencem a membros diferentes.';
  end if;

  if nullif(v->>'source_credit_id','') is not null then
    v_id:=(v->>'source_credit_id')::uuid;
    if not exists(select 1 from public.fee_credits c where c.id=v_id and c.club_id=new.club_id and (v_member is null or c.member_id=v_member)) then
      raise exception 'O crédito de origem não pertence ao membro/clube.';
    end if;
  end if;

  if nullif(v->>'fee_payment_id','') is not null then
    v_id:=(v->>'fee_payment_id')::uuid;
    if not exists(select 1 from public.fee_payments p where p.id=v_id and p.club_id=new.club_id and (v_member is null or p.member_id=v_member)) then
      raise exception 'O pagamento validado não pertence ao membro/clube.';
    end if;
  end if;

  if nullif(v->>'transaction_id','') is not null then
    v_id:=(v->>'transaction_id')::uuid;
    if not exists(select 1 from public.treasury_transactions t where t.id=v_id and t.club_id=new.club_id) then
      raise exception 'O movimento financeiro não pertence ao clube.';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.fee_settings_v1(target_club uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare result jsonb;
begin
  if not exists (
    select 1 from public.club_memberships cm
    where cm.club_id=target_club and cm.profile_id=auth.uid() and cm.active=true
  ) then raise exception 'Sem acesso ao clube.'; end if;

  select jsonb_build_object(
    'due_day',coalesce(max(case when key='fee_due_day' then value::integer end),8),
    'monthly_amount',coalesce(max(case when key='monthly_fee_amount' then value::numeric end),25),
    'registration_amount',coalesce(max(case when key='registration_fee_amount' then value::numeric end),0)
  ) into result
  from public.club_settings
  where club_id=target_club and key in ('fee_due_day','monthly_fee_amount','registration_fee_amount');
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.financial_storage_access_v2(p_name text, p_manage boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'storage'
AS $function$
declare
  folders text[];
  v_request uuid;
  v_transaction uuid;
  v_job uuid;
  v_sale uuid;
  v_club uuid;
begin
  if auth.uid() is null then return false; end if;
  folders:=storage.foldername(p_name);
  if coalesce(array_length(folders,1),0)<2 then return false; end if;

  if folders[2]='transactions' then
    if coalesce(array_length(folders,1),0)<3 then return false; end if;
    begin v_transaction:=folders[3]::uuid; exception when invalid_text_representation then return false; end;
    select t.club_id into v_club from public.treasury_transactions t where t.id=v_transaction;
    if not found or folders[1] is distinct from v_club::text then return false; end if;
    if p_manage then
      return public.has_club_permission(v_club,'createTreasuryMovement')
        or public.has_club_permission(v_club,'approveExpenseRequests');
    end if;
    return public.has_club_permission(v_club,'viewTreasury')
      or public.has_club_permission(v_club,'approveExpenseRequests');
  end if;

  if folders[2]='ocr' then
    if coalesce(array_length(folders,1),0)<3 then return false; end if;
    begin v_job:=folders[3]::uuid; exception when invalid_text_representation then return false; end;
    select j.club_id into v_club from public.financial_ocr_jobs j where j.id=v_job;
    if not found or folders[1] is distinct from v_club::text then return false; end if;
    if p_manage then
      return public.has_club_permission(v_club,'manageBar')
        or public.has_club_permission(v_club,'createTreasuryMovement')
        or public.has_club_permission(v_club,'approveExpenseRequests');
    end if;
    return public.has_club_permission(v_club,'manageBar')
      or public.has_club_permission(v_club,'viewBar')
      or public.has_club_permission(v_club,'viewTreasury')
      or public.has_club_permission(v_club,'approveExpenseRequests');
  end if;

  if folders[2]='bar-sales' then
    if coalesce(array_length(folders,1),0)<3 then return false; end if;
    begin v_sale:=folders[3]::uuid; exception when invalid_text_representation then return false; end;
    select s.club_id into v_club from public.bar_sales s where s.id=v_sale;
    if not found or folders[1] is distinct from v_club::text then return false; end if;
    if p_manage then return public.has_club_permission(v_club,'manageBar'); end if;
    return public.has_club_permission(v_club,'viewBar')
      or public.has_club_permission(v_club,'manageBar');
  end if;

  begin v_request:=folders[2]::uuid; exception when invalid_text_representation then return false; end;
  select r.club_id into v_club from public.financial_requests r where r.id=v_request;
  if not found or folders[1] is distinct from v_club::text then return false; end if;
  return public.financial_request_access_v1(v_request);
end;
$function$

CREATE OR REPLACE FUNCTION public.generate_euromillions_charges_v1(target_club uuid, p_year integer, p_month integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_amount numeric;
  d date;
  monday date;
begin
  if auth.uid() is null then
    raise exception 'Autenticação necessária.' using errcode = '42501';
  end if;
  if not public.has_club_access(target_club) then
    raise exception 'Sem acesso ao clube.';
  end if;

  perform public.sync_euromillions_players_v1(target_club);
  select coalesce(
    (select value::numeric from public.club_settings
      where club_id=target_club and key='euromillions_draw_amount'),
    2.20
  ) into v_amount;
  d := make_date(p_year,p_month,1);
  while extract(month from d)=p_month loop
    if extract(isodow from d) in (2,5) then
      monday := d - (extract(isodow from d)::integer - 1);
      insert into public.euromillions_draw_charges
        (club_id,player_id,week_start,draw_date,amount)
      select target_club,p.id,monday,d,v_amount
      from public.euromillions_players p
      where p.club_id=target_club and p.status='active'
      on conflict (club_id,player_id,draw_date) do nothing;
    end if;
    d := d + 1;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.generate_member_fees_internal(p_member uuid, p_year integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  m public.members%rowtype;
  entry_date date;
  start_month integer;
  month_no integer;
  due_day integer := 8;
  monthly_amount numeric := 25;
  registration_amount numeric := 0;
  plan_id uuid;
begin
  select * into m from public.members where id=p_member;
  if not found then return; end if;
  if m.status::text not in ('prospect','full_color','active') then return; end if;

  entry_date := coalesce(m.prospect_joined_at, m.joined_at, m.created_at::date);
  if entry_date is null then return; end if;

  select coalesce(max(case when key='fee_due_day' then value::integer end),8),
         coalesce(max(case when key='monthly_fee_amount' then value::numeric end),25),
         coalesce(max(case when key='registration_fee_amount' then value::numeric end),0)
    into due_day, monthly_amount, registration_amount
  from public.club_settings
  where club_id=m.club_id and key in ('fee_due_day','monthly_fee_amount','registration_fee_amount');

  due_day := greatest(1, least(due_day,28));

  select id into plan_id
  from public.fee_plans
  where club_id=m.club_id and active=true and frequency='monthly'
  order by created_at desc
  limit 1;

  if p_year >= extract(year from entry_date)::integer and monthly_amount > 0 then
    start_month := case
      when p_year = extract(year from entry_date)::integer then extract(month from entry_date)::integer
      else 1
    end;

    for month_no in start_month..12 loop
      insert into public.fee_obligations(
        club_id, member_id, fee_plan_id, reference_year, reference_month,
        due_date, amount, paid_amount, status, obligation_type
      ) values (
        m.club_id, m.id, plan_id, p_year, month_no,
        make_date(p_year,month_no,due_day), monthly_amount, 0, 'pending', 'monthly'
      )
      on conflict (club_id, member_id, reference_year, reference_month) do nothing;
    end loop;
  end if;

  if registration_amount > 0 and not exists (
    select 1 from public.fee_obligations
    where club_id=m.club_id and member_id=m.id and obligation_type='registration'
  ) then
    insert into public.fee_obligations(
      club_id, member_id, reference_year, reference_month,
      due_date, amount, paid_amount, status, obligation_type, notes
    ) values (
      m.club_id, m.id, extract(year from entry_date)::integer, null,
      entry_date, registration_amount, 0, 'pending', 'registration', 'Inscrição de entrada'
    );
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.generate_monthly_fees(target_club uuid, target_year integer, plan_ref uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare plan_row public.fee_plans%rowtype; inserted_count integer;
begin
  if not public.has_club_permission(target_club,'manageFees') then raise exception 'Sem autorização para gerar quotas.'; end if;
  select * into plan_row from public.fee_plans where id=plan_ref and club_id=target_club and active=true;
  if not found then raise exception 'Plano de quotas não encontrado.'; end if;
  insert into public.fee_obligations(club_id,member_id,fee_plan_id,reference_year,reference_month,due_date,amount,status)
  select target_club,m.id,plan_row.id,target_year,month_number,make_date(target_year,month_number,1)+(coalesce(plan_row.due_day,1)-1),plan_row.amount,'pending' from public.members m cross join generate_series(1,12) as month_number where m.club_id=target_club and m.status='active' on conflict(club_id,member_id,reference_year,reference_month) do nothing;
  get diagnostics inserted_count=row_count; return inserted_count;
end; $function$

CREATE OR REPLACE FUNCTION public.guard_event_registration_guest_attendance_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_club uuid;
begin
  if new.status is not distinct from old.status
     and new.checked_in_at is not distinct from old.checked_in_at
     and new.notes is not distinct from old.notes then
    return new;
  end if;

  select e.club_id
    into v_club
  from public.event_registrations er
  join public.events e on e.id = er.event_id
  where er.id = new.registration_id;

  if v_club is null then
    raise exception 'guest_registration_not_found' using errcode = 'P0001';
  end if;

  if not public.has_club_permission(v_club, 'manageEventParticipants') then
    raise exception 'guest_attendance_permission_denied' using errcode = '42501';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.has_club_permission(target_club uuid, requested_permission text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role text;
  v_override boolean;
  v_role_allowed boolean;
begin
  select access_role into v_role
  from public.club_memberships
  where club_id=target_club and profile_id=auth.uid() and active=true
  limit 1;

  if v_role is null then return false; end if;
  if lower(v_role) in ('super_admin','super admin') then return true; end if;

  select allowed into v_override
  from public.user_permission_overrides
  where club_id=target_club and profile_id=auth.uid() and permission_key=requested_permission;
  if found then return v_override; end if;

  select allowed into v_role_allowed
  from public.club_role_permissions
  where club_id=target_club and role_key=v_role and permission_key=requested_permission;
  return coalesce(v_role_allowed,false);
end;
$function$

CREATE OR REPLACE FUNCTION public.import_parse_boolean_v1(p_value text, p_default boolean DEFAULT NULL::boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v text := lower(nullif(btrim(p_value), ''));
begin
  if v is null then return p_default; end if;
  if v in ('true','1','sim','yes','y','s') then return true; end if;
  if v in ('false','0','nao','não','no','n') then return false; end if;
  raise exception 'boolean inválido';
end;
$function$

CREATE OR REPLACE FUNCTION public.import_parse_date_v1(p_value text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v text := nullif(btrim(p_value), '');
begin
  if v is null then return null; end if;
  if v ~ '^\d{2}/\d{2}/\d{4}$' then return to_date(v, 'DD/MM/YYYY'); end if;
  return v::date;
end;
$function$

CREATE OR REPLACE FUNCTION public.import_parse_numeric_v1(p_value text, p_default numeric DEFAULT NULL::numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v text := nullif(btrim(p_value), '');
begin
  if v is null then return p_default; end if;
  v := replace(replace(v, '€', ''), ' ', '');
  if position(',' in v) > 0 and position('.' in v) > 0 then
    if strpos(reverse(v), ',') < strpos(reverse(v), '.') then
      v := replace(v, '.', ''); v := replace(v, ',', '.');
    else v := replace(v, ',', ''); end if;
  else v := replace(v, ',', '.'); end if;
  return v::numeric;
end;
$function$

CREATE OR REPLACE FUNCTION public.import_parse_timestamptz_v1(p_value text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v text := nullif(btrim(p_value), '');
begin
  if v is null then return null; end if;
  if v ~ '^\d{2}/\d{2}/\d{4} \d{2}:\d{2}$' then return to_timestamp(v, 'DD/MM/YYYY HH24:MI')::timestamptz; end if;
  if v ~ '^\d{2}/\d{2}/\d{4}$' then return to_timestamp(v, 'DD/MM/YYYY')::timestamptz; end if;
  return v::timestamptz;
end;
$function$

CREATE OR REPLACE FUNCTION public.import_validate_row_v1(target_club uuid, p_target text, p_data jsonb)
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  e text[] := array[]::text[]; v text; n numeric; i integer; d1 timestamptz; d2 timestamptz;
begin
  if p_data is null or jsonb_typeof(p_data) <> 'object' then return array['Linha inválida.']; end if;
  case p_target
    when 'members' then
      if nullif(btrim(p_data->>'full_name'), '') is null then e := array_append(e, 'Nome completo é obrigatório.'); end if;
      v := nullif(btrim(p_data->>'member_number'), '');
      if v is not null then
        begin i := v::integer; if i <= 0 then e := array_append(e, 'Número de membro deve ser positivo.'); end if;
        exception when others then e := array_append(e, 'Número de membro inválido.'); end;
        if not ('Número de membro inválido.' = any(e)) and i is not null and exists (select 1 from public.members m where m.club_id=target_club and m.member_number=i) then e := array_append(e, 'Número de membro já existe.'); end if;
      end if;
      v := coalesce(nullif(btrim(p_data->>'status'), ''), 'active');
      if v not in ('active','suspended','honorary','former','prospect','full_color','deceased') then e := array_append(e, 'Estado do membro inválido.'); end if;
      foreach v in array array[p_data->>'birth_date',p_data->>'joined_at',p_data->>'prospect_joined_at',p_data->>'full_colors_at'] loop
        if nullif(btrim(v), '') is not null then begin perform public.import_parse_date_v1(v); exception when others then e:=array_append(e,'Existe uma data inválida.'); exit; end; end if;
      end loop;
    when 'inventory_products' then
      if nullif(btrim(p_data->>'name'), '') is null then e:=array_append(e,'Nome do produto é obrigatório.'); end if;
      v:=coalesce(nullif(btrim(p_data->>'inventory_area'),''),'shop'); if v not in ('shop','bar') then e:=array_append(e,'Área deve ser shop ou bar.'); end if;
      foreach v in array array[p_data->>'cost',p_data->>'sale_price',p_data->>'minimum_stock',p_data->>'units_per_purchase',p_data->>'purchase_cost'] loop
        if nullif(btrim(v),'') is not null then begin n:=public.import_parse_numeric_v1(v,0); if n<0 then e:=array_append(e,'Valores numéricos não podem ser negativos.'); exit; end if; exception when others then e:=array_append(e,'Existe um valor numérico inválido.'); exit; end; end if;
      end loop;
      foreach v in array array[p_data->>'active',p_data->>'institutional_delivery'] loop
        if nullif(btrim(v),'') is not null then begin perform public.import_parse_boolean_v1(v,false); exception when others then e:=array_append(e,'Existe um valor Sim/Não inválido.'); exit; end; end if;
      end loop;
    when 'events' then
      if nullif(btrim(p_data->>'name'),'') is null then e:=array_append(e,'Nome do evento é obrigatório.'); end if;
      v:=coalesce(nullif(btrim(p_data->>'status'),''),'draft'); if v not in ('draft','published','active','completed','cancelled') then e:=array_append(e,'Estado do evento inválido.'); end if;
      begin d1:=public.import_parse_timestamptz_v1(p_data->>'starts_at'); exception when others then e:=array_append(e,'Data/hora de início inválida.'); end;
      begin d2:=public.import_parse_timestamptz_v1(p_data->>'ends_at'); exception when others then e:=array_append(e,'Data/hora de fim inválida.'); end;
      if d1 is not null and d2 is not null and d2<d1 then e:=array_append(e,'Fim não pode ser anterior ao início.'); end if;
      v:=nullif(btrim(p_data->>'capacity'),''); if v is not null then begin i:=v::integer; if i<0 then e:=array_append(e,'Capacidade não pode ser negativa.'); end if; exception when others then e:=array_append(e,'Capacidade inválida.'); end; end if;
      v:=nullif(btrim(p_data->>'budget'),''); if v is not null then begin n:=public.import_parse_numeric_v1(v,0); if n<0 then e:=array_append(e,'Orçamento não pode ser negativo.'); end if; exception when others then e:=array_append(e,'Orçamento inválido.'); end; end if;
    when 'fee_plans' then
      if nullif(btrim(p_data->>'name'),'') is null then e:=array_append(e,'Nome do plano é obrigatório.'); end if;
      begin n:=public.import_parse_numeric_v1(p_data->>'amount',null); if n is null then e:=array_append(e,'Valor é obrigatório.'); elsif n<0 then e:=array_append(e,'Valor não pode ser negativo.'); end if; exception when others then e:=array_append(e,'Valor inválido.'); end;
      v:=coalesce(nullif(btrim(p_data->>'frequency'),''),'monthly'); if v not in ('monthly','quarterly','annual','custom') then e:=array_append(e,'Frequência inválida.'); end if;
      v:=nullif(btrim(p_data->>'due_day'),''); if v is not null then begin i:=v::integer; if i<1 or i>31 then e:=array_append(e,'Dia de vencimento deve estar entre 1 e 31.'); end if; exception when others then e:=array_append(e,'Dia de vencimento inválido.'); end; end if;
      v:=nullif(btrim(p_data->>'active'),''); if v is not null then begin perform public.import_parse_boolean_v1(v,true); exception when others then e:=array_append(e,'Ativo deve ser Sim/Não.'); end; end if;
    else e:=array_append(e,'Destino de importação inválido.');
  end case;
  return e;
end;
$function$

CREATE OR REPLACE FUNCTION public.inventory_advanced_maintenance_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_reservations integer; v_lots integer;
begin
  v_reservations:=public.inventory_expire_reservations_internal_v1(null);
  v_lots:=public.inventory_refresh_lot_status_internal_v1(null);
  return jsonb_build_object('expired_reservations',v_reservations,'updated_lots',v_lots,'ran_at',now());
end $function$

CREATE OR REPLACE FUNCTION public.inventory_advanced_summary_v1(target_club uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_manage boolean; v_member uuid; v_active int:=0; v_expiring int:=0; v_lots int:=0; v_expired int:=0; v_breakages numeric:=0;
begin
 if not public.has_club_permission(target_club,'viewInventory') then raise exception 'Sem permissão para consultar inventário.'; end if;
 v_manage:=public.has_club_permission(target_club,'manageInventory'); perform public.inventory_expire_reservations_internal_v1(target_club); perform public.inventory_refresh_lot_status_internal_v1(target_club);
 if not v_manage then select m.id into v_member from public.members m where m.club_id=target_club and m.profile_id=auth.uid() order by m.created_at limit 1; end if;
 select count(*),count(*) filter(where expires_at<=now()+interval '3 days') into v_active,v_expiring from public.stock_reservations r where r.club_id=target_club and r.status='active' and (v_manage or r.member_id=v_member);
 if v_manage then select count(*) filter(where status='active' and expires_at is not null and expires_at<=current_date+30),count(*) filter(where status='expired' and quantity>0) into v_lots,v_expired from public.stock_lots where club_id=target_club; select coalesce(sum(quantity),0) into v_breakages from public.stock_breakages where club_id=target_club and created_at>=date_trunc('month',now()); end if;
 return jsonb_build_object('active_reservations',v_active,'reservations_expiring_soon',v_expiring,'lots_expiring_30d',v_lots,'expired_lots',v_expired,'breakage_units_month',v_breakages,'can_manage',v_manage);
end $function$

CREATE OR REPLACE FUNCTION public.inventory_balance_apply_internal_v1(target_club uuid, p_product uuid, p_variant uuid, p_location uuid, p_quantity_delta numeric, p_reserved_delta numeric DEFAULT 0)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  v_quantity numeric;
  v_reserved numeric;
  v_new_quantity numeric;
  v_new_reserved numeric;
begin
  if not exists (
    select 1 from public.products p
    where p.id=p_product and p.club_id=target_club
  ) then raise exception 'Produto inválido para o clube.'; end if;
  if p_variant is not null and not exists (
    select 1 from public.product_variants pv
    where pv.id=p_variant and pv.product_id=p_product
  ) then raise exception 'Variante inválida para o produto.'; end if;
  if not exists (
    select 1 from public.inventory_locations l
    where l.id=p_location and l.club_id=target_club and l.active=true
  ) then raise exception 'Local de inventário inválido.'; end if;

  select id,quantity,reserved_quantity into v_id,v_quantity,v_reserved
  from public.inventory_stock_balances b
  where b.club_id=target_club and b.product_id=p_product
    and b.location_id=p_location
    and b.variant_id is not distinct from p_variant
  for update;

  if v_id is null then
    v_quantity:=0;
    v_reserved:=0;
  end if;
  v_new_quantity:=v_quantity+coalesce(p_quantity_delta,0);
  v_new_reserved:=v_reserved+coalesce(p_reserved_delta,0);
  if v_new_quantity<0 then raise exception 'Stock insuficiente no local selecionado.'; end if;
  if v_new_reserved<0 or v_new_reserved>v_new_quantity then
    raise exception 'Reserva inválida para o stock do local.';
  end if;

  if v_id is null then
    insert into public.inventory_stock_balances(
      club_id,product_id,variant_id,location_id,quantity,reserved_quantity,updated_by
    ) values (
      target_club,p_product,p_variant,p_location,v_new_quantity,v_new_reserved,auth.uid()
    );
  else
    update public.inventory_stock_balances
    set quantity=v_new_quantity,
        reserved_quantity=v_new_reserved,
        updated_at=now(),
        updated_by=auth.uid()
    where id=v_id;
  end if;
end $function$

CREATE OR REPLACE FUNCTION public.inventory_breakage_record_v1(target_club uuid, p_product uuid, p_variant uuid, p_location uuid, p_quantity numeric, p_reason text DEFAULT 'breakage'::text, p_lot uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_product public.products%rowtype; v_lot public.stock_lots%rowtype; v_cost numeric:=0; v_movement uuid; v_breakage uuid; v_remaining numeric; x record; v_take numeric;
begin
 if not public.has_club_permission(target_club,'manageInventory') then raise exception 'Sem permissão para registar quebras/perdas.'; end if;
 if p_quantity is null or p_quantity<=0 then raise exception 'Quantidade inválida.'; end if;
 if p_reason not in ('breakage','expiry','damage','loss','other') then raise exception 'Motivo inválido.'; end if;
 select * into v_product from public.products where id=p_product and club_id=target_club and active=true; if not found then raise exception 'Produto não encontrado.'; end if;
 if p_variant is not null and not exists(select 1 from public.product_variants where id=p_variant and product_id=p_product and active=true) then raise exception 'Variante inválida.'; end if;
 if p_lot is not null then
   select * into v_lot from public.stock_lots l where l.id=p_lot and l.club_id=target_club and l.product_id=p_product and l.variant_id is not distinct from p_variant and l.location_id=p_location for update;
   if not found then raise exception 'Lote inválido para o artigo/local selecionado.'; end if;
   if v_lot.quantity<p_quantity then raise exception 'Quantidade superior ao stock do lote.'; end if;
   update public.stock_lots set quantity=quantity-p_quantity,updated_at=now() where id=v_lot.id; v_cost:=coalesce(v_lot.unit_cost,0);
 else
   v_remaining:=p_quantity;
   for x in select l.id,l.quantity,l.unit_cost from public.stock_lots l where l.club_id=target_club and l.product_id=p_product and l.variant_id is not distinct from p_variant and l.location_id=p_location and l.quantity>0 and l.status<>'quarantined' order by l.expires_at nulls last,l.received_at,l.created_at for update loop
     exit when v_remaining<=0; v_take:=least(v_remaining,x.quantity); update public.stock_lots set quantity=quantity-v_take,updated_at=now() where id=x.id; if v_cost=0 and x.unit_cost is not null then v_cost:=x.unit_cost; end if; v_remaining:=v_remaining-v_take;
   end loop;
 end if;
 perform public.inventory_balance_apply_internal_v1(target_club,p_product,p_variant,p_location,-p_quantity,0);
 perform public.inventory_sync_aggregate_stock_v1(target_club,p_product,p_variant);
 perform public.inventory_refresh_lot_status_internal_v1(target_club);
 if v_cost=0 then if p_variant is null then v_cost:=coalesce(v_product.cost,0); else select coalesce(pv.cost,v_product.cost,0) into v_cost from public.product_variants pv where pv.id=p_variant; end if; end if;
 insert into public.stock_movements(club_id,product_id,variant_id,kind,quantity,unit_cost,notes,created_by,from_location_id)
 values(target_club,p_product,p_variant,'loss',-p_quantity,coalesce(v_cost,0),'Quebra/perda ('||p_reason||')'||case when nullif(trim(coalesce(p_notes,'')),'') is null then '' else ': '||trim(p_notes) end,auth.uid(),p_location) returning id into v_movement;
 insert into public.stock_breakages(club_id,product_id,variant_id,location_id,lot_id,quantity,reason,unit_cost,notes,stock_movement_id,created_by)
 values(target_club,p_product,p_variant,p_location,p_lot,p_quantity,p_reason,coalesce(v_cost,0),nullif(trim(coalesce(p_notes,'')),''),v_movement,auth.uid()) returning id into v_breakage;
 return v_breakage;
end $function$

CREATE OR REPLACE FUNCTION public.inventory_count_finalize_v1(target_club uuid, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  s public.inventory_count_sessions%rowtype;
  adjusted int:=0;
  total_diff numeric:=0;
  value_diff numeric:=0;
begin
  if not public.has_club_permission(target_club,'performInventoryCount') then
    raise exception 'Sem permissão para concluir inventário físico.';
  end if;
  select * into s from public.inventory_count_sessions
  where id=p_session and club_id=target_club and status in ('counting','review')
  for update;
  if not found then raise exception 'Sessão não encontrada ou já concluída.'; end if;
  if exists(select 1 from public.inventory_count_items where session_id=p_session and counted_qty is null) then
    raise exception 'Existem artigos por contar.';
  end if;
  if exists(select 1 from public.inventory_count_items where session_id=p_session and counted_qty<0) then
    raise exception 'Existem quantidades negativas na contagem.';
  end if;

  if s.location_id is not null then
    perform set_config('bob.skip_stock_balance_sync','1',true);
  end if;

  for r in select * from public.inventory_count_items where session_id=p_session loop
    if r.difference<>0 then
      if s.location_id is null then
        if r.variant_id is null then
          update public.products set current_stock=r.counted_qty
          where id=r.product_id and club_id=target_club;
        else
          update public.product_variants set current_stock=r.counted_qty
          where id=r.variant_id and product_id=r.product_id;
        end if;
      else
        -- O teórico é o saldo do local; substituir pelo contado equivale a aplicar a diferença.
        perform public.inventory_balance_apply_internal_v1(
          target_club,r.product_id,r.variant_id,s.location_id,r.difference,0
        );
        if r.variant_id is null then
          update public.products p
          set current_stock=(
            select coalesce(sum(b.quantity),0) from public.inventory_stock_balances b
            where b.club_id=target_club and b.product_id=p.id and b.variant_id is null
          )
          where p.id=r.product_id and p.club_id=target_club;
        else
          update public.product_variants pv
          set current_stock=(
            select coalesce(sum(b.quantity),0) from public.inventory_stock_balances b
            where b.club_id=target_club and b.product_id=r.product_id and b.variant_id=pv.id
          )
          where pv.id=r.variant_id and pv.product_id=r.product_id;
        end if;
      end if;

      insert into public.stock_movements(
        club_id,product_id,variant_id,kind,quantity,unit_cost,notes,created_by,
        from_location_id,to_location_id
      ) values (
        target_club,r.product_id,r.variant_id,'adjustment',r.difference,r.unit_cost,
        'Ajuste por inventário físico '||p_session::text,auth.uid(),
        case when r.difference<0 then s.location_id else null end,
        case when r.difference>0 then s.location_id else null end
      );
      adjusted:=adjusted+1;
      total_diff:=total_diff+r.difference;
      value_diff:=value_diff+(r.difference*r.unit_cost);
    end if;
  end loop;

  update public.products p
  set current_stock=(select coalesce(sum(pv.current_stock),0) from public.product_variants pv where pv.product_id=p.id and pv.active=true)
  where p.club_id=target_club
    and exists(select 1 from public.inventory_count_items i where i.session_id=p_session and i.product_id=p.id and i.variant_id is not null);

  if s.location_id is not null then
    perform set_config('bob.skip_stock_balance_sync','0',true);
  end if;

  update public.inventory_count_sessions
  set status='completed',completed_by=auth.uid(),completed_at=now()
  where id=p_session and club_id=target_club;

  return jsonb_build_object(
    'adjusted_items',adjusted,
    'net_quantity_difference',total_diff,
    'value_difference',value_diff,
    'location_id',s.location_id
  );
end $function$

CREATE OR REPLACE FUNCTION public.inventory_count_start_v1(target_club uuid, p_name text, p_location uuid DEFAULT NULL::uuid, p_event uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid;
begin
  if not public.has_club_permission(target_club,'performInventoryCount') then
    raise exception 'Sem permissão para realizar inventário físico.';
  end if;
  if p_location is not null and not exists (
    select 1 from public.inventory_locations l
    where l.id=p_location and l.club_id=target_club and l.active=true
  ) then raise exception 'Local de inventário inválido para este clube.'; end if;
  if p_event is not null and not exists (
    select 1 from public.events e where e.id=p_event and e.club_id=target_club
  ) then raise exception 'Evento inválido para este clube.'; end if;

  insert into public.inventory_count_sessions(club_id,name,location_id,event_id,status,notes,started_by)
  values(target_club,coalesce(nullif(trim(p_name),''),'Inventário físico'),p_location,p_event,'counting',nullif(trim(p_notes),''),auth.uid())
  returning id into sid;

  insert into public.inventory_count_items(session_id,product_id,variant_id,theoretical_qty,unit_cost)
  select sid,p.id,pv.id,
         case when p_location is null then pv.current_stock else coalesce(b.quantity,0) end,
         coalesce(pv.cost,p.cost,0)
  from public.products p
  join public.product_variants pv on pv.product_id=p.id and pv.active=true
  left join public.inventory_stock_balances b
    on b.club_id=p.club_id and b.product_id=p.id and b.variant_id=pv.id and b.location_id=p_location
  where p.club_id=target_club and p.active=true;

  insert into public.inventory_count_items(session_id,product_id,variant_id,theoretical_qty,unit_cost)
  select sid,p.id,null,
         case when p_location is null then p.current_stock else coalesce(b.quantity,0) end,
         coalesce(p.cost,0)
  from public.products p
  left join public.inventory_stock_balances b
    on b.club_id=p.club_id and b.product_id=p.id and b.variant_id is null and b.location_id=p_location
  where p.club_id=target_club and p.active=true
    and not exists(select 1 from public.product_variants pv where pv.product_id=p.id and pv.active=true);

  return sid;
end $function$

CREATE OR REPLACE FUNCTION public.inventory_expire_reservations_internal_v1(target_club uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v_count integer:=0;
begin
  for r in select id,club_id,product_id,variant_id,location_id,quantity from public.stock_reservations
    where status='active' and expires_at<=now() and (target_club is null or club_id=target_club)
    order by expires_at,id for update skip locked
  loop
    update public.inventory_stock_balances b
    set reserved_quantity=greatest(0,b.reserved_quantity-r.quantity),updated_at=now(),updated_by=null
    where b.club_id=r.club_id and b.product_id=r.product_id and b.variant_id is not distinct from r.variant_id and b.location_id=r.location_id;
    perform public.inventory_sync_aggregate_stock_v1(r.club_id,r.product_id,r.variant_id);
    update public.stock_reservations set status='expired',released_at=now(),release_reason='Prazo de 30 dias atingido',updated_at=now() where id=r.id;
    v_count:=v_count+1;
  end loop;
  return v_count;
end $function$

CREATE OR REPLACE FUNCTION public.inventory_lot_receive_v1(target_club uuid, p_product uuid, p_variant uuid, p_location uuid, p_lot_code text, p_quantity numeric, p_received_at date DEFAULT CURRENT_DATE, p_expires_at date DEFAULT NULL::date, p_unit_cost numeric DEFAULT NULL::numeric, p_supplier text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_lot public.stock_lots%rowtype;
begin
 if not public.has_club_permission(target_club,'manageInventory') then raise exception 'Sem permissão para receber lotes.'; end if;
 if p_quantity is null or p_quantity<=0 then raise exception 'Quantidade inválida.'; end if;
 if nullif(trim(coalesce(p_lot_code,'')),'') is null then raise exception 'Indica o número/código do lote.'; end if;
 if p_expires_at is not null and p_expires_at<coalesce(p_received_at,current_date) then raise exception 'A validade não pode ser anterior à receção.'; end if;
 if p_expires_at is not null and p_expires_at<current_date then raise exception 'Não é possível receber um lote já expirado.'; end if;
 if p_unit_cost is not null and p_unit_cost<0 then raise exception 'Custo inválido.'; end if;
 if not exists(select 1 from public.products p where p.id=p_product and p.club_id=target_club and p.active=true) then raise exception 'Produto não encontrado.'; end if;
 if p_variant is not null and not exists(select 1 from public.product_variants where id=p_variant and product_id=p_product and active=true) then raise exception 'Variante inválida.'; end if;
 if not exists(select 1 from public.inventory_locations where id=p_location and club_id=target_club and active=true) then raise exception 'Localização inválida.'; end if;
 select * into v_lot from public.stock_lots l where l.club_id=target_club and l.product_id=p_product and l.variant_id is not distinct from p_variant and l.location_id=p_location and lower(l.lot_code)=lower(trim(p_lot_code)) for update;
 if found then
   if v_lot.status='quarantined' then raise exception 'O lote existente está em quarentena.'; end if;
   update public.stock_lots set initial_quantity=initial_quantity+p_quantity,quantity=quantity+p_quantity,received_at=least(received_at,coalesce(p_received_at,current_date)),expires_at=coalesce(p_expires_at,expires_at),unit_cost=coalesce(p_unit_cost,unit_cost),supplier=coalesce(nullif(trim(coalesce(p_supplier,'')),''),supplier),notes=coalesce(nullif(trim(coalesce(p_notes,'')),''),notes),status='active',updated_at=now() where id=v_lot.id returning * into v_lot;
 else
   insert into public.stock_lots(club_id,product_id,variant_id,location_id,lot_code,received_at,expires_at,initial_quantity,quantity,unit_cost,supplier,status,notes,created_by)
   values(target_club,p_product,p_variant,p_location,trim(p_lot_code),coalesce(p_received_at,current_date),p_expires_at,p_quantity,p_quantity,p_unit_cost,nullif(trim(coalesce(p_supplier,'')),''),'active',nullif(trim(coalesce(p_notes,'')),''),auth.uid()) returning * into v_lot;
 end if;
 perform public.inventory_balance_apply_internal_v1(target_club,p_product,p_variant,p_location,p_quantity,0);
 perform public.inventory_sync_aggregate_stock_v1(target_club,p_product,p_variant);
 insert into public.stock_movements(club_id,product_id,variant_id,kind,quantity,unit_cost,notes,created_by,to_location_id)
 select target_club,p_product,p_variant,'purchase',p_quantity,coalesce(p_unit_cost,pv.cost,p.cost,0),'Entrada do lote '||v_lot.lot_code,auth.uid(),p_location from public.products p left join public.product_variants pv on pv.id=p_variant where p.id=p_product;
 return v_lot.id;
end $function$

CREATE OR REPLACE FUNCTION public.inventory_operation_v1(target_club uuid, p_product uuid, p_operation text, p_quantity numeric, p_unit_price numeric DEFAULT NULL::numeric, p_description text DEFAULT NULL::text, p_payment_method text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_product public.products%rowtype; v_new_stock numeric; v_new_reserved numeric; v_account uuid; v_cost_center uuid; v_transaction uuid; v_kind public.stock_movement_kind; v_total numeric;
begin
  if p_operation='sale' then
    if not public.has_club_permission(target_club,'sellInventory') then raise exception 'Sem autorização para registar vendas.'; end if;
  elsif not public.has_club_permission(target_club,'manageInventory') then raise exception 'Sem autorização para gerir inventário.'; end if;
  if p_quantity<=0 then raise exception 'A quantidade deve ser superior a zero.'; end if;
  select * into v_product from public.products where id=p_product and club_id=target_club and active=true for update; if not found then raise exception 'Artigo não encontrado ou inativo.'; end if;
  v_new_stock:=v_product.current_stock; v_new_reserved:=v_product.reserved_stock;
  if p_operation='entry' then v_new_stock:=v_new_stock+p_quantity; v_kind:='purchase';
  elsif p_operation='adjustment_in' then v_new_stock:=v_new_stock+p_quantity; v_kind:='adjustment';
  elsif p_operation='adjustment_out' then v_new_stock:=v_new_stock-p_quantity; v_kind:='adjustment';
  elsif p_operation='reserve' then if v_new_stock-v_new_reserved<p_quantity then raise exception 'Stock disponível insuficiente para a reserva.'; end if; v_new_reserved:=v_new_reserved+p_quantity; v_kind:='transfer';
  elsif p_operation='release' then if v_new_reserved<p_quantity then raise exception 'Reserva insuficiente.'; end if; v_new_reserved:=v_new_reserved-p_quantity; v_kind:='return';
  elsif p_operation='sale' then if v_new_stock-v_new_reserved<p_quantity then raise exception 'Stock disponível insuficiente para a venda.'; end if; v_new_stock:=v_new_stock-p_quantity; v_kind:='sale';
  else raise exception 'Operação de inventário inválida.'; end if;
  if v_new_stock<0 or v_new_reserved<0 or v_new_reserved>v_new_stock then raise exception 'O stock não pode ficar negativo nem abaixo do stock reservado.'; end if;
  update public.products set current_stock=v_new_stock,reserved_stock=v_new_reserved where id=v_product.id;
  insert into public.stock_movements(club_id,product_id,kind,quantity,unit_cost,notes,created_by) values(target_club,v_product.id,v_kind,case when p_operation in ('adjustment_out','sale') then -p_quantity else p_quantity end,coalesce(p_unit_price,v_product.cost),nullif(trim(coalesce(p_description,'')),''),auth.uid());
  if p_operation='sale' then v_total:=p_quantity*coalesce(p_unit_price,v_product.sale_price); select id into v_account from public.treasury_accounts where club_id=target_club and active=true and lower(name)=lower('Club House') limit 1; if v_account is null then raise exception 'Conta Club House não encontrada.'; end if; select id into v_cost_center from public.cost_centers where club_id=target_club and active=true and lower(name)=lower('Club House') limit 1; insert into public.treasury_transactions(club_id,kind,account_id,cost_center_id,transaction_date,description,amount,payment_method,source_type,source_id,created_by) values(target_club,'income',v_account,v_cost_center,current_date,coalesce(nullif(trim(coalesce(p_description,'')),''),'Venda '||v_product.name),v_total,p_payment_method,'inventory_sale',v_product.id,auth.uid()) returning id into v_transaction; end if;
  return jsonb_build_object('product_id',v_product.id,'current_stock',v_new_stock,'reserved_stock',v_new_reserved,'transaction_id',v_transaction);
end; $function$

CREATE OR REPLACE FUNCTION public.inventory_product_balance_sync_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_old_stock numeric:=0;
  v_old_reserved numeric:=0;
  v_location uuid;
begin
  if coalesce(current_setting('bob.skip_stock_balance_sync',true),'')='1' then return new; end if;
  if exists(select 1 from public.product_variants pv where pv.product_id=new.id and pv.active=true) then return new; end if;
  if tg_op='UPDATE' then
    v_old_stock:=coalesce(old.current_stock,0);
    v_old_reserved:=coalesce(old.reserved_stock,0);
  end if;
  v_location:=public.inventory_default_location_v1(new.club_id,new.inventory_area);
  perform public.inventory_balance_apply_internal_v1(
    new.club_id,new.id,null,v_location,
    coalesce(new.current_stock,0)-v_old_stock,
    coalesce(new.reserved_stock,0)-v_old_reserved
  );
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.inventory_reservation_close_v1(target_club uuid, p_reservation uuid, p_action text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.stock_reservations%rowtype; v_status text; v_is_owner boolean;
begin
  if p_action not in ('cancel','release') then raise exception 'Ação de reserva inválida.'; end if;
  select * into r from public.stock_reservations where id=p_reservation and club_id=target_club and status='active' for update;
  if not found then raise exception 'Reserva não encontrada ou já encerrada.'; end if;
  select exists(select 1 from public.members m where m.id=r.member_id and m.profile_id=auth.uid()) into v_is_owner;
  if p_action='cancel' then
    if not (v_is_owner or public.has_club_permission(target_club,'manageInventory')) then raise exception 'Sem permissão para cancelar esta reserva.'; end if;
    v_status:='cancelled';
  else
    if not public.has_club_permission(target_club,'manageInventory') then raise exception 'Sem permissão para libertar reservas.'; end if;
    v_status:='released';
  end if;
  perform public.inventory_balance_apply_internal_v1(target_club,r.product_id,r.variant_id,r.location_id,0,-r.quantity);
  perform public.inventory_sync_aggregate_stock_v1(target_club,r.product_id,r.variant_id);
  update public.stock_reservations set status=v_status,released_at=now(),released_by=auth.uid(),release_reason=coalesce(nullif(trim(coalesce(p_reason,'')),''),case when v_status='cancelled' then 'Cancelada pelo membro' else 'Libertada pelo responsável' end),updated_at=now() where id=r.id;
  return jsonb_build_object('reservation_id',r.id,'status',v_status,'quantity',r.quantity);
end $function$

CREATE OR REPLACE FUNCTION public.inventory_reservation_create_v1(target_club uuid, p_product uuid, p_variant uuid, p_location uuid, p_quantity numeric, p_member uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_member uuid; v_balance public.inventory_stock_balances%rowtype; v_expired numeric:=0; v_reservation uuid;
begin
  if not public.has_club_permission(target_club,'viewInventory') then raise exception 'Sem permissão para reservar stock.'; end if;
  if p_quantity is null or p_quantity<=0 then raise exception 'A quantidade deve ser superior a zero.'; end if;
  perform public.inventory_expire_reservations_internal_v1(target_club);
  if p_member is null then
    select m.id into v_member from public.members m where m.club_id=target_club and m.profile_id=auth.uid() order by m.created_at limit 1;
  else v_member:=p_member; end if;
  if v_member is null or not exists(select 1 from public.members m where m.id=v_member and m.club_id=target_club) then raise exception 'Membro inválido para este clube.'; end if;
  if not public.has_club_permission(target_club,'manageInventory') and not exists(select 1 from public.members m where m.id=v_member and m.club_id=target_club and m.profile_id=auth.uid()) then raise exception 'Só pode criar reservas em seu próprio nome.'; end if;
  if not exists(select 1 from public.products p where p.id=p_product and p.club_id=target_club and p.active=true) then raise exception 'Produto não encontrado ou inativo.'; end if;
  if exists(select 1 from public.product_variants where product_id=p_product and active=true) and p_variant is null then raise exception 'Seleciona a variante do produto.'; end if;
  if p_variant is not null and not exists(select 1 from public.product_variants where id=p_variant and product_id=p_product and active=true) then raise exception 'Variante inválida.'; end if;
  select * into v_balance from public.inventory_stock_balances b where b.club_id=target_club and b.product_id=p_product and b.variant_id is not distinct from p_variant and b.location_id=p_location for update;
  if not found then raise exception 'Não existe stock nesse local.'; end if;
  select coalesce(sum(l.quantity),0) into v_expired from public.stock_lots l
   where l.club_id=target_club and l.product_id=p_product and l.variant_id is not distinct from p_variant and l.location_id=p_location and l.quantity>0
   and (l.status in ('expired','quarantined') or (l.expires_at is not null and l.expires_at<current_date));
  if v_balance.quantity-v_balance.reserved_quantity-v_expired<p_quantity then raise exception 'Stock disponível insuficiente para a reserva.'; end if;
  perform public.inventory_balance_apply_internal_v1(target_club,p_product,p_variant,p_location,0,p_quantity);
  perform public.inventory_sync_aggregate_stock_v1(target_club,p_product,p_variant);
  insert into public.stock_reservations(club_id,product_id,variant_id,location_id,member_id,quantity,status,reserved_at,expires_at,notes,created_by)
  values(target_club,p_product,p_variant,p_location,v_member,p_quantity,'active',now(),now()+interval '30 days',nullif(trim(coalesce(p_notes,'')),''),auth.uid()) returning id into v_reservation;
  return v_reservation;
end $function$

CREATE OR REPLACE FUNCTION public.inventory_reservations_v1(target_club uuid)
 RETURNS TABLE(id uuid, product_id uuid, product_name text, variant_id uuid, variant_name text, location_id uuid, location_name text, member_id uuid, member_name text, quantity numeric, status text, reserved_at timestamp with time zone, expires_at timestamp with time zone, days_remaining integer, notes text, can_cancel boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_manage boolean:=public.has_club_permission(target_club,'manageInventory');
begin
  if not public.has_club_permission(target_club,'viewInventory') then raise exception 'Sem permissão para consultar reservas.'; end if;
  perform public.inventory_expire_reservations_internal_v1(target_club);
  return query select r.id,r.product_id,p.name,r.variant_id,pv.name,r.location_id,l.name,r.member_id,m.full_name,r.quantity,r.status,r.reserved_at,r.expires_at,
    greatest(0,ceil(extract(epoch from (r.expires_at-now()))/86400.0)::int),r.notes,(v_manage or m.profile_id=auth.uid())
  from public.stock_reservations r join public.products p on p.id=r.product_id left join public.product_variants pv on pv.id=r.variant_id join public.inventory_locations l on l.id=r.location_id join public.members m on m.id=r.member_id
  where r.club_id=target_club and (v_manage or m.profile_id=auth.uid())
  order by case when r.status='active' then 0 else 1 end,r.expires_at,r.created_at desc;
end $function$

CREATE OR REPLACE FUNCTION public.inventory_stock_movement_location_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_club uuid; v_area text; v_location uuid;
begin
  if new.from_location_id is not null or new.to_location_id is not null or new.kind='transfer' then return new; end if;
  select club_id,inventory_area into v_club,v_area from public.products where id=new.product_id;
  if v_club is null then return new; end if;
  v_location:=public.inventory_default_location_v1(v_club,v_area);
  if new.quantity<0 then new.from_location_id:=v_location; else new.to_location_id:=v_location; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.inventory_transfer_v1(target_club uuid, p_product uuid, p_variant uuid, p_from_location uuid, p_to_location uuid, p_quantity numeric, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_product public.products%rowtype;
  v_cost numeric;
  v_group uuid:=gen_random_uuid();
  v_source numeric;
  v_destination numeric;
begin
  if not public.has_club_permission(target_club,'manageInventory') then
    raise exception 'Sem permissão para transferir stock.';
  end if;
  if p_quantity is null or p_quantity<=0 then raise exception 'A quantidade deve ser superior a zero.'; end if;
  if p_from_location is null or p_to_location is null or p_from_location=p_to_location then
    raise exception 'Seleciona locais de origem e destino diferentes.';
  end if;
  select * into v_product from public.products
  where id=p_product and club_id=target_club and active=true;
  if not found then raise exception 'Produto não encontrado ou inativo.'; end if;
  if exists(select 1 from public.product_variants where product_id=p_product and active=true) and p_variant is null then
    raise exception 'Seleciona a variante do produto.';
  end if;
  if p_variant is not null and not exists(
    select 1 from public.product_variants where id=p_variant and product_id=p_product and active=true
  ) then raise exception 'Variante inválida.'; end if;
  if not exists(select 1 from public.inventory_locations where id=p_from_location and club_id=target_club and active=true)
     or not exists(select 1 from public.inventory_locations where id=p_to_location and club_id=target_club and active=true) then
    raise exception 'Local de inventário inválido.';
  end if;

  perform public.inventory_balance_apply_internal_v1(target_club,p_product,p_variant,p_from_location,-p_quantity,0);
  perform public.inventory_balance_apply_internal_v1(target_club,p_product,p_variant,p_to_location,p_quantity,0);

  select coalesce(pv.cost,v_product.cost) into v_cost
  from public.product_variants pv where pv.id=p_variant;
  if p_variant is null then v_cost:=v_product.cost; end if;

  insert into public.stock_movements(
    club_id,product_id,variant_id,kind,quantity,unit_cost,notes,created_by,
    from_location_id,to_location_id,transfer_group_id
  ) values (
    target_club,p_product,p_variant,'transfer',p_quantity,coalesce(v_cost,0),
    coalesce(nullif(trim(coalesce(p_notes,'')),''),'Transferência entre localizações'),auth.uid(),
    p_from_location,p_to_location,v_group
  );

  select quantity into v_source from public.inventory_stock_balances
  where club_id=target_club and product_id=p_product and location_id=p_from_location
    and variant_id is not distinct from p_variant;
  select quantity into v_destination from public.inventory_stock_balances
  where club_id=target_club and product_id=p_product and location_id=p_to_location
    and variant_id is not distinct from p_variant;

  return jsonb_build_object(
    'transfer_group_id',v_group,
    'product_id',p_product,
    'variant_id',p_variant,
    'from_location_id',p_from_location,
    'to_location_id',p_to_location,
    'quantity',p_quantity,
    'source_quantity',coalesce(v_source,0),
    'destination_quantity',coalesce(v_destination,0)
  );
end $function$

CREATE OR REPLACE FUNCTION public.inventory_variant_balance_sync_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_old_stock numeric:=0;
  v_old_reserved numeric:=0;
  v_club uuid;
  v_area text;
  v_location uuid;
begin
  if coalesce(current_setting('bob.skip_stock_balance_sync',true),'')='1' then return new; end if;
  select club_id,inventory_area into v_club,v_area from public.products where id=new.product_id;
  if tg_op='UPDATE' then
    v_old_stock:=coalesce(old.current_stock,0);
    v_old_reserved:=coalesce(old.reserved_stock,0);
  end if;
  v_location:=public.inventory_default_location_v1(v_club,v_area);
  -- Ao aparecer a primeira variante, o stock passa a ser controlado pelas variantes.
  delete from public.inventory_stock_balances
  where club_id=v_club and product_id=new.product_id and variant_id is null;
  perform public.inventory_balance_apply_internal_v1(
    v_club,new.product_id,new.id,v_location,
    coalesce(new.current_stock,0)-v_old_stock,
    coalesce(new.reserved_stock,0)-v_old_reserved
  );
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.link_weekly_dinner_expense_v1(target_club uuid, p_dinner uuid, p_transaction uuid, p_kind text, p_remove boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t public.treasury_transactions%rowtype; begin
  perform bob_dinner_private.require_access(target_club,true);
  perform 1 from public.weekly_dinners where id=p_dinner and club_id=target_club for update;
  if not found then raise exception 'Jantar não encontrado.'; end if;
  if exists(select 1 from public.weekly_dinner_finances where dinner_id=p_dinner and financial_status='closed') then
    raise exception 'Reabre o fecho financeiro.'; end if;
  if p_remove then
    delete from public.weekly_dinner_expenses where dinner_id=p_dinner and transaction_id=p_transaction and club_id=target_club;
    return;
  end if;
  select * into t from public.treasury_transactions where id=p_transaction and club_id=target_club for update;
  if not found or t.kind::text<>'expense' or t.reversal_of is not null
    or exists(select 1 from public.treasury_transactions where reversal_of=t.id) then
    raise exception 'Apenas despesas não revertidas do mesmo clube.'; end if;
  -- BAR/inventory purchases are already recognized through stock consumption.
  -- Linking them as food/other would silently count inventory costs twice.
  if t.source_type in ('bar','bar_purchase','bar_operation','inventory','stock_purchase') then
    raise exception 'Compra de stock: custo reconhecido através do consumo, não nesta ligação.'; end if;
  insert into public.weekly_dinner_expenses(club_id,dinner_id,transaction_id,cost_kind,created_by,updated_by)
    values(target_club,p_dinner,p_transaction,p_kind,auth.uid(),auth.uid());
end $function$

