end; $function$

CREATE OR REPLACE FUNCTION public.mark_weekly_officer_swap_applied_v1(target_club uuid, p_request uuid, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row public.weekly_officer_swap_requests%rowtype;
begin
  if not public.can_manage_weekly_officer_v1(target_club) then raise exception 'Sem autorização para concluir a troca.'; end if;
