CREATE OR REPLACE FUNCTION public.notify_financial_profile_v1(target_club uuid, p_profile uuid, p_request uuid, p_title text, p_body text, p_priority text DEFAULT 'normal'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_profile is null then return; end if;
  if not exists(select 1 from public.club_memberships cm where cm.club_id=target_club and cm.profile_id=p_profile and cm.active=true) then return; end if;
  if coalesce((select np.in_app_enabled from public.notification_preferences np where np.club_id=target_club and np.profile_id=p_profile and np.module_code='treasury'),true) then
