CREATE OR REPLACE FUNCTION public.pay_reimbursement_v1(target_club uuid, p_request uuid, p_account uuid, p_payment_method text, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.financial_requests%rowtype; tx uuid; member_profile uuid; member_name text; method text;
begin
  if not public.financial_manager_v1(target_club) then raise exception 'Sem autorização.'; end if;
  method:=lower(btrim(coalesce(p_payment_method,'')));
  if method not in ('cash','mbway','bank_transfer','other') then raise exception 'Método de pagamento inválido.'; end if;
  select * into r from public.financial_requests where id=p_request and club_id=target_club for update;
  if not found or r.request_type<>'reimbursement' or r.status<>'approved' then raise exception 'O reembolso não está aprovado para pagamento.'; end if;
  if not exists(select 1 from public.treasury_accounts a where a.id=p_account and a.club_id=target_club and a.active=true) then raise exception 'Conta financeira inválida.'; end if;
  if method<>'cash' and not exists(select 1 from public.financial_request_attachments a where a.request_id=p_request and a.kind='club_payment_proof') then raise exception 'Anexa o comprovativo do pagamento antes de liquidar.'; end if;
  select m.profile_id,coalesce(nullif(m.nickname,''),m.full_name) into member_profile,member_name from public.members m where m.id=r.member_id;
  insert into public.treasury_transactions(club_id,kind,account_id,transaction_date,description,amount,payment_method,notes,source_type,source_id,created_by)
  values(target_club,'expense',p_account,current_date,'Reembolso - '||coalesce(member_name,'Membro')||' - '||r.description,r.amount,method,nullif(btrim(coalesce(p_note,'')),''),'financial_reimbursement',p_request,auth.uid()) returning id into tx;
  update public.financial_requests set status='paid',payment_method=method,treasury_account_id=p_account,treasury_transaction_id=tx,paid_at=now(),paid_by=auth.uid() where id=p_request;
  perform public.notify_financial_profile_v1(target_club,member_profile,p_request,'Reembolso liquidado','O reembolso de '||to_char(r.amount,'FM999999990.00')||' € foi liquidado.','normal');
  perform public.financial_activity_v1(target_club,p_request,'Reembolso liquidado',coalesce(member_name,'Membro')||' · '||to_char(r.amount,'FM999999990.00')||' €');
  return tx;
end;
$function$

CREATE OR REPLACE FUNCTION public.poll_guard_update_internal_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_options integer;
begin
  if old.status <> 'draft' and (
    new.club_id is distinct from old.club_id or
    new.title is distinct from old.title or
    new.description is distinct from old.description or
    new.poll_type is distinct from old.poll_type or
    new.anonymous is distinct from old.anonymous or
    new.multiple_choice is distinct from old.multiple_choice or
    new.show_results_before_close is distinct from old.show_results_before_close or
    new.starts_at is distinct from old.starts_at or
    new.ends_at is distinct from old.ends_at or
    new.created_by is distinct from old.created_by
  ) then
    raise exception 'Uma votação publicada já não pode ser alterada; apenas encerrada ou cancelada.';
  end if;

  if old.status='draft' and new.status not in ('draft','published','cancelled') then
    raise exception 'Transição de estado inválida.';
  elsif old.status='published' and new.status not in ('published','closed','cancelled') then
    raise exception 'Transição de estado inválida.';
  elsif old.status in ('closed','cancelled') and new.status is distinct from old.status then
    raise exception 'Uma votação encerrada ou cancelada não pode ser reaberta.';
  end if;

  if old.status='draft' and new.status='published' then
    select count(*) into v_options from public.poll_options where poll_id=old.id;
    if v_options < 2 then raise exception 'São necessárias pelo menos duas opções para publicar.'; end if;
    if new.ends_at is not null and new.ends_at <= new.starts_at then
      raise exception 'O fecho tem de ser posterior à abertura.';
    end if;
  end if;

  new.updated_at:=now();
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.poll_option_guard_internal_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_poll uuid; v_club uuid; v_status text;
begin
  if tg_op='DELETE' then
    v_poll:=old.poll_id;
    v_club:=old.club_id;
  else
    v_poll:=new.poll_id;
    v_club:=new.club_id;
  end if;
  select status into v_status from public.polls where id=v_poll and club_id=v_club;
  if v_status is null then raise exception 'Votação não encontrada.'; end if;
  if v_status <> 'draft' then raise exception 'As opções só podem ser alteradas enquanto a votação está em rascunho.'; end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.poll_vote_validate_internal_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p public.polls%rowtype;
begin
  if auth.uid() is null or new.profile_id is distinct from auth.uid() then
    raise exception 'O voto só pode ser registado pelo próprio utilizador.';
  end if;
  select * into p from public.polls where id=new.poll_id and club_id=new.club_id;
  if not found then raise exception 'Votação não encontrada.'; end if;
  if p.status <> 'published' or now() < p.starts_at or (p.ends_at is not null and now() >= p.ends_at) then
    raise exception 'A votação não está aberta.';
  end if;
  if not public.poll_member_eligible_internal_v1(new.club_id,new.profile_id) then
    raise exception 'Utilizador não elegível para votar.';
  end if;
  if not exists(select 1 from public.poll_options o where o.id=new.option_id and o.poll_id=new.poll_id and o.club_id=new.club_id) then
    raise exception 'Opção inválida para esta votação.';
  end if;
  new.single_choice_guard:=not p.multiple_choice;
  new.created_at:=now();
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.preview_fee_payment_v1(target_club uuid, p_member uuid, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v_remaining numeric:=coalesce(p_amount,0); v_use numeric; v_allocations jsonb:='[]'::jsonb; v_credit numeric:=0;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageFees') then raise exception 'Sem autorização para receber quotas.'; end if;
  if v_remaining<=0 then raise exception 'O valor deve ser superior a zero.'; end if;
  if not exists(select 1 from public.members where id=p_member and club_id=target_club) then raise exception 'Membro inválido.'; end if;
  for r in select o.*,public.fee_obligation_outstanding_v1(o) outstanding from public.fee_obligations o
    where o.club_id=target_club and o.member_id=p_member and o.status not in('cancelled','exempt','paid') and public.fee_obligation_outstanding_v1(o)>0
    order by o.due_date nulls last,o.reference_year,o.reference_month nulls first,o.created_at
  loop
    exit when v_remaining<=0;
    v_use:=least(v_remaining,r.outstanding);
    v_allocations:=v_allocations||jsonb_build_array(jsonb_build_object('obligation_id',r.id,'reference_year',r.reference_year,'reference_month',r.reference_month,'obligation_type',r.obligation_type,'due_date',r.due_date,'amount',v_use,'outstanding_before',r.outstanding));
    v_remaining:=v_remaining-v_use;
  end loop;
  select coalesce(sum(amount),0) into v_credit from public.fee_credits where club_id=target_club and member_id=p_member;
  return jsonb_build_object('payment_amount',p_amount,'allocations',v_allocations,'allocated',p_amount-v_remaining,'excess_credit',v_remaining,'existing_credit',greatest(0,v_credit));
end;
$function$

CREATE OR REPLACE FUNCTION public.process_euromillions_official_result_v1(target_club uuid, p_draw_date date, p_draw_number text, p_numbers integer[], p_stars integer[], p_prizes jsonb DEFAULT '{}'::jsonb, p_source text DEFAULT 'official'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  rid uuid;
  fine_unit numeric;
  p record;
  hit_n int;
  hit_s int;
  miss_n int;
  miss_s int;
  cat int;
  prize numeric;
  prize_entry record;
begin
  if auth.role() = 'service_role' then
    if p_source is null or lower(p_source) = 'manual' then
      raise exception 'Importação oficial inválida.';
    end if;
  elsif auth.role() = 'authenticated' and auth.uid() is not null then
    if not exists (
      select 1
      from public.club_memberships cm
      where cm.club_id = target_club
        and cm.profile_id = auth.uid()
        and cm.active is true
    ) then
      raise exception 'Sem acesso ao clube.' using errcode = '42501';
    end if;
    if not exists (
      select 1
      from public.club_memberships cm
      where cm.club_id = target_club
        and cm.profile_id = auth.uid()
        and cm.active is true
        and lower(cm.access_role) in ('treasurer', 'super_admin', 'super admin')
    ) then
      raise exception 'Sem permissão para processar resultados.' using errcode = '42501';
    end if;
    if p_source is distinct from 'manual'
      or p_draw_number is not null
      or p_prizes is distinct from '{}'::jsonb then
      raise exception 'O processamento manual exige origem manual e não aceita número ou prémios oficiais.';
    end if;
  else
    raise exception 'Autenticação ou autorização inválida.' using errcode = '42501';
  end if;

  if p_draw_date is null
    or extract(isodow from p_draw_date) not in (2, 5)
    or p_draw_date > current_date then
    raise exception 'Data de sorteio inválida.';
  end if;

  if cardinality(p_numbers) is distinct from 5
    or (select count(distinct n) from unnest(p_numbers) as values_list(n)) <> 5
    or exists (select 1 from unnest(p_numbers) as values_list(n) where n is null or n < 1 or n > 50) then
    raise exception 'Resultado inválido: são necessários cinco números únicos entre 1 e 50.';
  end if;
  if cardinality(p_stars) is distinct from 2
    or (select count(distinct s) from unnest(p_stars) as values_list(s)) <> 2
    or exists (select 1 from unnest(p_stars) as values_list(s) where s is null or s < 1 or s > 12) then
    raise exception 'Resultado inválido: são necessárias duas estrelas únicas entre 1 e 12.';
  end if;

  if auth.role() = 'service_role' then
    if p_draw_number is null
      or p_draw_number !~ '^[0-9]{3}/[0-9]{4}$'
      or split_part(p_draw_number, '/', 2) <> extract(year from p_draw_date)::integer::text then
      raise exception 'Número oficial do sorteio inválido.';
    end if;
  end if;

  if p_prizes is null or jsonb_typeof(p_prizes) is distinct from 'object' then
    raise exception 'A tabela de prémios tem de ser um objeto JSON.';
  end if;
  for prize_entry in select key, value from jsonb_each(p_prizes)
  loop
    if prize_entry.key !~ '^(?:[1-9]|1[0-3])$'
      or jsonb_typeof(prize_entry.value) is distinct from 'number'
      or (prize_entry.value #>> '{}')::numeric <= 0 then
      raise exception 'Tabela de prémios inválida.';
    end if;
  end loop;

  insert into public.euromillions_results as existing(
    club_id,draw_date,numbers,stars,created_by,official_draw_number,prize_table,source,imported_at
  ) values(
    target_club,p_draw_date,p_numbers,p_stars,auth.uid(),p_draw_number,p_prizes,p_source,now()
  )
  on conflict (club_id,draw_date) do update set
    numbers=excluded.numbers,stars=excluded.stars,
    created_by=coalesce(excluded.created_by, existing.created_by),
    official_draw_number=excluded.official_draw_number,prize_table=excluded.prize_table,
    source=excluded.source,imported_at=excluded.imported_at
  returning existing.id into rid;

  select coalesce((select value::numeric from public.club_settings where club_id=target_club and key='euromillions_fine_per_miss'),0.10) into fine_unit;

  for p in select * from public.euromillions_players where club_id=target_club and status='active' loop
    hit_n := (select count(*) from unnest(p.numbers) n where n=any(p_numbers));
    hit_s := (select count(*) from unnest(p.stars) s where s=any(p_stars));
    miss_n := 5-hit_n;
    miss_s := 2-hit_s;

    insert into public.euromillions_fines(club_id,result_id,player_id,missed_numbers,missed_stars,fine_amount)
    values(target_club,rid,p.id,miss_n,miss_s,(miss_n+miss_s)*fine_unit)
    on conflict (result_id,player_id) do update set
      missed_numbers=excluded.missed_numbers,missed_stars=excluded.missed_stars,fine_amount=excluded.fine_amount;

    cat := public.euromillions_prize_category_v1(hit_n,hit_s);
    if cat is not null then
      prize := coalesce((p_prizes->>cat::text)::numeric,0);
      if prize > 0 then
        insert into public.euromillions_prizes(club_id,result_id,player_id,category,matched_numbers,matched_stars,prize_amount)
        values(target_club,rid,p.id,cat,hit_n,hit_s,prize)
        on conflict (result_id,player_id) do update set
          category=excluded.category,matched_numbers=excluded.matched_numbers,
          matched_stars=excluded.matched_stars,prize_amount=excluded.prize_amount;
      else
        delete from public.euromillions_prizes where result_id=rid and player_id=p.id and received_amount=0;
      end if;
    else
      delete from public.euromillions_prizes where result_id=rid and player_id=p.id and received_amount=0;
    end if;
  end loop;
  return rid;
end; $function$

CREATE OR REPLACE FUNCTION public.process_euromillions_result_v1(target_club uuid, p_draw_date date, p_numbers integer[], p_stars integer[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare rid uuid; fine_unit numeric; p record; mn int; ms int;
begin
  if not public.has_club_permission(target_club,'manageLottery') then raise exception 'Sem permissão para processar sorteios.'; end if;
  if cardinality(p_numbers)<>5 or cardinality(p_stars)<>2 then raise exception 'Resultado inválido.'; end if;
  insert into public.euromillions_results(club_id,draw_date,numbers,stars,created_by) values(target_club,p_draw_date,p_numbers,p_stars,auth.uid()) on conflict(club_id,draw_date) do update set numbers=excluded.numbers,stars=excluded.stars,created_by=excluded.created_by returning id into rid;
  select coalesce((select value::numeric from public.club_settings where club_id=target_club and key='euromillions_fine_per_miss'),0.10) into fine_unit;
  for p in select * from public.euromillions_players where club_id=target_club and status='active' loop mn:=5-(select count(*) from unnest(p.numbers) n where n=any(p_numbers)); ms:=2-(select count(*) from unnest(p.stars) s where s=any(p_stars)); insert into public.euromillions_fines(club_id,result_id,player_id,missed_numbers,missed_stars,fine_amount) values(target_club,rid,p.id,mn,ms,(mn+ms)*fine_unit) on conflict(result_id,player_id) do update set missed_numbers=excluded.missed_numbers,missed_stars=excluded.missed_stars,fine_amount=excluded.fine_amount; end loop;
  return rid;
end; $function$

CREATE OR REPLACE FUNCTION public.profile_has_club_permission(target_club uuid, target_profile uuid, p_permission text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text; v_override boolean; v_base boolean;
begin
  select access_role into v_role from public.club_memberships
   where club_id=target_club and profile_id=target_profile and active=true limit 1;
  if v_role is null then return false; end if;
  if v_role='super_admin' then return true; end if;
  select allowed into v_override from public.user_permission_overrides
   where club_id=target_club and profile_id=target_profile and permission_key=p_permission;
  if found then return v_override; end if;
  select allowed into v_base from public.club_role_permissions
   where club_id=target_club and role_key=v_role and permission_key=p_permission;
  return coalesce(v_base,false);
end; $function$

CREATE OR REPLACE FUNCTION public.protect_member_milestone_dates_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op='INSERT' then
    if (new.prospect_joined_at is not null or new.full_colors_at is not null)
       and not public.can_edit_member_milestone_dates_v1(new.club_id) then
      raise exception using errcode='42501', message='Apenas Superadmin, Presidente ou Vice-Presidente podem definir as datas de Prospect e Full Color.';
    end if;
  elsif tg_op='UPDATE' then
    if (new.prospect_joined_at is distinct from old.prospect_joined_at
        or new.full_colors_at is distinct from old.full_colors_at)
       and not public.can_edit_member_milestone_dates_v1(new.club_id) then
      raise exception using errcode='42501', message='Apenas Superadmin, Presidente ou Vice-Presidente podem alterar as datas de Prospect e Full Color.';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_profile_privileges()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller_role public.user_role;
begin
  select role into caller_role
  from public.profiles
  where id = auth.uid();

  if caller_role = 'admin' and new.role = 'super_admin' then
    raise exception 'Apenas um superadministrador pode atribuir este perfil.';
  end if;

  if old.id = auth.uid() and old.active = true and new.active = false then
    raise exception 'Não é possível desativar a própria conta.';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.rebuild_weekly_officer_future_internal_v1(target_club uuid, p_from_date date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_year record; v_start date; v_end date;
begin
  for v_year in select distinct extract(year from d.dinner_date)::int as year_no from public.weekly_dinners d
    where d.club_id=target_club and d.dinner_kind='regular' and d.dinner_date>=p_from_date order by 1
  loop
    v_start:=greatest(p_from_date,make_date(v_year.year_no,1,1)); v_end:=make_date(v_year.year_no,12,31);
    perform public.rebuild_weekly_officer_schedule_internal_v1(target_club,v_start,v_end);
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.rebuild_weekly_officer_schedule_internal_v1(target_club uuid, p_from_date date, p_through_date date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_dinner record; v_member uuid; v_year int;
begin
  if p_through_date < p_from_date then return; end if;
  update public.weekly_dinners d set assigned_member_id=null,updated_at=now(),updated_by=coalesce((select auth.uid()),updated_by)
  where d.club_id=target_club and d.dinner_kind='regular' and d.status='planned' and d.assignment_source='auto'
    and d.dinner_date between p_from_date and p_through_date;
  for v_dinner in
    select d.id,d.dinner_date from public.weekly_dinners d
    where d.club_id=target_club and d.dinner_kind='regular' and d.status='planned'
      and d.assignment_source='auto' and d.assigned_member_id is null
      and d.dinner_date between p_from_date and p_through_date order by d.dinner_date
  loop
    v_year:=extract(year from v_dinner.dinner_date)::int;
    select r.member_id into v_member from public.weekly_officer_rotation r
    where r.club_id=target_club and public.weekly_officer_member_available_v1(target_club,r.member_id,v_dinner.dinner_date)
    order by (
      select count(*) from public.weekly_dinners x
      where x.club_id=target_club and x.dinner_kind='regular' and x.status in ('planned','completed')
        and x.assigned_member_id=r.member_id and extract(year from x.dinner_date)::int=v_year
    ) asc,r.rotation_order asc,r.joined_rotation_at asc,r.member_id limit 1;
    if v_member is not null then
      update public.weekly_dinners set assigned_member_id=v_member,assignment_source='auto',updated_at=now(),updated_by=coalesce((select auth.uid()),updated_by)
      where id=v_dinner.id;
    end if;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_shop_order_payment_v1(target_club uuid, p_order uuid, p_amount numeric, p_payment_method text DEFAULT 'Dinheiro'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_order public.shop_orders%rowtype; v_account uuid; v_cost_center uuid; v_tx uuid; v_name text; v_new_paid numeric;
begin
  if not (public.has_club_permission(target_club,'sellInventory') or public.has_club_permission(target_club,'manageMerchandising')) then raise exception 'Sem autorização para receber pagamentos.'; end if;
  if p_amount<=0 then raise exception 'O valor deve ser superior a zero.'; end if;
  select * into v_order from public.shop_orders where id=p_order and club_id=target_club and status<>'cancelled' for update;
  if not found then raise exception 'Encomenda não encontrada.'; end if;
  if v_order.paid_amount+p_amount>v_order.total_amount then raise exception 'O pagamento ultrapassa o valor em dívida.'; end if;
  select id into v_account from public.treasury_accounts where club_id=target_club and active=true and lower(name)=lower('Club House') limit 1;
  if v_account is null then raise exception 'Conta Club House não encontrada.'; end if;
  select id into v_cost_center from public.cost_centers where club_id=target_club and active=true and lower(name)=lower('Club House') limit 1;
  select coalesce(m.full_name,v_order.external_name,'Cliente') into v_name from public.shop_orders o left join public.members m on m.id=o.member_id where o.id=v_order.id;
  insert into public.treasury_transactions(club_id,kind,account_id,cost_center_id,transaction_date,description,amount,payment_method,source_type,source_id,created_by)
  values(target_club,'income',v_account,v_cost_center,current_date,'Pagamento encomenda Loja - '||v_name,p_amount,p_payment_method,'shop_order',v_order.id,auth.uid()) returning id into v_tx;
  insert into public.shop_order_payments(club_id,order_id,amount,payment_method,treasury_transaction_id,created_by) values(target_club,v_order.id,p_amount,p_payment_method,v_tx,auth.uid());
  v_new_paid:=v_order.paid_amount+p_amount;
  update public.shop_orders set paid_amount=v_new_paid,updated_at=now() where id=v_order.id;
  return jsonb_build_object('order_id',v_order.id,'paid_amount',v_new_paid,'remaining',v_order.total_amount-v_new_paid,'transaction_id',v_tx);
end; $function$

CREATE OR REPLACE FUNCTION public.refresh_fee_obligation_status_v1(p_obligation uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.fee_obligations%rowtype; v_total numeric;
begin
  select * into v from public.fee_obligations where id=p_obligation for update;
  if not found or v.status='cancelled' then return; end if;
  v_total:=greatest(0,coalesce(v.amount,0)+coalesce(v.adjustment_amount,0)-coalesce(v.exempt_amount,0));
  update public.fee_obligations set status=case
    when v_total=0 and coalesce(v.exempt_amount,0)>0 then 'exempt'::public.fee_status
    when coalesce(v.paid_amount,0)>=v_total and v_total>0 then 'paid'::public.fee_status
    when coalesce(v.paid_amount,0)>0 then 'partial'::public.fee_status
    else 'pending'::public.fee_status end
  where id=p_obligation;
end;
$function$

CREATE OR REPLACE FUNCTION public.register_document_version_v1(p_document uuid, p_storage_path text, p_original_file_name text, p_mime_type text, p_file_size bigint, p_change_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_doc public.documents%rowtype; v_no integer; v_id uuid; v_label text;
begin
  select * into v_doc from public.documents where id=p_document for update;
  if not found or not public.can_edit_document_v1(p_document) then raise exception 'Documento não acessível para edição.'; end if;
  if coalesce(p_storage_path,'')='' or coalesce(p_file_size,0)<0 then raise exception 'Versão inválida.'; end if;
  select coalesce(max(version_no),0)+1 into v_no from public.document_versions where document_id=p_document;
  v_label:=v_no::text||'.0';
  update public.document_versions set is_current=false where document_id=p_document and is_current=true;
  insert into public.document_versions(club_id,document_id,version_no,version_label,storage_path,original_file_name,mime_type,file_size,change_notes,is_current,created_by)
  values(v_doc.club_id,p_document,v_no,v_label,p_storage_path,p_original_file_name,p_mime_type,coalesce(p_file_size,0),p_change_notes,true,(select auth.uid()))
  returning id into v_id;
  update public.documents set current_version_id=v_id,storage_path=p_storage_path,original_file_name=p_original_file_name,mime_type=p_mime_type,file_size=coalesce(p_file_size,0),version=v_label,updated_at=now(),updated_by=(select auth.uid()) where id=p_document;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.register_euromillions_draw_payment_v1(target_club uuid, p_charge uuid, p_payment_method text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.euromillions_draw_charges%rowtype; acc uuid; tx uuid; remaining numeric;
begin
 if not public.has_club_permission(target_club,'manageLottery') then raise exception 'Sem permissão para registar pagamentos.'; end if;
 select * into c from public.euromillions_draw_charges where id=p_charge and club_id=target_club for update;
 if c.id is null then raise exception 'Cobrança não encontrada.'; end if;
 remaining:=greatest(c.amount-c.paid_amount,0); if remaining=0 then return; end if;
 select id into acc from public.treasury_accounts where club_id=target_club and lower(name)=lower('Euromilhões') and active=true limit 1;
 if acc is null then raise exception 'Conta Euromilhões não encontrada.'; end if;
 insert into public.treasury_transactions(club_id,kind,account_id,transaction_date,description,amount,payment_method,source_type,source_id,created_by)
 values(target_club,'income',acc,current_date,'Pagamento Euromilhões - sorteio '||to_char(c.draw_date,'DD/MM/YYYY'),remaining,p_payment_method,'euromillions_draw_charge',c.id,auth.uid()) returning id into tx;
 update public.euromillions_draw_charges set paid_amount=amount,paid_at=now(),payment_method=p_payment_method,transaction_id=tx where id=c.id;
end; $function$

CREATE OR REPLACE FUNCTION public.register_euromillions_fine_payment_v1(target_club uuid, p_player uuid, p_amount numeric DEFAULT NULL::numeric, p_payment_method text DEFAULT NULL::text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare outstanding numeric; to_pay numeric; remaining numeric; r record; allocation numeric; acc uuid; tx uuid; member_name text;
begin
  if not public.has_club_permission(target_club,'manageLottery') then raise exception 'Sem permissão para receber multas.'; end if;
  select m.full_name into member_name from public.euromillions_players p join public.members m on m.id=p.member_id where p.id=p_player and p.club_id=target_club;
  if member_name is null then raise exception 'Jogador não encontrado.'; end if;
  select coalesce(sum(greatest(fine_amount-paid_amount,0)),0) into outstanding from public.euromillions_fines where club_id=target_club and player_id=p_player;
  if outstanding<=0 then raise exception 'Este jogador não tem multas em dívida.'; end if;
  to_pay:=case when p_amount is null then outstanding else least(p_amount,outstanding) end;
  if to_pay<=0 then raise exception 'O valor deve ser superior a zero.'; end if;
  select id into acc from public.treasury_accounts where club_id=target_club and lower(name)=lower('Euromilhões - Multas') and active=true limit 1;
  if acc is null then raise exception 'Conta Euromilhões - Multas não encontrada.'; end if;
  insert into public.treasury_transactions(club_id,kind,account_id,transaction_date,description,amount,payment_method,source_type,source_id,created_by)
  values(target_club,'income',acc,current_date,'Pagamento multas Euromilhões - '||member_name,to_pay,p_payment_method,'euromillions_fine_payment',p_player,auth.uid()) returning id into tx;
  remaining:=to_pay;
  for r in select id,fine_amount,paid_amount from public.euromillions_fines where club_id=target_club and player_id=p_player and paid_amount<fine_amount order by created_at,id for update loop
    exit when remaining<=0; allocation:=least(remaining,r.fine_amount-r.paid_amount);
    update public.euromillions_fines set paid_amount=paid_amount+allocation,paid_at=case when paid_amount+allocation>=fine_amount then now() else paid_at end,payment_method=p_payment_method,transaction_id=tx where id=r.id;
    remaining:=remaining-allocation;
  end loop;
  return to_pay;
end; $function$

CREATE OR REPLACE FUNCTION public.register_euromillions_manual_prize_v1(target_club uuid, p_result uuid, p_player uuid, p_amount numeric, p_payment_method text DEFAULT NULL::text, p_category integer DEFAULT 13)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare prize_id uuid; acc uuid; tx uuid; member_name text; hit_n int:=0; hit_s int:=0;
begin
  if not public.has_club_permission(target_club,'manageLottery') then raise exception 'Sem permissão para registar prémios.'; end if;
  if p_amount<=0 then raise exception 'O valor do prémio deve ser superior a zero.'; end if;
  if p_category<1 or p_category>13 then raise exception 'Categoria de prémio inválida.'; end if;
  if not exists(select 1 from public.euromillions_results where id=p_result and club_id=target_club) then raise exception 'Sorteio não encontrado.'; end if;
  select m.full_name into member_name from public.euromillions_players p join public.members m on m.id=p.member_id where p.id=p_player and p.club_id=target_club;
  if member_name is null then raise exception 'Jogador não encontrado.'; end if;
  select (select count(*) from unnest(p.numbers) n where n=any(r.numbers)),(select count(*) from unnest(p.stars) s where s=any(r.stars)) into hit_n,hit_s from public.euromillions_players p cross join public.euromillions_results r where p.id=p_player and r.id=p_result;
  insert into public.euromillions_prizes(club_id,result_id,player_id,category,matched_numbers,matched_stars,prize_amount,received_amount,received_at,payment_method)
  values(target_club,p_result,p_player,p_category,coalesce(hit_n,0),coalesce(hit_s,0),p_amount,p_amount,now(),p_payment_method)
  on conflict(result_id,player_id) do update set category=excluded.category,matched_numbers=excluded.matched_numbers,matched_stars=excluded.matched_stars,prize_amount=public.euromillions_prizes.prize_amount+excluded.prize_amount,received_amount=public.euromillions_prizes.received_amount+excluded.received_amount,received_at=now(),payment_method=excluded.payment_method returning id into prize_id;
  select id into acc from public.treasury_accounts where club_id=target_club and lower(name)=lower('Euromilhões') and active=true limit 1;
  if acc is null then raise exception 'Conta Euromilhões não encontrada.'; end if;
  insert into public.treasury_transactions(club_id,kind,account_id,transaction_date,description,amount,payment_method,source_type,source_id,created_by)
  values(target_club,'income',acc,current_date,'Prémio Euromilhões - '||member_name,p_amount,p_payment_method,'euromillions_prize_manual',prize_id,auth.uid()) returning id into tx;
  update public.euromillions_prizes set transaction_id=tx where id=prize_id; return prize_id;
end; $function$

CREATE OR REPLACE FUNCTION public.register_euromillions_month_fine_payment_v1(target_club uuid, p_player uuid, p_year integer, p_month integer, p_payment_method text DEFAULT NULL::text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  outstanding numeric := 0;
  acc uuid;
  tx uuid;
  member_name text;
  has_partial boolean := false;
begin
  if auth.uid() is null then
    raise exception 'Autenticação necessária.';
  end if;
  if not public.has_club_permission(target_club,'manageLottery') then
    raise exception 'Sem permissão para receber multas.';
  end if;

  select m.full_name into member_name
  from public.euromillions_players p
  join public.members m on m.id=p.member_id
  where p.id=p_player and p.club_id=target_club;

  if member_name is null then
    raise exception 'Jogador não encontrado.';
  end if;

  select
    coalesce(sum(greatest(f.fine_amount-f.paid_amount,0)),0),
    coalesce(bool_or(f.paid_amount>0 and f.paid_amount<f.fine_amount),false)
  into outstanding, has_partial
  from public.euromillions_fines f
  join public.euromillions_results r on r.id=f.result_id
  where f.club_id=target_club
    and f.player_id=p_player
    and extract(year from r.draw_date)=p_year
    and extract(month from r.draw_date)=p_month;

  if has_partial then
    raise exception 'Existem multas parcialmente pagas neste mês. Regulariza-as individualmente antes de usar o pagamento mensal.';
  end if;
  if outstanding<=0 then
    raise exception 'Este jogador não tem multas deste mês em dívida.';
  end if;

  select id into acc
  from public.treasury_accounts
  where club_id=target_club
    and lower(name)=lower('Euromilhões - Multas')
    and active=true
  limit 1;

  if acc is null then
    raise exception 'Conta Euromilhões - Multas não encontrada.';
  end if;

  insert into public.treasury_transactions(
    club_id,kind,account_id,transaction_date,description,amount,
    payment_method,source_type,source_id,created_by
  ) values (
    target_club,'income',acc,current_date,
    'Pagamento multas Euromilhões - '||member_name||' - '||lpad(p_month::text,2,'0')||'/'||p_year,
    outstanding,p_payment_method,'euromillions_fine_payment_month',p_player,auth.uid()
  ) returning id into tx;

  update public.euromillions_fines f
  set paid_amount=f.fine_amount,
      paid_at=now(),
      payment_method=p_payment_method,
      transaction_id=tx,
      updated_at=now(),
      updated_by=auth.uid()
  from public.euromillions_results r
  where r.id=f.result_id
    and f.club_id=target_club
    and f.player_id=p_player
    and extract(year from r.draw_date)=p_year
    and extract(month from r.draw_date)=p_month
    and f.paid_amount<f.fine_amount;

  perform public.audit_event(
    target_club,
    'register_euromillions_month_fine_payment',
    'euromillions_fine_payment',
    tx::text,
    null,
    jsonb_build_object(
      'player_id',p_player,
      'year',p_year,
      'month',p_month,
      'amount',outstanding,
      'transaction_id',tx
    ),
    null
  );

  return outstanding;
end;
$function$

CREATE OR REPLACE FUNCTION public.register_euromillions_month_payment_v1(target_club uuid, p_player uuid, p_year integer, p_month integer, p_payment_method text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record;
begin
 if not public.has_club_permission(target_club,'manageLottery') then raise exception 'Sem permissão para registar pagamentos.'; end if;
 perform public.generate_euromillions_charges_v1(target_club,p_year,p_month);
 for r in select id from public.euromillions_draw_charges where club_id=target_club and player_id=p_player and extract(year from draw_date)=p_year and extract(month from draw_date)=p_month and paid_amount<amount order by draw_date loop
  perform public.register_euromillions_draw_payment_v1(target_club,r.id,p_payment_method);
 end loop;
end; $function$

CREATE OR REPLACE FUNCTION public.register_euromillions_prize_receipt_v1(target_club uuid, p_prize uuid, p_amount numeric DEFAULT NULL::numeric, p_payment_method text DEFAULT NULL::text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pr public.euromillions_prizes%rowtype; remaining numeric; received numeric; acc uuid; tx uuid; member_name text;
begin
  if not public.has_club_permission(target_club,'manageLottery') then raise exception 'Sem permissão para receber prémios.'; end if;
  select * into pr from public.euromillions_prizes where id=p_prize and club_id=target_club for update;
  if pr.id is null then raise exception 'Prémio não encontrado.'; end if;
  select m.full_name into member_name from public.euromillions_players p join public.members m on m.id=p.member_id where p.id=pr.player_id;
  remaining:=greatest(pr.prize_amount-pr.received_amount,0); if remaining<=0 then raise exception 'Este prémio já está totalmente recebido.'; end if;
  received:=case when p_amount is null then remaining else least(p_amount,remaining) end; if received<=0 then raise exception 'O valor deve ser superior a zero.'; end if;
  select id into acc from public.treasury_accounts where club_id=target_club and lower(name)=lower('Euromilhões') and active=true limit 1;
  if acc is null then raise exception 'Conta Euromilhões não encontrada.'; end if;
  insert into public.treasury_transactions(club_id,kind,account_id,transaction_date,description,amount,payment_method,source_type,source_id,created_by)
  values(target_club,'income',acc,current_date,'Prémio Euromilhões - '||coalesce(member_name,'Jogador'),received,p_payment_method,'euromillions_prize',pr.id,auth.uid()) returning id into tx;
  update public.euromillions_prizes set received_amount=received_amount+received,received_at=case when received_amount+received>=prize_amount then now() else received_at end,payment_method=p_payment_method,transaction_id=tx where id=pr.id;
  return received;
end; $function$

CREATE OR REPLACE FUNCTION public.register_fee_payment_batch_v1(target_club uuid, p_member uuid, p_amount numeric, p_payment_method text, p_payment_date date DEFAULT CURRENT_DATE, p_notes text DEFAULT NULL::text, p_allocations jsonb DEFAULT NULL::jsonb, p_reported_payment uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_account uuid; v_payment uuid:=gen_random_uuid(); v_transaction uuid:=gen_random_uuid(); v_member_name text;
  v_remaining numeric:=coalesce(p_amount,0); v_first_obligation uuid; v_row jsonb;
  v_obligation public.fee_obligations%rowtype; v_requested numeric; v_outstanding numeric; r record;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageFees') then raise exception 'Sem autorização para registar pagamentos de quotas.'; end if;
  if p_amount is null or p_amount<=0 then raise exception 'O valor do pagamento deve ser superior a zero.'; end if;
  if nullif(trim(coalesce(p_payment_method,'')),'') is null then raise exception 'Indica o método de pagamento.'; end if;
  select full_name into v_member_name from public.members where id=p_member and club_id=target_club;
  if v_member_name is null then raise exception 'Membro inválido.'; end if;
  select id into v_account from public.treasury_accounts where club_id=target_club and lower(name)='quotas' and active=true order by created_at limit 1;
  if v_account is null then raise exception 'A conta Quotas não está disponível.'; end if;
  if p_reported_payment is not null and not exists(select 1 from public.reported_payments where id=p_reported_payment and club_id=target_club and member_id=p_member and status='pending' and amount=p_amount) then
    raise exception 'Pagamento comunicado inválido ou já tratado.';
  end if;

  insert into public.treasury_transactions(id,club_id,kind,account_id,transaction_date,description,amount,payment_method,notes,source_type,source_id,created_by)
  values(v_transaction,target_club,'income',v_account,coalesce(p_payment_date,current_date),'Pagamento de quotas - '||v_member_name,p_amount,trim(p_payment_method),nullif(trim(coalesce(p_notes,'')),''),'fee_payment',v_payment,auth.uid());
  insert into public.fee_payments(id,club_id,member_id,obligation_id,transaction_id,amount,paid_at,received_by,notes,payment_method,payment_date,status)
  values(v_payment,target_club,p_member,null,v_transaction,p_amount,now(),auth.uid(),nullif(trim(coalesce(p_notes,'')),''),trim(p_payment_method),coalesce(p_payment_date,current_date),'confirmed');

  if p_allocations is not null and jsonb_typeof(p_allocations)='array' and jsonb_array_length(p_allocations)>0 then
    for v_row in select value from jsonb_array_elements(p_allocations) loop
      if nullif(v_row->>'obligation_id','') is null then raise exception 'Distribuição inválida.'; end if;
      v_requested:=(v_row->>'amount')::numeric;
      if v_requested is null or v_requested<=0 then raise exception 'O valor distribuído deve ser positivo.'; end if;
      select * into v_obligation from public.fee_obligations where id=(v_row->>'obligation_id')::uuid and club_id=target_club and member_id=p_member for update;
      if not found then raise exception 'Quota da distribuição não encontrada.'; end if;
      if v_obligation.status in('paid','exempt','cancelled') then raise exception 'Uma das quotas já não aceita pagamentos.'; end if;
      v_outstanding:=public.fee_obligation_outstanding_v1(v_obligation);
      if v_requested>v_outstanding then raise exception 'A distribuição excede o saldo de uma quota.'; end if;
      if v_requested>v_remaining then raise exception 'A distribuição excede o valor recebido.'; end if;
      insert into public.fee_payment_allocations(club_id,payment_id,obligation_id,amount) values(target_club,v_payment,v_obligation.id,v_requested);
      update public.fee_obligations set paid_amount=paid_amount+v_requested where id=v_obligation.id;
      perform public.refresh_fee_obligation_status_v1(v_obligation.id);
      v_first_obligation:=coalesce(v_first_obligation,v_obligation.id); v_remaining:=v_remaining-v_requested;
    end loop;
  else
    for r in select o.id from public.fee_obligations o where o.club_id=target_club and o.member_id=p_member and o.status not in('paid','exempt','cancelled') and public.fee_obligation_outstanding_v1(o)>0 order by o.due_date nulls last,o.reference_year,o.reference_month nulls first,o.created_at for update
    loop
      exit when v_remaining<=0;
      select * into v_obligation from public.fee_obligations where id=r.id;
      v_outstanding:=public.fee_obligation_outstanding_v1(v_obligation); v_requested:=least(v_remaining,v_outstanding);
      insert into public.fee_payment_allocations(club_id,payment_id,obligation_id,amount) values(target_club,v_payment,v_obligation.id,v_requested);
      update public.fee_obligations set paid_amount=paid_amount+v_requested where id=v_obligation.id;
      perform public.refresh_fee_obligation_status_v1(v_obligation.id);
      v_first_obligation:=coalesce(v_first_obligation,v_obligation.id); v_remaining:=v_remaining-v_requested;
    end loop;
  end if;
  update public.fee_payments set obligation_id=v_first_obligation where id=v_payment;
  if v_remaining>0 then insert into public.fee_credits(club_id,member_id,amount,entry_type,payment_id,reason) values(target_club,p_member,v_remaining,'payment_excess',v_payment,'Excesso do pagamento de quotas'); end if;
  if p_reported_payment is not null then update public.reported_payments set status='approved',reviewed_at=now(),reviewed_by=auth.uid(),fee_payment_id=v_payment where id=p_reported_payment; end if;
  return v_payment;
end;
$function$

CREATE OR REPLACE FUNCTION public.register_fee_payment_v1(target_club uuid, p_obligation uuid, p_amount numeric, p_payment_method text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_member uuid;
begin
  select member_id into v_member from public.fee_obligations where id=p_obligation and club_id=target_club;
  if v_member is null then raise exception 'Quota não encontrada.'; end if;
  return public.register_fee_payment_batch_v1(target_club,v_member,p_amount,p_payment_method,current_date,p_notes,jsonb_build_array(jsonb_build_object('obligation_id',p_obligation,'amount',p_amount)),null);
end;
$function$

CREATE OR REPLACE FUNCTION public.register_push_device_v1(target_club uuid, p_platform text, p_device_id text, p_push_token text, p_app_version text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if auth.uid() is null or not public.has_club_access(target_club) then
    raise exception 'Sem acesso ao clube.';
  end if;
  if lower(coalesce(p_platform,'')) not in ('android','ios','web') then
    raise exception 'Plataforma push invalida.';
  end if;
  if btrim(coalesce(p_device_id,''))='' or btrim(coalesce(p_push_token,''))='' then
    raise exception 'Dispositivo ou token push invalido.';
  end if;

  insert into public.push_devices(
    club_id,profile_id,platform,device_id,push_token,provider,active,last_seen_at,app_version,updated_at
  ) values (
    target_club,auth.uid(),lower(p_platform),btrim(p_device_id),btrim(p_push_token),'fcm',true,now(),nullif(btrim(coalesce(p_app_version,'')),''),now()
  )
  on conflict (club_id,profile_id,device_id) do update set
    platform=excluded.platform,
    push_token=excluded.push_token,
    provider='fcm',
    active=true,
    last_seen_at=now(),
    app_version=excluded.app_version,
    updated_at=now()
  returning id into v_id;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.reject_event_proposal_v1(p_proposal uuid, p_notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v public.event_proposals%rowtype;
begin
  if (select auth.uid()) is null then raise exception 'Autenticação necessária.'; end if;
  select * into v from public.event_proposals where id = p_proposal for update;
  if not found then raise exception 'Proposta não encontrada.'; end if;
  if not public.has_club_permission(v.club_id, 'approveEventProposals') then
    raise exception 'Sem permissão para rejeitar propostas.';
  end if;
  if v.status <> 'submitted' then raise exception 'A proposta já foi processada.'; end if;
  update public.event_proposals
  set status='rejected', decision_notes=nullif(btrim(p_notes), ''), decided_by=(select auth.uid()),
      decided_at=now(), updated_at=now(), updated_by=(select auth.uid())
  where id=p_proposal;
end;
$function$

CREATE OR REPLACE FUNCTION public.reorder_event_program_v1(p_event uuid, p_item_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_club_id uuid;
  v_expected integer;
  v_received integer;
  v_offset integer;
begin
  select e.club_id
    into v_club_id
  from public.events e
  where e.id = p_event;

  if not found then
    raise exception 'Evento não encontrado.' using errcode = 'P0001';
  end if;

  if not public.has_club_permission(v_club_id, 'manageEventOperations') then
    raise exception 'Sem permissão para gerir o programa do evento.' using errcode = '42501';
  end if;

  select count(*)::integer
    into v_expected
  from public.event_program p
  where p.event_id = p_event
    and p.club_id = v_club_id;

  v_received := coalesce(cardinality(p_item_ids), 0);

  if v_received <> v_expected then
    raise exception 'A lista do programa está desatualizada. Atualiza e tenta novamente.' using errcode = 'P0001';
  end if;

  if v_expected = 0 then
    return;
  end if;

  if exists (
    select 1
    from unnest(p_item_ids) as x(item_id)
    group by x.item_id
    having count(*) > 1
  ) then
    raise exception 'A ordem do programa contém registos repetidos.' using errcode = 'P0001';
  end if;

  if (
    select count(*)
    from public.event_program p
    where p.event_id = p_event
      and p.club_id = v_club_id
      and p.id = any(p_item_ids)
  ) <> v_expected then
    raise exception 'A ordem do programa contém registos inválidos.' using errcode = 'P0001';
  end if;

  select coalesce(max(p.sequence_no), 0) + v_expected + 1000
    into v_offset
  from public.event_program p
  where p.event_id = p_event
    and p.club_id = v_club_id;

  update public.event_program
  set sequence_no = sequence_no + v_offset
  where event_id = p_event
    and club_id = v_club_id;

  update public.event_program p
  set sequence_no = ordered.position::integer
  from unnest(p_item_ids) with ordinality as ordered(item_id, position)
  where p.id = ordered.item_id
    and p.event_id = p_event
    and p.club_id = v_club_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.reorder_event_route_stops_v1(p_event uuid, p_route uuid, p_stop_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_club_id uuid;
  v_expected integer;
  v_received integer;
  v_offset integer;
begin
  select er.club_id
    into v_club_id
  from public.event_routes er
  where er.id = p_route
    and er.event_id = p_event;

  if not found then
    raise exception 'Roadbook não encontrado.' using errcode = 'P0001';
  end if;

  if not public.has_club_permission(v_club_id, 'manageEventRoadbook') then
    raise exception 'Sem permissão para gerir o Roadbook.' using errcode = '42501';
  end if;

  select count(*)::integer
    into v_expected
  from public.event_route_stops s
  where s.event_id = p_event
    and s.route_id = p_route
    and s.club_id = v_club_id;

  v_received := coalesce(cardinality(p_stop_ids), 0);

  if v_received <> v_expected then
    raise exception 'A lista de paragens está desatualizada. Atualiza o Roadbook e tenta novamente.' using errcode = 'P0001';
  end if;

  if v_expected = 0 then
    return;
  end if;

  if exists (
    select 1
    from unnest(p_stop_ids) as x(stop_id)
    group by x.stop_id
    having count(*) > 1
  ) then
    raise exception 'A ordem das paragens contém registos repetidos.' using errcode = 'P0001';
  end if;

  if (
    select count(*)
    from public.event_route_stops s
    where s.event_id = p_event
      and s.route_id = p_route
      and s.club_id = v_club_id
      and s.id = any(p_stop_ids)
  ) <> v_expected then
    raise exception 'A ordem das paragens contém registos inválidos.' using errcode = 'P0001';
  end if;

  select coalesce(max(s.sequence_no), 0) + v_expected + 1000
    into v_offset
  from public.event_route_stops s
  where s.event_id = p_event
    and s.route_id = p_route
    and s.club_id = v_club_id;

  update public.event_route_stops
  set sequence_no = sequence_no + v_offset
  where event_id = p_event
    and route_id = p_route
    and club_id = v_club_id;

  update public.event_route_stops s
  set sequence_no = ordered.position::integer
  from unnest(p_stop_ids) with ordinality as ordered(stop_id, position)
  where s.id = ordered.stop_id
    and s.event_id = p_event
    and s.route_id = p_route
    and s.club_id = v_club_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.reorder_weekly_officer_v1(target_club uuid, p_member_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected int; v_supplied int; v_distinct int; v_member uuid; v_index int:=0;
begin
  if not public.can_manage_weekly_officer_v1(target_club) then raise exception 'Apenas Presidente, Vice-Presidente ou Superadmin podem alterar a ordem.'; end if;
  select count(*) into v_expected from public.weekly_officer_rotation where club_id=target_club;
  v_supplied:=coalesce(array_length(p_member_ids,1),0);
  select count(distinct x) into v_distinct from unnest(coalesce(p_member_ids,array[]::uuid[])) x;
  if v_supplied<>v_expected or v_distinct<>v_expected then raise exception 'A lista deve conter todos os membros da rotação uma única vez.'; end if;
  if exists(select 1 from unnest(p_member_ids) x where not exists(select 1 from public.weekly_officer_rotation r where r.club_id=target_club and r.member_id=x)) then raise exception 'A lista contém um membro inválido.'; end if;
  foreach v_member in array p_member_ids loop v_index:=v_index+1;
    update public.weekly_officer_rotation set rotation_order=v_index*10,updated_at=now(),updated_by=(select auth.uid()) where club_id=target_club and member_id=v_member;
  end loop;
  perform public.audit_event(target_club,'weekly_officer_rotation_reordered','weekly_officer_rotation',target_club::text,null,jsonb_build_object('member_ids',p_member_ids),null);
  perform public.rebuild_weekly_officer_future_internal_v1(target_club,current_date);
end;
$function$

CREATE OR REPLACE FUNCTION public.request_document_approval_v1(p_document uuid, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_doc public.documents%rowtype; v_id uuid;
begin
  select * into v_doc from public.documents where id=p_document for update;
  if not found or not public.can_edit_document_v1(p_document) then raise exception 'Documento não acessível para aprovação.'; end if;
  select id into v_id from public.document_approvals where document_id=p_document and status='pending' limit 1;
  if v_id is not null then return v_id; end if;
  insert into public.document_approvals(club_id,document_id,status,requested_by,notes) values(v_doc.club_id,p_document,'pending',(select auth.uid()),p_notes) returning id into v_id;
  update public.documents set requires_approval=true,approval_status='pending',updated_at=now(),updated_by=(select auth.uid()) where id=p_document;
  return v_id;
end; $function$

CREATE OR REPLACE FUNCTION public.request_member_patch_v1(target_club uuid, p_member uuid, p_product uuid, p_variant uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  v_patch text;
  v_variant text;
begin
  if not public.has_club_permission(target_club,'manageMembers') then
    raise exception 'Sem permissão para atribuir patches.';
  end if;
  if not exists(select 1 from public.members where id=p_member and club_id=target_club) then
    raise exception 'Membro inválido.';
  end if;
  select name into v_patch from public.products
  where id=p_product and club_id=target_club and active=true
    and inventory_area='shop' and institutional_delivery=true;
  if v_patch is null then raise exception 'Patch/artigo institucional inválido.'; end if;
  if exists(select 1 from public.product_variants where product_id=p_product and active=true) and p_variant is null then
    raise exception 'Seleciona a variante do patch.';
  end if;
  if p_variant is not null then
    select name into v_variant from public.product_variants
    where id=p_variant and product_id=p_product and active=true;
    if v_variant is null then raise exception 'Variante inválida.'; end if;
  end if;
  insert into public.member_patch_awards(
    club_id,member_id,product_id,variant_id,patch_name,variant_name,status,notes,created_by,updated_by
  ) values (
    target_club,p_member,p_product,p_variant,v_patch,v_variant,'pending',
    nullif(trim(coalesce(p_notes,'')),''),auth.uid(),auth.uid()
  ) returning id into v_id;
  return v_id;
end
$function$

CREATE OR REPLACE FUNCTION public.request_weekly_officer_swap_v1(target_club uuid, p_dinner uuid, p_requested_member uuid, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_requester uuid; v_id uuid; v_date date; v_requester_name text;
begin
  if (select auth.uid()) is null or not public.has_club_access(target_club) then raise exception 'Sem acesso ao clube.'; end if;
  v_requester:=public.current_weekly_officer_member_v1(target_club); if v_requester is null then raise exception 'O teu utilizador não está ligado a um membro.'; end if;
  if p_requested_member=v_requester then raise exception 'Não podes pedir troca contigo próprio.'; end if;
  if not exists(select 1 from public.members where id=p_requested_member and club_id=target_club) then raise exception 'Membro pedido inválido.'; end if;
  select d.dinner_date into v_date from public.weekly_dinners d where d.id=p_dinner and d.club_id=target_club and d.dinner_kind='regular' and d.status='planned'
    and d.assigned_member_id=v_requester and d.dinner_date>=current_date;
  if v_date is null then raise exception 'Só podes pedir troca do teu próprio jantar futuro.'; end if;
  insert into public.weekly_officer_swap_requests(club_id,dinner_id,requester_member_id,requested_member_id,requester_note)
  values(target_club,p_dinner,v_requester,p_requested_member,nullif(btrim(coalesce(p_note,'')),'')) returning id into v_id;
  select coalesce(nullif(m.nickname,''),m.full_name) into v_requester_name from public.members m where m.id=v_requester;
  perform public.weekly_officer_notify_member_v1(target_club,p_requested_member,'Pedido de troca de jantar',coalesce(v_requester_name,'Um membro')||' pediu troca para '||to_char(v_date,'DD/MM/YYYY')||'.','weekly_officer_swap',v_id);
  perform public.audit_event(target_club,'weekly_officer_swap_requested','weekly_officer_swap',v_id::text,null,jsonb_build_object('dinner_id',p_dinner,'requested_member_id',p_requested_member),null); return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.reserve_shop_variant_v1(target_club uuid, p_product uuid, p_variant uuid, p_quantity numeric, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_variant public.product_variants%rowtype; v_product public.products%rowtype;
begin
  if not public.has_club_permission(target_club,'manageMerchandising') then raise exception 'Sem autorização para reservar stock.'; end if;
  if p_quantity<=0 then raise exception 'Quantidade inválida.'; end if;
  select * into v_product from public.products where id=p_product and club_id=target_club and active=true;
  if not found then raise exception 'Artigo não encontrado.'; end if;
  select * into v_variant from public.product_variants where id=p_variant and product_id=p_product and active=true for update;
  if not found then raise exception 'Variante não encontrada.'; end if;
  if v_variant.current_stock-v_variant.reserved_stock<p_quantity then raise exception 'Stock disponível insuficiente. Use Encomendar para artigos sem stock.'; end if;
  update public.product_variants set reserved_stock=reserved_stock+p_quantity where id=p_variant;
  insert into public.stock_movements(club_id,product_id,variant_id,kind,quantity,unit_cost,notes,created_by) values(target_club,p_product,p_variant,'transfer',p_quantity,coalesce(v_variant.cost,v_product.cost),coalesce(nullif(trim(coalesce(p_notes,'')),''),'Reserva de stock'),auth.uid());
  return jsonb_build_object('variant_id',p_variant,'reserved_stock',v_variant.reserved_stock+p_quantity);
end; $function$

CREATE OR REPLACE FUNCTION public.respond_weekly_officer_swap_v1(target_club uuid, p_request uuid, p_accept boolean, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_member uuid; v_row public.weekly_officer_swap_requests%rowtype; v_status text; v_responder_name text;
begin
  v_member:=public.current_weekly_officer_member_v1(target_club); if v_member is null then raise exception 'O teu utilizador não está ligado a um membro.'; end if;
  select * into v_row from public.weekly_officer_swap_requests where id=p_request and club_id=target_club and status='pending' for update;
  if not found then raise exception 'Pedido de troca pendente não encontrado.'; end if;
  if v_row.requested_member_id<>v_member then raise exception 'Este pedido não te é dirigido.'; end if;
  v_status:=case when p_accept then 'accepted' else 'rejected' end;
  update public.weekly_officer_swap_requests set status=v_status,response_note=nullif(btrim(coalesce(p_note,'')),''),responded_at=now(),responded_by=(select auth.uid()),updated_at=now(),updated_by=(select auth.uid()) where id=p_request;
  select coalesce(nullif(m.nickname,''),m.full_name) into v_responder_name from public.members m where m.id=v_member;
  perform public.weekly_officer_notify_member_v1(target_club,v_row.requester_member_id,case when p_accept then 'Troca aceite' else 'Troca recusada' end,
    coalesce(v_responder_name,'O membro')||case when p_accept then ' aceitou o pedido. A alteração aguarda Presidente/Vice-Presidente.' else ' recusou o pedido.' end,'weekly_officer_swap',p_request);
end;
$function$

CREATE OR REPLACE FUNCTION public.retry_financial_ocr_job_v1(target_club uuid, p_job uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare j public.financial_ocr_jobs%rowtype; v_allowed boolean;
begin
  if auth.uid() is null then raise exception 'Sessão inválida.'; end if;
  select * into j from public.financial_ocr_jobs where id=p_job and club_id=target_club for update;
  if not found then raise exception 'Pedido OCR não encontrado.'; end if;
  v_allowed:=case when j.source_kind='bar_import' then public.has_club_permission(target_club,'manageBar') else (public.has_club_permission(target_club,'createTreasuryMovement') or public.has_club_permission(target_club,'approveExpenseRequests')) end;
  if not v_allowed then raise exception 'Sem autorização para repetir este OCR.'; end if;
  if j.storage_path is null then raise exception 'Pedido OCR sem ficheiro.'; end if;
  if j.status in ('processing','confirmed','cancelled') then raise exception 'O pedido OCR não pode ser repetido neste estado.'; end if;
  update public.financial_ocr_jobs set status='pending',error_message=null,started_at=null,completed_at=null where id=p_job;
end; $function$

CREATE OR REPLACE FUNCTION public.reverse_bar_sale_v1(target_club uuid, p_sale uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s public.bar_sales%rowtype; t public.treasury_transactions%rowtype;
  item public.bar_sale_items%rowtype; tx uuid; reversal uuid; quantity_back numeric;
  product uuid; consumed numeric; snapshot_consumed numeric;
begin
  if auth.uid() is null or not public.has_club_access(target_club)
    or not public.has_club_permission(target_club,'manageBar')
    or not public.has_club_permission(target_club,'reverseTreasuryMovement') then
    raise exception 'Sem permissão para anular vendas do BAR.' using errcode='42501';
  end if;
  if length(btrim(coalesce(p_reason,'')))<3 then raise exception 'Indica o motivo da anulação (mínimo 3 caracteres).'; end if;
  select * into s from public.bar_sales where club_id=target_club and id=p_sale for update;
  if not found then raise exception 'Venda do BAR não encontrada neste clube.'; end if;
  if s.status<>'completed' or exists(select 1 from public.bar_sale_reversals where sale_id=p_sale) then
    raise exception 'Só é possível anular uma venda concluída ainda não anulada.';
  end if;
  -- Same dinner lock as close/association triggers. No frozen snapshot is edited.
  if s.weekly_dinner_id is not null then
    perform 1 from public.weekly_dinners where club_id=target_club and id=s.weekly_dinner_id for update;
    if not found then raise exception 'Jantar inválido para este clube.'; end if;
    if exists(select 1 from public.weekly_dinner_finances where dinner_id=s.weekly_dinner_id and financial_status='closed') then
      raise exception 'Reabre o fecho financeiro do jantar antes de anular esta venda.';
    end if;
  end if;
  select * into t from public.treasury_transactions
    where club_id=target_club and id=s.treasury_transaction_id for update;
  if not found or t.kind::text<>'income' or t.reversal_of is not null
    or t.source_type is distinct from 'bar_sale' or t.source_id is distinct from s.id
    or t.amount is distinct from s.total_amount then
    raise exception 'O movimento financeiro original da venda não é fiável para anulação.';
  end if;
  if exists(select 1 from public.treasury_transactions where reversal_of=t.id) then
    raise exception 'O movimento financeiro desta venda já foi revertido.';
  end if;
  -- Lock products in a deterministic order. Use the sale's immutable dose factors,
  -- never today's product/options/conversion or current average purchase cost.
  for product in select distinct i.product_id from public.bar_sale_items i
    where i.club_id=target_club and i.sale_id=p_sale and i.item_kind='stock' order by i.product_id loop
    perform 1 from public.products where id=product and club_id=target_club for update;
    if not found then raise exception 'Produto original da venda não encontrado.'; end if;
    select sum(i.quantity*i.stock_quantity_per_unit) into snapshot_consumed
      from public.bar_sale_items i where i.club_id=target_club and i.sale_id=p_sale and i.product_id=product and i.item_kind='stock';
    select sum(o.consumption_quantity) into consumed from public.bar_operations o
      where o.club_id=target_club and o.sale_id=p_sale and o.product_id=product and o.operation_type='sale';
    if snapshot_consumed is null or snapshot_consumed<=0 or snapshot_consumed::text in ('NaN','Infinity','-Infinity')
      or consumed is distinct from snapshot_consumed
      or exists(select 1 from public.bar_sale_items i where i.sale_id=p_sale and i.item_kind='stock' and i.product_id=product
        and (i.stock_quantity_per_unit is null or i.stock_quantity_per_unit<=0)) then
      raise exception 'Quantidade de stock histórica não fiável; não é possível anular automaticamente.';
    end if;
  end loop;
  if exists(select 1 from public.bar_sale_items where sale_id=p_sale and item_kind='stock' and product_id is null) then
    raise exception 'Produto original da venda não encontrado.';
  end if;
  -- Same compensating-entry convention as reverse_treasury_transaction_v1.
  -- Its source-module restriction stays intact; no source_type is temporarily changed.
  insert into public.treasury_transactions(club_id,kind,account_id,destination_account_id,category_id,cost_center_id,event_id,
    transaction_date,description,amount,payment_method,notes,source_type,source_id,reversal_of,created_by)
  values(target_club,'expense',t.account_id,null,t.category_id,t.cost_center_id,t.event_id,
    current_date,'Reversão — '||t.description,t.amount,t.payment_method,btrim(p_reason),'reversal',t.id,t.id,auth.uid())
    returning id into tx;
  insert into public.bar_sale_reversals(club_id,sale_id,original_transaction_id,reversal_transaction_id,reason,created_by)
    values(target_club,p_sale,t.id,tx,btrim(p_reason),auth.uid()) returning id into reversal;
  for item in select * from public.bar_sale_items
    where club_id=target_club and sale_id=p_sale and item_kind='stock' order by product_id,id loop
    quantity_back:=item.quantity*item.stock_quantity_per_unit;
    update public.products set current_stock=coalesce(current_stock,0)+quantity_back,updated_by=auth.uid(),updated_at=now()
      where club_id=target_club and id=item.product_id;
    -- Nullable historical cost stays NULL; this is a quantity correction, not a
    -- purchase. Product.cost is deliberately unchanged, preserving average cost.
    insert into public.stock_movements(club_id,product_id,event_id,kind,quantity,unit_cost,notes,created_by)
      values(target_club,item.product_id,s.event_id,'adjustment',quantity_back,item.unit_cost_snapshot,
        'Anulação venda '||s.id||' | Linha '||item.id||' | '||btrim(p_reason),auth.uid());
    insert into public.bar_operations(club_id,product_id,event_id,operation_type,consumption_quantity,unit_price,total_amount,
      payment_method,notes,treasury_transaction_id,created_by,sale_id,sale_option_id,sale_option_name,customer_type)
      values(target_club,item.product_id,s.event_id,'adjustment_in',quantity_back,0,0,s.payment_method,
        'Anulação venda '||s.id||' | Linha '||item.id||' | '||btrim(p_reason),tx,auth.uid(),s.id,item.sale_option_id,item.sale_option_name,s.customer_type);
  end loop;
  update public.bar_sales set status='reversed',updated_by=auth.uid(),updated_at=now() where id=s.id;
  return reversal;
end $function$

CREATE OR REPLACE FUNCTION public.reverse_euromillions_draw_payment_v1(target_club uuid, p_charge uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c public.euromillions_draw_charges%rowtype;
  tx public.treasury_transactions%rowtype;
  reversal_id uuid;
  old_data jsonb;
  new_data jsonb;
begin
  if auth.uid() is null then
    raise exception 'Autenticação necessária.';
  end if;
  if not public.has_club_permission(target_club,'manageLottery') then
    raise exception 'Sem permissão para reverter pagamentos.';
  end if;
  if length(trim(coalesce(p_reason,''))) < 3 then
    raise exception 'Indica o motivo da reversão.';
  end if;

  select * into c
  from public.euromillions_draw_charges
  where id=p_charge and club_id=target_club
  for update;

  if c.id is null then
    raise exception 'Cobrança não encontrada.';
  end if;
  if coalesce(c.paid_amount,0) <= 0 then
    raise exception 'Este sorteio não tem pagamento por reverter.';
  end if;

  old_data := to_jsonb(c);

  select t.* into tx
  from public.treasury_transactions t
  where t.club_id=target_club
    and t.id=c.transaction_id
    and t.kind='income'
    and t.source_type='euromillions_draw_charge'
    and not exists (
      select 1 from public.treasury_transactions r
      where r.club_id=target_club and r.reversal_of=t.id
    )
  for update;

  if tx.id is null then
    select t.* into tx
    from public.treasury_transactions t
    where t.club_id=target_club
      and t.source_id=c.id
      and t.kind='income'
      and t.source_type='euromillions_draw_charge'
      and not exists (
        select 1 from public.treasury_transactions r
        where r.club_id=target_club and r.reversal_of=t.id
      )
    order by t.created_at desc, t.id desc
    limit 1
    for update;
  end if;

  if tx.id is null then
    raise exception 'Não foi encontrado o movimento financeiro deste pagamento.';
  end if;
  if abs(tx.amount-c.paid_amount) > 0.005 then
    raise exception 'O movimento financeiro não coincide com o valor pago.';
  end if;

  insert into public.treasury_transactions(
    club_id,kind,account_id,transaction_date,description,amount,
    payment_method,notes,source_type,source_id,reversal_of,created_by
  ) values (
    target_club,'expense',tx.account_id,current_date,
    'Reversão — '||tx.description,tx.amount,
    tx.payment_method,trim(p_reason),'euromillions_draw_charge_reversal',c.id,tx.id,auth.uid()
  ) returning id into reversal_id;

  update public.euromillions_draw_charges
  set paid_amount=0,
      paid_at=null,
      payment_method=null,
      transaction_id=null,
      updated_at=now(),
      updated_by=auth.uid()
  where id=c.id;

  select to_jsonb(x) into new_data
  from public.euromillions_draw_charges x
  where x.id=c.id;

  perform public.audit_event(
    target_club,
    'reverse_euromillions_draw_payment',
    'euromillions_draw_charge',
    c.id::text,
    old_data,
    new_data,
    trim(p_reason)
  );

  return reversal_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.reverse_euromillions_fine_payment_v1(target_club uuid, p_transaction uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  tx public.treasury_transactions%rowtype;
  reversal_id uuid;
  linked_total numeric := 0;
  linked_count integer := 0;
begin
  if auth.uid() is null then
    raise exception 'Autenticação necessária.';
  end if;
  if not public.has_club_permission(target_club,'manageLottery') then
    raise exception 'Sem permissão para reverter multas.';
  end if;
  if length(trim(coalesce(p_reason,''))) < 3 then
    raise exception 'Indica o motivo da reversão.';
  end if;

  select t.* into tx
  from public.treasury_transactions t
  where t.id=p_transaction
    and t.club_id=target_club
    and t.kind='income'
    and t.source_type in ('euromillions_fine_payment','euromillions_fine_payment_month')
  for update;

  if tx.id is null then
    raise exception 'Pagamento de multas não encontrado.';
  end if;
  if exists (
    select 1 from public.treasury_transactions r
    where r.club_id=target_club and r.reversal_of=tx.id
  ) then
    raise exception 'Este pagamento já foi revertido.';
  end if;

  select coalesce(sum(f.paid_amount),0), count(*)
  into linked_total, linked_count
  from public.euromillions_fines f
  where f.club_id=target_club
    and f.transaction_id=tx.id
    and f.paid_amount>0;

  if linked_count=0 then
    raise exception 'Não existem multas associadas a este movimento.';
  end if;
  if abs(linked_total-tx.amount) > 0.005 then
    raise exception 'As multas associadas não coincidem com o movimento financeiro; reversão bloqueada por segurança.';
  end if;

  insert into public.treasury_transactions(
    club_id,kind,account_id,transaction_date,description,amount,
    payment_method,notes,source_type,source_id,reversal_of,created_by
  ) values (
    target_club,'expense',tx.account_id,current_date,
    'Reversão — '||tx.description,tx.amount,
    tx.payment_method,trim(p_reason),'euromillions_fine_payment_reversal',tx.source_id,tx.id,auth.uid()
  ) returning id into reversal_id;

  update public.euromillions_fines
  set paid_amount=0,
      paid_at=null,
      payment_method=null,
      transaction_id=null,
      updated_at=now(),
      updated_by=auth.uid()
  where club_id=target_club
    and transaction_id=tx.id;

  perform public.audit_event(
    target_club,
    'reverse_euromillions_fine_payment',
    'euromillions_fine_payment',
    tx.id::text,
    to_jsonb(tx),
    jsonb_build_object('reversal_transaction_id',reversal_id),
    trim(p_reason)
  );

  return reversal_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.reverse_euromillions_month_payment_v1(target_club uuid, p_player uuid, p_year integer, p_month integer, p_reason text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  reversed_count integer := 0;
begin
  if auth.uid() is null then
    raise exception 'Autenticação necessária.';
  end if;
  if not public.has_club_permission(target_club,'manageLottery') then
    raise exception 'Sem permissão para reverter pagamentos.';
  end if;
  if length(trim(coalesce(p_reason,''))) < 3 then
    raise exception 'Indica o motivo da reversão.';
  end if;

  for r in
    select id
    from public.euromillions_draw_charges
    where club_id=target_club
      and player_id=p_player
      and extract(year from draw_date)=p_year
      and extract(month from draw_date)=p_month
      and paid_amount>0
    order by draw_date
  loop
    perform public.reverse_euromillions_draw_payment_v1(
      target_club,
      r.id,
      trim(p_reason)
    );
    reversed_count := reversed_count + 1;
  end loop;

  if reversed_count=0 then
    raise exception 'Não existem pagamentos deste mês por reverter.';
  end if;

  return reversed_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.reverse_euromillions_prize_receipt_v1(target_club uuid, p_prize uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  pr public.euromillions_prizes%rowtype;
  old_pr jsonb;
  new_pr jsonb;
  tx record;
  reversal_id uuid;
  first_reversal uuid;
  reversed_total numeric := 0;
  hit_n int := 0;
  hit_s int := 0;
  expected_cat int;
  expected_prize numeric := 0;
begin
  if auth.uid() is null then
    raise exception 'Autenticação necessária.';
  end if;
  if not public.has_club_permission(target_club,'manageLottery') then
    raise exception 'Sem permissão para reverter prémios.';
  end if;
  if length(trim(coalesce(p_reason,''))) < 3 then
    raise exception 'Indica o motivo da reversão.';
  end if;

  select * into pr
  from public.euromillions_prizes
  where id=p_prize and club_id=target_club
  for update;

  if pr.id is null then
    raise exception 'Prémio não encontrado.';
  end if;
  if coalesce(pr.received_amount,0) <= 0 then
    raise exception 'Este prémio não tem recebimentos por reverter.';
  end if;

  old_pr := to_jsonb(pr);

  for tx in
    select t.*
    from public.treasury_transactions t
    where t.club_id=target_club
      and t.source_id=pr.id
      and t.source_type in ('euromillions_prize','euromillions_prize_manual')
      and t.kind='income'
      and not exists (
        select 1
        from public.treasury_transactions r
        where r.club_id=target_club and r.reversal_of=t.id
      )
    order by t.created_at, t.id
    for update
  loop
    insert into public.treasury_transactions(
      club_id,kind,account_id,transaction_date,description,amount,
      payment_method,notes,source_type,source_id,reversal_of,created_by
    ) values (
      target_club,'expense',tx.account_id,current_date,
      'Reversão — '||tx.description,tx.amount,
      tx.payment_method,trim(p_reason),'euromillions_prize_reversal',pr.id,tx.id,auth.uid()
    ) returning id into reversal_id;

    if first_reversal is null then first_reversal := reversal_id; end if;
    reversed_total := reversed_total + tx.amount;
  end loop;

  if reversed_total <= 0 then
    raise exception 'Não foi encontrado o movimento financeiro do prémio para reverter.';
  end if;
  if abs(reversed_total - pr.received_amount) > 0.005 then
    raise exception 'Os movimentos financeiros do prémio não coincidem com o valor recebido.';
  end if;

  select
    (select count(*) from unnest(p.numbers) n where n=any(r.numbers)),
    (select count(*) from unnest(p.stars) s where s=any(r.stars))
  into hit_n, hit_s
  from public.euromillions_players p
  join public.euromillions_results r on r.id=pr.result_id
  where p.id=pr.player_id and p.club_id=target_club and r.club_id=target_club;

  expected_cat := public.euromillions_prize_category_v1(coalesce(hit_n,0),coalesce(hit_s,0));
  if expected_cat is not null then
    select coalesce((r.prize_table->>expected_cat::text)::numeric,0)
      into expected_prize
    from public.euromillions_results r
    where r.id=pr.result_id and r.club_id=target_club;
  end if;

  if expected_cat is null or coalesce(expected_prize,0) <= 0 then
    delete from public.euromillions_prizes where id=pr.id;
    new_pr := null;
  else
    update public.euromillions_prizes
    set category=expected_cat,
        matched_numbers=coalesce(hit_n,0),
        matched_stars=coalesce(hit_s,0),
        prize_amount=expected_prize,
        received_amount=0,
        received_at=null,
        payment_method=null,
        transaction_id=null,
        updated_at=now(),
        updated_by=auth.uid()
    where id=pr.id
    returning to_jsonb(public.euromillions_prizes.*) into new_pr;
  end if;

  perform public.audit_event(
    target_club,
    'reverse_euromillions_prize_receipt',
    'euromillions_prize',
    pr.id::text,
    old_pr,
    new_pr,
    trim(p_reason)
  );

  return first_reversal;
end;
$function$

CREATE OR REPLACE FUNCTION public.reverse_fee_adjustment_v1(target_club uuid, p_adjustment uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.fee_adjustments%rowtype; o public.fee_obligations%rowtype; v_new numeric; v_total numeric;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageFees') then raise exception 'Sem autorização para reverter ajustes.'; end if;
  if length(trim(coalesce(p_reason,'')))<3 then raise exception 'Indica o motivo da reversão.'; end if;
  select * into v from public.fee_adjustments where id=p_adjustment and club_id=target_club for update;
  if not found then raise exception 'Ajuste não encontrado.'; end if;
  if v.status='reversed' then raise exception 'O ajuste já foi revertido.'; end if;
  select * into o from public.fee_obligations where id=v.obligation_id for update;
  v_new:=o.adjustment_amount-v.amount; v_total:=greatest(0,o.amount+v_new-o.exempt_amount);
  if o.paid_amount>v_total then raise exception 'A reversão deixaria pagamentos acima do valor devido.'; end if;
  update public.fee_adjustments set status='reversed',reversed_at=now(),reversed_by=auth.uid(),reversal_reason=trim(p_reason) where id=p_adjustment;
  update public.fee_obligations set adjustment_amount=v_new where id=v.obligation_id;
  perform public.refresh_fee_obligation_status_v1(v.obligation_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.reverse_fee_exemption_v1(target_club uuid, p_exemption uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.fee_exemptions%rowtype;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageFees') then raise exception 'Sem autorização para reverter isenções.'; end if;
  if length(trim(coalesce(p_reason,'')))<3 then raise exception 'Indica o motivo da reversão.'; end if;
  select * into v from public.fee_exemptions where id=p_exemption and club_id=target_club for update;
  if not found then raise exception 'Isenção não encontrada.'; end if;
  if v.status='reversed' then raise exception 'A isenção já foi revertida.'; end if;
  update public.fee_exemptions set status='reversed',reversed_at=now(),reversed_by=auth.uid(),reversal_reason=trim(p_reason) where id=p_exemption;
  update public.fee_obligations set exempt_amount=greatest(0,exempt_amount-v.amount) where id=v.obligation_id;
  perform public.refresh_fee_obligation_status_v1(v.obligation_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.reverse_fee_payment_v1(target_club uuid, p_payment uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p public.fee_payments%rowtype; t public.treasury_transactions%rowtype; v_reversal uuid:=gen_random_uuid(); a record; c record; u record;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageFees') then raise exception 'Sem autorização para reverter pagamentos de quotas.'; end if;
  if length(trim(coalesce(p_reason,'')))<3 then raise exception 'Indica o motivo da reversão.'; end if;
  select * into p from public.fee_payments where id=p_payment and club_id=target_club for update;
  if not found then raise exception 'Pagamento não encontrado.'; end if;
  if p.status='reversed' then raise exception 'O pagamento já foi revertido.'; end if;
  select * into t from public.treasury_transactions where id=p.transaction_id and club_id=target_club for update;
  if not found then raise exception 'Movimento financeiro do pagamento não encontrado.'; end if;
  if exists(select 1 from public.treasury_transactions x where x.reversal_of=t.id) then raise exception 'O movimento financeiro já possui reversão.'; end if;
  for a in select obligation_id,amount from public.fee_payment_allocations where payment_id=p_payment and club_id=target_club loop
    update public.fee_obligations set paid_amount=greatest(0,paid_amount-a.amount) where id=a.obligation_id and club_id=target_club;
    perform public.refresh_fee_obligation_status_v1(a.obligation_id);
  end loop;
  for c in select * from public.fee_credits where club_id=target_club and member_id=p.member_id and payment_id=p_payment and amount>0 and entry_type='payment_excess' order by created_at loop
    for u in select * from public.fee_credits cu where cu.source_credit_id=c.id and cu.entry_type='application' and cu.amount<0 and not exists(select 1 from public.fee_credits rr where rr.reversal_of=cu.id) order by cu.created_at loop
      update public.fee_obligations set paid_amount=greatest(0,paid_amount-abs(u.amount)) where id=u.obligation_id and club_id=target_club;
      perform public.refresh_fee_obligation_status_v1(u.obligation_id);
      insert into public.fee_credits(club_id,member_id,amount,entry_type,obligation_id,source_credit_id,reversal_of,reason)
      values(target_club,p.member_id,abs(u.amount),'reversal',u.obligation_id,c.id,u.id,'Reversão da aplicação de crédito');
    end loop;
    insert into public.fee_credits(club_id,member_id,amount,entry_type,payment_id,source_credit_id,reversal_of,reason)
    values(target_club,p.member_id,-c.amount,'reversal',p_payment,c.id,c.id,'Reversão do excesso do pagamento');
  end loop;
  insert into public.treasury_transactions(id,club_id,kind,account_id,transaction_date,description,amount,payment_method,notes,source_type,source_id,reversal_of,created_by)
  values(v_reversal,target_club,'expense',t.account_id,current_date,'Reversão — '||t.description,t.amount,t.payment_method,trim(p_reason),'fee_payment_reversal',p_payment,t.id,auth.uid());
  update public.fee_payments set status='reversed',reversed_at=now(),reversed_by=auth.uid(),reversal_reason=trim(p_reason) where id=p_payment;
  update public.reported_payments set status='reversed',review_notes=trim(concat_ws(' · ',nullif(review_notes,''),'Pagamento revertido: '||trim(p_reason))),updated_at=now() where fee_payment_id=p_payment and status='approved';
  perform public.emit_domain_event(target_club,'FeePaymentReversed','fee',p_payment,jsonb_build_object('title','Pagamento de quotas revertido','description',coalesce(p.amount,0)::text||' € · '||trim(p_reason),'route','fees','priority','important','amount',p.amount));
  return v_reversal;
end;
$function$

CREATE OR REPLACE FUNCTION public.reverse_treasury_transaction_v1(target_club uuid, p_transaction uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_original public.treasury_transactions%rowtype;
  v_id uuid;
  v_kind public.transaction_kind;
  v_account uuid;
  v_destination uuid;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'reverseTreasuryMovement') then
    raise exception 'Sem permissão para reverter movimentos.';
  end if;
  if length(trim(coalesce(p_reason,'')))<3 then raise exception 'Indica o motivo da reversão.'; end if;

  select * into v_original from public.treasury_transactions
    where id=p_transaction and club_id=target_club for update;
  if not found then raise exception 'Movimento não encontrado.'; end if;
  if v_original.reversal_of is not null or v_original.kind='reversal' then
    raise exception 'Um movimento de reversão não pode ser revertido por este fluxo.';
  end if;
  if exists(select 1 from public.treasury_transactions r where r.reversal_of=p_transaction) then
    raise exception 'O movimento já foi revertido.';
  end if;
  if v_original.source_type is not null and v_original.source_type not in ('payable','receivable') then
    raise exception 'Este movimento pertence a outro módulo e deve ser corrigido na origem.';
  end if;

  if v_original.kind='income' then
    v_kind:='expense'; v_account:=v_original.account_id; v_destination:=null;
  elsif v_original.kind='expense' then
    v_kind:='income'; v_account:=v_original.account_id; v_destination:=null;
  elsif v_original.kind='transfer' then
    v_kind:='transfer'; v_account:=v_original.destination_account_id; v_destination:=v_original.account_id;
  else
    raise exception 'Tipo de movimento não reversível.';
  end if;

  insert into public.treasury_transactions(
    club_id,kind,account_id,destination_account_id,category_id,cost_center_id,event_id,
    transaction_date,description,amount,payment_method,notes,source_type,source_id,
    reversal_of,created_by
  ) values (
    target_club,v_kind,v_account,v_destination,v_original.category_id,v_original.cost_center_id,
    v_original.event_id,current_date,'Reversão — '||v_original.description,v_original.amount,
    v_original.payment_method,trim(p_reason),'reversal',p_transaction,p_transaction,auth.uid()
  ) returning id into v_id;

  if v_original.source_type='payable' and v_original.source_id is not null then
    update public.payables
      set settled_amount=greatest(0,settled_amount-v_original.amount),
          status=case
            when greatest(0,settled_amount-v_original.amount)=0 then 'open'
            when greatest(0,settled_amount-v_original.amount)<amount then 'partial'
            else 'paid'
          end
      where id=v_original.source_id and club_id=target_club;
  elsif v_original.source_type='receivable' and v_original.source_id is not null then
    update public.receivables
      set settled_amount=greatest(0,settled_amount-v_original.amount),
          status=case
            when greatest(0,settled_amount-v_original.amount)=0 then 'open'
            when greatest(0,settled_amount-v_original.amount)<amount then 'partial'
            else 'paid'
          end
      where id=v_original.source_id and club_id=target_club;
  end if;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.review_charge_payment_v1(target_club uuid, p_request uuid, p_action text, p_account uuid DEFAULT NULL::uuid, p_payment_method text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.financial_requests%rowtype; member_profile uuid; member_name text; method text; tx uuid;
begin
  if not public.financial_manager_v1(target_club) then raise exception 'Sem autorização.'; end if;
  select * into r from public.financial_requests where id=p_request and club_id=target_club for update;
  if not found or r.request_type<>'charge' then raise exception 'Cobrança não encontrada.'; end if;
  select m.profile_id,coalesce(nullif(m.nickname,''),m.full_name) into member_profile,member_name from public.members m where m.id=r.member_id;
  if p_action='reject' then
    if r.status<>'awaiting_validation' then raise exception 'Não existe comprovativo pendente de validação.'; end if;
    if nullif(btrim(coalesce(p_note,'')),'') is null then raise exception 'Indica o motivo da rejeição.'; end if;
    update public.financial_requests set status='awaiting_payment',review_note=btrim(p_note),reviewed_by=auth.uid(),reviewed_at=now() where id=p_request;
    perform public.notify_financial_profile_v1(target_club,member_profile,p_request,'Comprovativo não aceite',btrim(p_note),'high');
    perform public.financial_activity_v1(target_club,p_request,'Comprovativo rejeitado',btrim(p_note));
    return null;
  elsif p_action<>'approve' then raise exception 'Ação inválida.'; end if;
  method:=lower(btrim(coalesce(p_payment_method,'')));
  if method not in ('cash','mbway','bank_transfer','other') then raise exception 'Método de pagamento inválido.'; end if;
  if p_account is null or not exists(select 1 from public.treasury_accounts a where a.id=p_account and a.club_id=target_club and a.active=true) then raise exception 'Conta financeira inválida.'; end if;
  if method='cash' then
    if r.status not in ('awaiting_payment','awaiting_validation') then raise exception 'Cobrança não está pendente.'; end if;
  else
    if r.status<>'awaiting_validation' then raise exception 'O comprovativo ainda não foi submetido.'; end if;
    if not exists(select 1 from public.financial_request_attachments a where a.request_id=p_request and a.kind='member_payment_proof') then raise exception 'Não existe comprovativo anexado.'; end if;
  end if;
  insert into public.treasury_transactions(club_id,kind,account_id,transaction_date,description,amount,payment_method,notes,source_type,source_id,created_by)
  values(target_club,'income',p_account,current_date,'Cobrança - '||coalesce(member_name,'Membro')||' - '||r.description,r.amount,method,nullif(btrim(coalesce(p_note,'')),''),'financial_charge',p_request,auth.uid()) returning id into tx;
  update public.financial_requests set status='paid',payment_method=method,treasury_account_id=p_account,treasury_transaction_id=tx,review_note=null,reviewed_by=auth.uid(),reviewed_at=now(),paid_at=now(),paid_by=auth.uid() where id=p_request;
  perform public.notify_financial_profile_v1(target_club,member_profile,p_request,'Pagamento validado','Pagamento de '||to_char(r.amount,'FM999999990.00')||' € confirmado.','normal');
  perform public.financial_activity_v1(target_club,p_request,'Cobrança liquidada',coalesce(member_name,'Membro')||' · '||to_char(r.amount,'FM999999990.00')||' €');
  return tx;
end;
$function$

CREATE OR REPLACE FUNCTION public.review_reimbursement_v1(target_club uuid, p_request uuid, p_action text, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.financial_requests%rowtype; member_profile uuid; next_status text; title text; body text;
begin
  if not public.financial_manager_v1(target_club) then raise exception 'Sem autorização.'; end if;
  select * into r from public.financial_requests where id=p_request and club_id=target_club for update;
  if not found or r.request_type<>'reimbursement' or r.status<>'pending_review' then raise exception 'Pedido não está pendente de análise.'; end if;
  if p_action='approve' then next_status:='approved'; title:='Reembolso aprovado'; body:='O teu pedido foi aprovado e aguarda pagamento.';
  elsif p_action='reject' then if nullif(btrim(coalesce(p_note,'')),'') is null then raise exception 'Indica o motivo da rejeição.'; end if; next_status:='rejected'; title:='Reembolso rejeitado'; body:='O teu pedido foi rejeitado: '||btrim(p_note);
  elsif p_action='request_info' then if nullif(btrim(coalesce(p_note,'')),'') is null then raise exception 'Indica a informação em falta.'; end if; next_status:='needs_info'; title:='Reembolso precisa de informação'; body:=btrim(p_note);
  else raise exception 'Ação inválida.'; end if;
  update public.financial_requests set status=next_status,review_note=nullif(btrim(coalesce(p_note,'')),''),reviewed_by=auth.uid(),reviewed_at=now() where id=p_request;
  select m.profile_id into member_profile from public.members m where m.id=r.member_id;
  perform public.notify_financial_profile_v1(target_club,member_profile,p_request,title,body,case when p_action='request_info' then 'high' else 'normal' end);
  perform public.financial_activity_v1(target_club,p_request,title,body);
end;
$function$

CREATE OR REPLACE FUNCTION public.review_reported_fee_payment_v1(target_club uuid, p_report uuid, p_action text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.reported_payments%rowtype; v_payment uuid; v_action text:=lower(trim(coalesce(p_action,'')));
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageFees') then raise exception 'Sem autorização para validar pagamentos comunicados.'; end if;
  if v_action not in('approve','reject') then raise exception 'Ação inválida.'; end if;
  select * into v from public.reported_payments where id=p_report and club_id=target_club for update;
  if not found then raise exception 'Pagamento comunicado não encontrado.'; end if;
  if v.status<>'pending' then raise exception 'O pagamento comunicado já foi tratado.'; end if;
  if v_action='reject' then
    if length(trim(coalesce(p_notes,'')))<3 then raise exception 'Indica o motivo da rejeição.'; end if;
    update public.reported_payments set status='rejected',review_notes=trim(p_notes),reviewed_at=now(),reviewed_by=auth.uid() where id=p_report;
    return null;
  end if;
  v_payment:=public.register_fee_payment_batch_v1(target_club,v.member_id,v.amount,v.payment_method,v.paid_on,coalesce(nullif(trim(coalesce(p_notes,'')),''),v.notes),null,p_report);
  update public.reported_payments set review_notes=nullif(trim(coalesce(p_notes,'')),'') where id=p_report;
  return v_payment;
end;
$function$

CREATE OR REPLACE FUNCTION public.rollback_import_v1(target_club uuid, p_import uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_import public.imports%rowtype; r public.import_rows%rowtype; v_updated timestamptz; v_expected double precision; v_blocked boolean; v_count integer:=0;
begin
  if auth.uid() is null then raise exception 'Autenticação necessária.'; end if;
  select * into v_import from public.imports where id=p_import and club_id=target_club for update;
  if not found then raise exception 'Importação não encontrada.'; end if;
  if not public.import_target_allowed_v1(target_club,v_import.target) then raise exception 'Sem permissão.'; end if;
  if v_import.status<>'applied' then raise exception 'Apenas importações aplicadas podem ser revertidas.'; end if;
  begin
    for r in select * from public.import_rows where import_id=p_import order by row_number desc loop
      if r.target_row_id is null then raise exception 'Registo importado em falta.'; end if;
      v_expected:=(r.applied_snapshot->>'updated_at_epoch')::double precision; v_blocked:=false;
      case v_import.target
        when 'members' then
          select updated_at into v_updated from public.members where id=r.target_row_id and club_id=target_club; if not found then raise exception 'Membro importado já não existe.'; end if;
          if abs(extract(epoch from v_updated)-v_expected)>0.001 then raise exception 'Membro importado foi alterado depois da importação.'; end if;
          select exists(select 1 from public.member_motorcycles where member_id=r.target_row_id) or exists(select 1 from public.maintenance_records where member_id=r.target_row_id) or exists(select 1 from public.member_patch_awards where member_id=r.target_row_id) or exists(select 1 from public.member_positions where member_id=r.target_row_id) or exists(select 1 from public.financial_requests where member_id=r.target_row_id) or exists(select 1 from public.event_registrations where member_id=r.target_row_id) or exists(select 1 from public.event_volunteers where member_id=r.target_row_id) or exists(select 1 from public.shop_orders where member_id=r.target_row_id) or exists(select 1 from public.euromillions_players where member_id=r.target_row_id) or exists(select 1 from public.euromillions_participations where member_id=r.target_row_id) or exists(select 1 from public.asset_loans where member_id=r.target_row_id) or exists(select 1 from public.inventory_assets where responsible_member_id=r.target_row_id) or exists(select 1 from public.weekly_dinners where assigned_member_id=r.target_row_id) or exists(select 1 from public.weekly_officer_absences where member_id=r.target_row_id) or exists(select 1 from public.weekly_officer_swap_requests where requester_member_id=r.target_row_id or requested_member_id=r.target_row_id) into v_blocked;
          if v_blocked then raise exception 'Membro importado já possui dados associados.'; end if; delete from public.members where id=r.target_row_id and club_id=target_club;
        when 'inventory_products' then
          select updated_at into v_updated from public.products where id=r.target_row_id and club_id=target_club; if not found then raise exception 'Produto importado já não existe.'; end if;
          if abs(extract(epoch from v_updated)-v_expected)>0.001 then raise exception 'Produto importado foi alterado depois da importação.'; end if;
          select exists(select 1 from public.product_variants where product_id=r.target_row_id) or exists(select 1 from public.product_images where product_id=r.target_row_id) or exists(select 1 from public.stock_movements where product_id=r.target_row_id) or exists(select 1 from public.shop_order_items where product_id=r.target_row_id) or exists(select 1 from public.member_patch_awards where product_id=r.target_row_id) or exists(select 1 from public.bar_operations where product_id=r.target_row_id) or exists(select 1 from public.bar_consumption_session_items where product_id=r.target_row_id) or exists(select 1 from public.inventory_count_items where product_id=r.target_row_id) or exists(select 1 from public.inventory_prices where product_id=r.target_row_id) or exists(select 1 from public.inventory_visibility where product_id=r.target_row_id) into v_blocked;
          if v_blocked then raise exception 'Produto importado já possui dados associados.'; end if; delete from public.products where id=r.target_row_id and club_id=target_club;
        when 'events' then
          select updated_at into v_updated from public.events where id=r.target_row_id and club_id=target_club; if not found then raise exception 'Evento importado já não existe.'; end if;
          if abs(extract(epoch from v_updated)-v_expected)>0.001 then raise exception 'Evento importado foi alterado depois da importação.'; end if;
          select exists(select 1 from public.event_registrations where event_id=r.target_row_id) or exists(select 1 from public.event_volunteers where event_id=r.target_row_id) or exists(select 1 from public.event_partners where event_id=r.target_row_id) or exists(select 1 from public.treasury_transactions where event_id=r.target_row_id) or exists(select 1 from public.stock_movements where event_id=r.target_row_id) or exists(select 1 from public.inventory_locations where event_id=r.target_row_id) or exists(select 1 from public.inventory_count_sessions where event_id=r.target_row_id) or exists(select 1 from public.bar_operations where event_id=r.target_row_id) or exists(select 1 from public.bar_consumption_sessions where event_id=r.target_row_id) or exists(select 1 from public.asset_loans where event_id=r.target_row_id) into v_blocked;
          if v_blocked then raise exception 'Evento importado já possui dados associados.'; end if; delete from public.events where id=r.target_row_id and club_id=target_club;
        when 'fee_plans' then
          select updated_at into v_updated from public.fee_plans where id=r.target_row_id and club_id=target_club; if not found then raise exception 'Plano importado já não existe.'; end if;
          if v_updated is not null and abs(extract(epoch from v_updated)-v_expected)>0.001 then raise exception 'Plano importado foi alterado depois da importação.'; end if;
          if exists(select 1 from public.fee_obligations where fee_plan_id=r.target_row_id) then raise exception 'Plano importado já possui quotas associadas.'; end if; delete from public.fee_plans where id=r.target_row_id and club_id=target_club;
      end case;
      update public.import_rows set reverted_at=now(),updated_at=now() where id=r.id; v_count:=v_count+1;
    end loop;
  exception when others then
    insert into public.audit_log(club_id,actor_id,entity_type,entity_id,action,after_data,data) values(target_club,auth.uid(),'import',p_import::text,'import_rollback_blocked',jsonb_build_object('error_code','rollback_blocked'),jsonb_build_object('import_id',p_import));
    return jsonb_build_object('success',false,'error_code','rollback_blocked');
  end;
  update public.imports set status='reverted',reverted_at=now(),updated_at=now() where id=p_import;
  insert into public.audit_log(club_id,actor_id,entity_type,entity_id,action,after_data,data) values(target_club,auth.uid(),'import',p_import::text,'import_reverted',jsonb_build_object('reverted_rows',v_count),jsonb_build_object('import_id',p_import));
  return jsonb_build_object('success',true,'reverted_rows',v_count);
end; $function$

CREATE OR REPLACE FUNCTION public.save_agenda_item_v1(target_club uuid, p_item uuid, p_item_type text, p_title text, p_description text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_all_day boolean, p_location text, p_audience text, p_priority text, p_status text, p_notify_now boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_old jsonb; v_new jsonb; v_date_label text;
begin
  if not public.can_manage_agenda_v1(target_club) then raise exception 'Sem autorização para gerir a Agenda.'; end if;
  if p_item_type not in ('meeting','deadline','reminder') then raise exception 'Tipo inválido.'; end if;
  if nullif(btrim(coalesce(p_title,'')),'') is null then raise exception 'Indica o título.'; end if;
  if p_starts_at is null then raise exception 'Indica a data/hora.'; end if;
  if p_ends_at is not null and p_ends_at<p_starts_at then raise exception 'A data final não pode ser anterior à inicial.'; end if;
  if p_audience not in ('all','direction') then raise exception 'Destinatários inválidos.'; end if;
  if p_priority not in ('low','normal','high') then raise exception 'Prioridade inválida.'; end if;
  if p_status not in ('planned','completed','cancelled') then raise exception 'Estado inválido.'; end if;

  if p_item is null then
    insert into public.agenda_items(club_id,item_type,title,description,starts_at,ends_at,all_day,location,audience,priority,status)
    values(target_club,p_item_type,btrim(p_title),nullif(btrim(coalesce(p_description,'')),''),p_starts_at,p_ends_at,
      coalesce(p_all_day,false),nullif(btrim(coalesce(p_location,'')),''),p_audience,p_priority,p_status)
    returning id into v_id;
  else
    select to_jsonb(a) into v_old from public.agenda_items a where a.id=p_item and a.club_id=target_club;
    if v_old is null then raise exception 'Item da Agenda não encontrado.'; end if;
    update public.agenda_items set item_type=p_item_type,title=btrim(p_title),description=nullif(btrim(coalesce(p_description,'')),''),
      starts_at=p_starts_at,ends_at=p_ends_at,all_day=coalesce(p_all_day,false),location=nullif(btrim(coalesce(p_location,'')),''),
      audience=p_audience,priority=p_priority,status=p_status,updated_at=now(),updated_by=(select auth.uid())
    where id=p_item and club_id=target_club returning id into v_id;
  end if;

  select to_jsonb(a) into v_new from public.agenda_items a where a.id=v_id;
  perform public.audit_event(target_club,case when p_item is null then 'agenda_item_created' else 'agenda_item_updated' end,
    'agenda_item',v_id::text,v_old,v_new,null);

  if coalesce(p_notify_now,false) and p_status='planned' then
    v_date_label:=to_char(p_starts_at at time zone 'Europe/Lisbon','DD/MM/YYYY HH24:MI');
    perform public.agenda_notify_profiles_v1(target_club,p_audience,'Agenda: '||btrim(p_title),
      'Novo item na Agenda para '||v_date_label||'.',v_id);
  end if;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_bar_product_v3(target_club uuid, p_product uuid, p_name text, p_sku text, p_category text, p_description text, p_supplier text, p_purchase_unit text, p_consumption_unit text, p_units_per_purchase numeric, p_purchase_cost numeric, p_minimum_stock numeric, p_sale_options jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_product_id uuid;
  v_option jsonb;
  v_option_id uuid;
  v_name text;
  v_stock_quantity numeric;
  v_public_price numeric;
  v_member_price numeric;
  v_sort integer;
  v_first_public numeric:=0;
  v_count integer:=0;
  v_updated integer;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageBar') then
    raise exception 'Sem autorização para gerir artigos do Bar.';
  end if;
  if nullif(btrim(coalesce(p_name,'')),'') is null then
    raise exception 'Indica o nome do artigo.';
  end if;
  if coalesce(p_units_per_purchase,0)<=0 then
    raise exception 'A quantidade por embalagem de compra deve ser superior a zero.';
  end if;
  if coalesce(p_purchase_cost,0)<0 or coalesce(p_minimum_stock,0)<0 then
    raise exception 'Custos e stock mínimo não podem ser negativos.';
  end if;
  if p_sale_options is null or jsonb_typeof(p_sale_options)<>'array' or jsonb_array_length(p_sale_options)=0 then
    raise exception 'Define pelo menos uma forma de venda.';
  end if;

  for v_option in select value from jsonb_array_elements(p_sale_options)
  loop
    v_name:=nullif(btrim(coalesce(v_option->>'name','')),'');
    if v_name is null then raise exception 'Todas as formas de venda precisam de nome.'; end if;
    begin
      v_stock_quantity:=(v_option->>'stock_quantity')::numeric;
      v_public_price:=(v_option->>'public_price')::numeric;
      v_member_price:=(v_option->>'member_price')::numeric;
    exception when others then
      raise exception 'Quantidade ou preço inválido numa forma de venda.';
    end;
    if coalesce(v_stock_quantity,0)<=0 then raise exception 'A quantidade de stock por venda deve ser superior a zero.'; end if;
    if coalesce(v_public_price,0)<0 or coalesce(v_member_price,0)<0 then raise exception 'Os preços não podem ser negativos.'; end if;
    v_count:=v_count+1;
    if v_count=1 then v_first_public:=v_public_price; end if;
  end loop;

  if p_product is null then
    insert into public.products(
      club_id,inventory_area,name,sku,category,description,supplier,unit,
      purchase_unit,consumption_unit,units_per_purchase,purchase_cost,cost,
      sale_price,minimum_stock,current_stock,reserved_stock,active,created_by,updated_by
    ) values (
      target_club,'bar',btrim(p_name),nullif(btrim(coalesce(p_sku,'')),''),
      coalesce(nullif(btrim(coalesce(p_category,'')),''),'Bebidas'),
      nullif(btrim(coalesce(p_description,'')),''),nullif(btrim(coalesce(p_supplier,'')),''),
      coalesce(nullif(btrim(coalesce(p_consumption_unit,'')),''),'unidade'),
      coalesce(nullif(btrim(coalesce(p_purchase_unit,'')),''),'unidade'),
      coalesce(nullif(btrim(coalesce(p_consumption_unit,'')),''),'unidade'),
      p_units_per_purchase,coalesce(p_purchase_cost,0),coalesce(p_purchase_cost,0)/p_units_per_purchase,
      v_first_public,coalesce(p_minimum_stock,0),0,0,true,auth.uid(),auth.uid()
    ) returning id into v_product_id;
  else
    select id into v_product_id
    from public.products
    where id=p_product and club_id=target_club and inventory_area='bar'
    for update;
    if v_product_id is null then raise exception 'Artigo do Bar não encontrado.'; end if;

    update public.products set
      name=btrim(p_name),
      sku=nullif(btrim(coalesce(p_sku,'')),''),
      category=coalesce(nullif(btrim(coalesce(p_category,'')),''),'Bebidas'),
      description=nullif(btrim(coalesce(p_description,'')),''),
      supplier=nullif(btrim(coalesce(p_supplier,'')),''),
      unit=coalesce(nullif(btrim(coalesce(p_consumption_unit,'')),''),'unidade'),
      purchase_unit=coalesce(nullif(btrim(coalesce(p_purchase_unit,'')),''),'unidade'),
      consumption_unit=coalesce(nullif(btrim(coalesce(p_consumption_unit,'')),''),'unidade'),
      units_per_purchase=p_units_per_purchase,
      purchase_cost=coalesce(p_purchase_cost,0),
      cost=coalesce(p_purchase_cost,0)/p_units_per_purchase,
      sale_price=v_first_public,
      minimum_stock=coalesce(p_minimum_stock,0),
      updated_by=auth.uid(),updated_at=now()
    where id=v_product_id;

    update public.bar_product_sale_options
    set active=false, updated_by=auth.uid(), updated_at=now()
    where product_id=v_product_id and club_id=target_club;
  end if;

  v_sort:=0;
  for v_option in select value from jsonb_array_elements(p_sale_options)
  loop
    v_sort:=v_sort+10;
    v_name:=btrim(v_option->>'name');
    v_stock_quantity:=(v_option->>'stock_quantity')::numeric;
    v_public_price:=(v_option->>'public_price')::numeric;
    v_member_price:=(v_option->>'member_price')::numeric;
    v_option_id:=null;
    begin
      if nullif(v_option->>'id','') is not null then v_option_id:=(v_option->>'id')::uuid; end if;
    exception when others then
      raise exception 'Identificador inválido numa forma de venda.';
    end;

    if v_option_id is not null then
      update public.bar_product_sale_options set
        name=v_name,stock_quantity=v_stock_quantity,public_price=v_public_price,
        member_price=v_member_price,sort_order=v_sort,active=true,
        updated_by=auth.uid(),updated_at=now()
      where id=v_option_id and product_id=v_product_id and club_id=target_club;
      get diagnostics v_updated = row_count;
      if v_updated=0 then raise exception 'Forma de venda inválida para este artigo.'; end if;
    else
      insert into public.bar_product_sale_options(
        club_id,product_id,name,stock_quantity,public_price,member_price,sort_order,active,created_by,updated_by
      ) values (
        target_club,v_product_id,v_name,v_stock_quantity,v_public_price,v_member_price,v_sort,true,auth.uid(),auth.uid()
      );
    end if;
  end loop;

  return jsonb_build_object('id',v_product_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.save_cost_center_v1(target_club uuid, p_id uuid, p_name text, p_code text DEFAULT NULL::text, p_active boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageTreasuryPlanning') then
    raise exception 'Sem permissão para gerir centros de custo.';
  end if;
  if length(trim(coalesce(p_name,'')))<2 then raise exception 'Indica o nome do centro de custo.'; end if;

  if p_id is null then
    insert into public.cost_centers(club_id,name,code,active,created_by)
    values(target_club,trim(p_name),nullif(trim(coalesce(p_code,'')),''),coalesce(p_active,true),auth.uid())
    returning id into v_id;
  else
    update public.cost_centers
      set name=trim(p_name),code=nullif(trim(coalesce(p_code,'')),''),active=coalesce(p_active,true)
      where id=p_id and club_id=target_club
      returning id into v_id;
    if v_id is null then raise exception 'Centro de custo não encontrado.'; end if;
  end if;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_fee_obligation_v1(target_club uuid, p_obligation uuid, p_member uuid, p_reference_year integer, p_reference_month integer, p_due_date date, p_amount numeric, p_obligation_type text, p_notes text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageFees') then raise exception 'Sem autorização para gerir quotas.'; end if;
  if p_amount is null or p_amount<0 then raise exception 'O valor da quota é inválido.'; end if;
  if p_reference_year is null or p_reference_year<2000 or p_reference_year>2200 then raise exception 'Ano inválido.'; end if;
  if p_obligation_type not in('monthly','registration') then raise exception 'Tipo de quota inválido.'; end if;
  if p_obligation_type='monthly' and (p_reference_month is null or p_reference_month<1 or p_reference_month>12) then raise exception 'Mês inválido.'; end if;
  if not exists(select 1 from public.members where id=p_member and club_id=target_club) then raise exception 'Membro inválido.'; end if;
  if p_obligation is null then
    insert into public.fee_obligations(club_id,member_id,reference_year,reference_month,due_date,amount,paid_amount,exempt_amount,adjustment_amount,status,obligation_type,notes)
    values(target_club,p_member,p_reference_year,case when p_obligation_type='registration' then null else p_reference_month end,p_due_date,p_amount,0,0,0,'pending',p_obligation_type,nullif(trim(coalesce(p_notes,'')),'')) returning id into v_id;
  else
    if exists(select 1 from public.fee_payment_allocations where obligation_id=p_obligation) then raise exception 'A quota já tem pagamentos. Usa ajustes, isenções ou reversões.'; end if;
    update public.fee_obligations set member_id=p_member,reference_year=p_reference_year,
      reference_month=case when p_obligation_type='registration' then null else p_reference_month end,
      due_date=p_due_date,amount=p_amount,obligation_type=p_obligation_type,notes=nullif(trim(coalesce(p_notes,'')),'')
    where id=p_obligation and club_id=target_club returning id into v_id;
    if v_id is null then raise exception 'Quota não encontrada.'; end if;
  end if;
  perform public.refresh_fee_obligation_status_v1(v_id); return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_financial_ocr_review_v1(target_club uuid, p_job uuid, p_supplier_name text, p_supplier_tax_id text, p_document_number text, p_document_date date, p_currency text, p_subtotal numeric, p_tax_total numeric, p_total numeric, p_payment_method text, p_confidence numeric, p_line_items jsonb, p_warnings jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare j public.financial_ocr_jobs%rowtype; v_allowed boolean;
begin
  if auth.uid() is null then raise exception 'Sessão inválida.'; end if;
  select * into j from public.financial_ocr_jobs where id=p_job and club_id=target_club for update;
  if not found then raise exception 'Pedido OCR não encontrado.'; end if;
  v_allowed:=case when j.source_kind='bar_import' then public.has_club_permission(target_club,'manageBar') else (public.has_club_permission(target_club,'createTreasuryMovement') or public.has_club_permission(target_club,'approveExpenseRequests')) end;
  if not v_allowed then raise exception 'Sem autorização para rever este OCR.'; end if;
  if j.status not in ('ready','reviewed') then raise exception 'O OCR ainda não está pronto para revisão.'; end if;
  if p_line_items is null or jsonb_typeof(p_line_items)<>'array' then raise exception 'Linhas OCR inválidas.'; end if;
  if p_warnings is null or jsonb_typeof(p_warnings)<>'array' then raise exception 'Avisos OCR inválidos.'; end if;
  update public.financial_ocr_jobs set supplier_name=nullif(btrim(coalesce(p_supplier_name,'')),''),supplier_tax_id=nullif(btrim(coalesce(p_supplier_tax_id,'')),''),document_number=nullif(btrim(coalesce(p_document_number,'')),''),document_date=p_document_date,currency=upper(nullif(btrim(coalesce(p_currency,'')),'')),subtotal=p_subtotal,tax_total=p_tax_total,total=p_total,payment_method=nullif(btrim(coalesce(p_payment_method,'')),''),confidence=case when p_confidence is null then confidence else greatest(0,least(1,p_confidence)) end,line_items=p_line_items,warnings=p_warnings,status='reviewed',reviewed_at=now(),reviewed_by=auth.uid() where id=p_job;
end; $function$

CREATE OR REPLACE FUNCTION public.save_member_motorcycle_v1(target_club uuid, p_member uuid, p_motorcycle uuid, p_brand text, p_model text, p_year integer, p_registration text, p_nickname text, p_acquired_on date, p_notes text, p_primary boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  v_allowed boolean;
  v_primary boolean:=coalesce(p_primary,false);
begin
  if auth.uid() is null then raise exception 'Autenticação necessária.'; end if;
  select exists(
    select 1 from public.members m
    where m.id=p_member and m.club_id=target_club
      and (
        public.has_club_permission(target_club,'manageMembers')
        or (
          m.profile_id=auth.uid()
          and public.has_club_permission(target_club,'editOwnMemberProfile')
        )
      )
  ) into v_allowed;
  if not v_allowed then raise exception 'Sem permissão para gerir as motas deste membro.'; end if;
  if nullif(trim(coalesce(p_brand,'')),'') is null
     and nullif(trim(coalesce(p_model,'')),'') is null then
    raise exception 'Indica pelo menos a marca ou o modelo da mota.';
  end if;
  if p_year is not null and (p_year<1900 or p_year>extract(year from current_date)::int+1) then
    raise exception 'Ano da mota inválido.';
  end if;

  if p_motorcycle is null then
    if not exists(
      select 1 from public.member_motorcycles
      where club_id=target_club and member_id=p_member and active=true and primary_motorcycle=true
    ) then v_primary:=true; end if;
    if v_primary then
      update public.member_motorcycles
      set primary_motorcycle=false,updated_at=now(),updated_by=auth.uid()
      where club_id=target_club and member_id=p_member and active=true and primary_motorcycle=true;
    end if;
    insert into public.member_motorcycles(
      club_id,member_id,brand,model,year,registration,nickname,primary_motorcycle,
      active,acquired_on,retired_on,notes,created_by,updated_by
    ) values (
      target_club,p_member,nullif(trim(coalesce(p_brand,'')),''),nullif(trim(coalesce(p_model,'')),''),
      p_year,nullif(upper(trim(coalesce(p_registration,''))),''),nullif(trim(coalesce(p_nickname,'')),''),
      v_primary,true,p_acquired_on,null,nullif(trim(coalesce(p_notes,'')),''),auth.uid(),auth.uid()
    ) returning id into v_id;
  else
    select id into v_id from public.member_motorcycles
    where id=p_motorcycle and club_id=target_club and member_id=p_member;
    if v_id is null then raise exception 'Mota não encontrada.'; end if;
    if v_primary then
      update public.member_motorcycles
      set primary_motorcycle=false,updated_at=now(),updated_by=auth.uid()
      where club_id=target_club and member_id=p_member and id<>p_motorcycle
        and active=true and primary_motorcycle=true;
    end if;
    update public.member_motorcycles
    set brand=nullif(trim(coalesce(p_brand,'')),''),
        model=nullif(trim(coalesce(p_model,'')),''),
        year=p_year,
        registration=nullif(upper(trim(coalesce(p_registration,''))),''),
        nickname=nullif(trim(coalesce(p_nickname,'')),''),
        primary_motorcycle=v_primary,
        active=true,
        acquired_on=p_acquired_on,
        retired_on=null,
        notes=nullif(trim(coalesce(p_notes,'')),''),
        updated_at=now(),updated_by=auth.uid()
    where id=p_motorcycle;
  end if;
  return v_id;
end
$function$

CREATE OR REPLACE FUNCTION public.save_member_v1(target_club uuid, target_member uuid, p_member_number integer, p_full_name text, p_nickname text, p_email text, p_phone text, p_status text, p_birth_date date, p_joined_at date, p_prospect_joined_at date, p_full_colors_at date, p_notes text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare result_id uuid;
begin
  if not public.has_club_permission(target_club,'manageMembers') then raise exception 'Sem autorização.'; end if;
  if target_member is null then
    insert into public.members(club_id,member_number,full_name,nickname,email,phone,status,birth_date,joined_at,prospect_joined_at,full_colors_at,notes)
    values(target_club,p_member_number,p_full_name,p_nickname,p_email,p_phone,p_status::public.member_status,p_birth_date,p_joined_at,p_prospect_joined_at,p_full_colors_at,p_notes) returning id into result_id;
  else
    update public.members set member_number=p_member_number,full_name=p_full_name,nickname=p_nickname,email=p_email,phone=p_phone,status=p_status::public.member_status,birth_date=p_birth_date,joined_at=p_joined_at,prospect_joined_at=p_prospect_joined_at,full_colors_at=p_full_colors_at,notes=p_notes,updated_at=now()
    where id=target_member and club_id=target_club returning id into result_id;
  end if;
  if result_id is null then raise exception 'Não foi possível guardar o membro.'; end if;
  return result_id;
end; $function$

CREATE OR REPLACE FUNCTION public.save_weekly_dinner_v1(target_club uuid, p_dinner uuid, p_date date, p_assigned_member uuid DEFAULT NULL::uuid, p_external_name text DEFAULT NULL::text, p_dish text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_status text DEFAULT 'planned'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_old public.weekly_dinners%rowtype; v_new public.weekly_dinners%rowtype; v_kind text; v_source text; v_rebuild_from date;
begin
  if not public.can_manage_weekly_officer_v1(target_club) then raise exception 'Apenas Presidente, Vice-Presidente ou Superadmin podem alterar a escala.'; end if;
  if p_status not in ('planned','completed','cancelled') then raise exception 'Estado inválido para edição.'; end if;
  if p_assigned_member is not null and not exists(select 1 from public.members where id=p_assigned_member and club_id=target_club) then raise exception 'Membro inválido.'; end if;
  if p_assigned_member is not null and nullif(btrim(coalesce(p_external_name,'')),'') is not null then raise exception 'Escolhe um membro ou um externo, não ambos.'; end if;
  if p_dinner is null then
    if p_date is null then raise exception 'Indica a data.'; end if; v_kind:='extraordinary';
    v_source:=case when nullif(btrim(coalesce(p_external_name,'')),'') is not null then 'external' else 'manual' end;
    insert into public.weekly_dinners(club_id,dinner_date,dinner_kind,status,assigned_member_id,external_name,dish,notes,assignment_source,generated)
    values(target_club,p_date,'extraordinary',p_status,p_assigned_member,nullif(btrim(coalesce(p_external_name,'')),''),nullif(btrim(coalesce(p_dish,'')),''),nullif(btrim(coalesce(p_notes,'')),''),v_source,false) returning id into v_id;
  else
    select * into v_old from public.weekly_dinners where id=p_dinner and club_id=target_club for update;
    if not found then raise exception 'Jantar não encontrado.'; end if; v_kind:=v_old.dinner_kind;
    if v_kind='regular' and p_date is distinct from v_old.dinner_date then raise exception 'A data de uma quinta oficial não pode ser alterada.'; end if;
    v_source:=case when nullif(btrim(coalesce(p_external_name,'')),'') is not null then 'external' when p_assigned_member is distinct from v_old.assigned_member_id then 'manual' else v_old.assignment_source end;
    update public.weekly_dinners set dinner_date=case when v_kind='regular' then dinner_date else p_date end,status=p_status,assigned_member_id=p_assigned_member,
      external_name=nullif(btrim(coalesce(p_external_name,'')),''),dish=nullif(btrim(coalesce(p_dish,'')),''),notes=nullif(btrim(coalesce(p_notes,'')),''),assignment_source=v_source,
      updated_at=now(),updated_by=(select auth.uid()) where id=p_dinner returning * into v_new; v_id:=p_dinner;
  end if;
  select * into v_new from public.weekly_dinners where id=v_id;
  perform public.audit_event(target_club,'weekly_dinner_saved','weekly_dinner',v_id::text,case when p_dinner is null then null else to_jsonb(v_old) end,to_jsonb(v_new),null);
  if v_kind='regular' then v_rebuild_from:=greatest(current_date,v_new.dinner_date+1); perform public.rebuild_weekly_officer_future_internal_v1(target_club,v_rebuild_from); end if;
  if v_new.assigned_member_id is not null and (p_dinner is null or v_old.assigned_member_id is distinct from v_new.assigned_member_id) then
    perform public.weekly_officer_notify_member_v1(target_club,v_new.assigned_member_id,'Alteração na escala de jantares','Ficaste escalado para o jantar de '||to_char(v_new.dinner_date,'DD/MM/YYYY')||'.','weekly_dinner',v_id);
  end if; return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_weekly_officer_absence_v1(target_club uuid, p_absence uuid, p_member uuid, p_absence_kind text, p_starts_on date, p_ends_on date, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_old jsonb; v_new jsonb;
begin
  if not public.can_manage_weekly_officer_v1(target_club) then raise exception 'Sem autorização para gerir ausências/férias.'; end if;
  if p_absence_kind not in ('vacation','absence') then raise exception 'Tipo inválido.'; end if;
  if p_starts_on is null or p_ends_on is null or p_ends_on<p_starts_on then raise exception 'Intervalo de datas inválido.'; end if;
  if not exists(select 1 from public.members where id=p_member and club_id=target_club) then raise exception 'Membro inválido.'; end if;
  if p_absence is null then
    insert into public.weekly_officer_absences(club_id,member_id,absence_kind,starts_on,ends_on,notes)
    values(target_club,p_member,p_absence_kind,p_starts_on,p_ends_on,nullif(btrim(coalesce(p_notes,'')),'')) returning id into v_id;
  else
    select to_jsonb(a) into v_old from public.weekly_officer_absences a where a.id=p_absence and a.club_id=target_club;
    if v_old is null then raise exception 'Ausência/férias não encontrada.'; end if;
    update public.weekly_officer_absences set member_id=p_member,absence_kind=p_absence_kind,starts_on=p_starts_on,ends_on=p_ends_on,
      notes=nullif(btrim(coalesce(p_notes,'')),''),updated_at=now(),updated_by=(select auth.uid()) where id=p_absence and club_id=target_club returning id into v_id;
  end if;
  select to_jsonb(a) into v_new from public.weekly_officer_absences a where a.id=v_id;
  perform public.audit_event(target_club,'weekly_officer_absence_saved','weekly_officer_absence',v_id::text,v_old,v_new,null);
  perform public.rebuild_weekly_officer_future_internal_v1(target_club,greatest(current_date,p_starts_on)); return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_budget_status_v1(target_club uuid, p_budget uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_current text;
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageTreasuryPlanning') then
    raise exception 'Sem permissão para gerir orçamentos.';
  end if;
  select status into v_current from public.budgets where id=p_budget and club_id=target_club for update;
  if not found then raise exception 'Orçamento não encontrado.'; end if;

  if p_status='approved' and v_current='draft' then
    update public.budgets set status='approved',approved_at=now(),approved_by=auth.uid() where id=p_budget;
  elsif p_status='closed' and v_current='approved' then
    update public.budgets set status='closed',closed_at=now(),closed_by=auth.uid() where id=p_budget;
  else
    raise exception 'Transição de estado do orçamento inválida.';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_event_shift_member_status_v1(p_assignment uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v public.event_shift_members%rowtype;
  v_profile uuid;
begin
  if (select auth.uid()) is null then
    raise exception 'Autenticação necessária.';
  end if;
  if p_status not in ('assigned','confirmed','present','absent','cancelled') then
    raise exception 'Estado inválido.';
  end if;
  select * into v
  from public.event_shift_members
  where id = p_assignment
  for update;
  if not found then
    raise exception 'Atribuição não encontrada.';
  end if;
  if v.member_id is not null then
    select m.profile_id into v_profile
    from public.members m
    where m.id = v.member_id;
    if v_profile is distinct from (select auth.uid())
       and not public.has_club_permission(v.club_id, 'manageEventOperations') then
      raise exception 'Sem permissão para atualizar este turno.';
    end if;
  elsif not public.has_club_permission(v.club_id, 'manageEventOperations') then
    raise exception 'Sem permissão para atualizar este turno.';
  end if;
  update public.event_shift_members
  set status = p_status,
      checked_in_at = case
        when p_status = 'present' then coalesce(checked_in_at, now())
        else checked_in_at
      end,
      checked_out_at = case
        when p_status in ('absent','cancelled') then coalesce(checked_out_at, now())
        else checked_out_at
      end
  where id = p_assignment;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_notification_preference_v1(target_club uuid, p_module_code text, p_in_app_enabled boolean, p_push_enabled boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_module text:=lower(btrim(coalesce(p_module_code,'')));
begin
  if auth.uid() is null or not public.has_club_access(target_club) then
