CREATE OR REPLACE FUNCTION public.set_weekly_dinner_closed_v1(target_club uuid, p_dinner uuid, p_closed boolean, p_notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_old public.weekly_dinners%rowtype; v_new public.weekly_dinners%rowtype;
begin
  if not public.can_manage_weekly_officer_v1(target_club) then raise exception 'Sem autorização para fechar/reabrir uma quinta-feira.'; end if;
  select * into v_old from public.weekly_dinners where id=p_dinner and club_id=target_club and dinner_kind='regular' for update;
  if not found then raise exception 'Quinta-feira oficial não encontrada.'; end if;
  update public.weekly_dinners set status=case when p_closed then 'closed' else 'planned' end,assigned_member_id=case when p_closed then null else assigned_member_id end,
    assignment_source='auto',notes=coalesce(nullif(btrim(coalesce(p_notes,'')),''),notes),updated_at=now(),updated_by=(select auth.uid()) where id=p_dinner returning * into v_new;
  perform public.audit_event(target_club,case when p_closed then 'weekly_dinner_closed' else 'weekly_dinner_reopened' end,'weekly_dinner',p_dinner::text,to_jsonb(v_old),to_jsonb(v_new),p_notes);
  perform public.rebuild_weekly_officer_future_internal_v1(target_club,greatest(current_date,v_old.dinner_date));
end;
$function$

CREATE OR REPLACE FUNCTION public.set_weekly_dinner_financial_closed_v1(target_club uuid, p_dinner uuid, p_closed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare f public.weekly_dinner_finances%rowtype; result jsonb; begin
  perform bob_dinner_private.require_access(target_club,true);
  perform 1 from public.weekly_dinners where id=p_dinner and club_id=target_club for update;
  if not found then raise exception 'Jantar não encontrado.'; end if;
  insert into public.weekly_dinner_finances(club_id,dinner_id,created_by,updated_by)
    values(target_club,p_dinner,auth.uid(),auth.uid()) on conflict(dinner_id) do nothing;
  select * into f from public.weekly_dinner_finances where dinner_id=p_dinner for update;
  if p_closed is null then raise exception 'Estado inválido.'; end if;
  if p_closed and f.financial_status<>'closed' then
    perform t.id from public.treasury_transactions t join public.weekly_dinner_expenses l on l.transaction_id=t.id
      where l.dinner_id=p_dinner order by t.id for update of t;
    if exists(select 1 from public.bar_sales where weekly_dinner_id=p_dinner and status='draft') then
      raise exception 'Existem vendas em rascunho associadas ao jantar.'; end if;
    result:=bob_dinner_private.live_result(target_club,p_dinner);
    -- Excluded items remain unclassified, never silently included as beverages.
    -- line_total is constrained >= 0: any positive excluded line makes this
    -- sum positive. Resolve its association before recording a final snapshot.
    if (result->>'excluded_revenue')::numeric>0 then
      raise exception 'Existem vendas do BAR por classificar neste jantar. Classifica ou corrige essas vendas antes de fechar financeiramente.';
    end if;
    if (result->>'missing_cost_count')::integer>0 then
      raise exception 'Vendas antigas sem custo/classificação fiável: não é possível fechar.'; end if;
    insert into public.weekly_dinner_financial_snapshots(club_id,dinner_id,revision,snapshot,closed_by)
      values(target_club,p_dinner,f.revision+1,result||jsonb_build_object('meal_mode',f.meal_mode,
        'food_cost_manual',f.food_cost_manual,'other_cost_manual',f.other_cost_manual,'notes',f.notes),auth.uid());
    update public.weekly_dinner_finances set financial_status='closed',snapshot=result,revision=f.revision+1,
      closed_at=now(),closed_by=auth.uid(),updated_at=now(),updated_by=auth.uid() where dinner_id=p_dinner;
  elsif not p_closed and f.financial_status='closed' then
    -- Retain the previous snapshot and append-only revision archive on reopen.
    update public.weekly_dinner_finances set financial_status='open',updated_at=now(),updated_by=auth.uid() where dinner_id=p_dinner;
  end if;
  return public.weekly_dinner_finance_v1(target_club,p_dinner);
end $function$

CREATE OR REPLACE FUNCTION public.set_weekly_officer_member_v1(target_club uuid, p_member uuid, p_enabled boolean, p_availability_status text, p_force_included boolean, p_notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_old jsonb; v_new jsonb; v_order integer;
begin
  if not public.can_manage_weekly_officer_v1(target_club) then raise exception 'Apenas Presidente, Vice-Presidente ou Superadmin podem gerir a escala.'; end if;
  if p_availability_status not in ('active','absent','inactive') then raise exception 'Estado de disponibilidade inválido.'; end if;
  if not exists(select 1 from public.members where id=p_member and club_id=target_club) then raise exception 'Membro inválido.'; end if;
  select to_jsonb(r) into v_old from public.weekly_officer_rotation r where r.club_id=target_club and r.member_id=p_member;
  if v_old is null then
    select coalesce(max(rotation_order),0)+10 into v_order from public.weekly_officer_rotation where club_id=target_club;
    insert into public.weekly_officer_rotation(club_id,member_id,rotation_order,enabled,availability_status,force_included,notes)
    values(target_club,p_member,v_order,coalesce(p_enabled,true),p_availability_status,coalesce(p_force_included,false),nullif(btrim(coalesce(p_notes,'')),''));
  else
    update public.weekly_officer_rotation set enabled=coalesce(p_enabled,enabled),availability_status=p_availability_status,
      force_included=coalesce(p_force_included,force_included),notes=nullif(btrim(coalesce(p_notes,'')),''),updated_at=now(),updated_by=(select auth.uid())
    where club_id=target_club and member_id=p_member;
  end if;
  select to_jsonb(r) into v_new from public.weekly_officer_rotation r where r.club_id=target_club and r.member_id=p_member;
  perform public.audit_event(target_club,'weekly_officer_member_updated','weekly_officer_rotation',p_member::text,v_old,v_new,null);
  perform public.rebuild_weekly_officer_future_internal_v1(target_club,current_date);
end;
$function$

CREATE OR REPLACE FUNCTION public.settle_treasury_obligation_v1(target_club uuid, p_obligation_type text, p_obligation uuid, p_account uuid, p_amount numeric, p_payment_method text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row record;
  v_kind public.transaction_kind;
  v_transaction uuid;
  v_new_settled numeric;
  v_new_status text;
begin
  if auth.uid() is null
     or not public.has_club_permission(target_club,'manageTreasuryPlanning')
     or not public.has_club_permission(target_club,'createTreasuryMovement') then
    raise exception 'Sem permissão para liquidar obrigações financeiras.';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'O valor deve ser superior a zero.';
  end if;
  if not exists(select 1 from public.treasury_accounts a where a.id=p_account and a.club_id=target_club and a.active=true) then
    raise exception 'Conta financeira inválida.';
  end if;

  if p_obligation_type='payable' then
    select * into v_row from public.payables
    where id=p_obligation and club_id=target_club for update;
    v_kind := 'expense';
  elsif p_obligation_type='receivable' then
    select * into v_row from public.receivables
    where id=p_obligation and club_id=target_club for update;
    v_kind := 'income';
  else
    raise exception 'Tipo de obrigação inválido.';
  end if;

  if not found then raise exception 'Obrigação financeira não encontrada.'; end if;
  if v_row.status in ('paid','cancelled') then raise exception 'A obrigação já está encerrada.'; end if;
  if p_amount > (v_row.amount-v_row.settled_amount) then
    raise exception 'O valor excede o saldo da obrigação.';
  end if;

  insert into public.treasury_transactions(
    club_id,kind,account_id,transaction_date,description,amount,
    cost_center_id,event_id,payment_method,notes,source_type,source_id,created_by
  ) values (
    target_club,v_kind,p_account,current_date,
    case when p_obligation_type='payable' then 'Pagamento — ' else 'Recebimento — ' end || v_row.description,
    p_amount,v_row.cost_center_id,v_row.event_id,p_payment_method,p_notes,
    p_obligation_type,p_obligation,auth.uid()
  ) returning id into v_transaction;

  v_new_settled := v_row.settled_amount + p_amount;
  v_new_status := case when v_new_settled >= v_row.amount then 'paid' else 'partial' end;

  if p_obligation_type='payable' then
    update public.payables set settled_amount=v_new_settled,status=v_new_status,account_id=p_account where id=p_obligation;
  else
    update public.receivables set settled_amount=v_new_settled,status=v_new_status,account_id=p_account where id=p_obligation;
  end if;

  return v_transaction;
end;
$function$

CREATE OR REPLACE FUNCTION public.stage_import_rows_v1(target_club uuid, p_import uuid, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_import public.imports%rowtype; item jsonb; v_row_number integer; v_source jsonb; v_mapped jsonb; v_errors text[]; v_total integer; v_invalid integer;
begin
  if auth.uid() is null then raise exception 'Autenticação necessária.'; end if;
  select * into v_import from public.imports where id=p_import and club_id=target_club and requested_by=auth.uid() for update;
  if not found then raise exception 'Importação não encontrada.'; end if;
  if not public.import_target_allowed_v1(target_club,v_import.target) then raise exception 'Sem permissão para esta importação.'; end if;
  if v_import.status not in ('draft','ready','failed') then raise exception 'Esta importação já não pode ser alterada.'; end if;
  if p_rows is null or jsonb_typeof(p_rows)<>'array' then raise exception 'Linhas inválidas.'; end if;
  v_total:=jsonb_array_length(p_rows); if v_total<1 or v_total>1000 then raise exception 'A importação deve ter entre 1 e 1000 linhas.'; end if;
  if octet_length(p_rows::text)>5*1024*1024 then raise exception 'Dados de importação demasiado grandes.'; end if;
  delete from public.import_rows where import_id=p_import;
  for item in select value from jsonb_array_elements(p_rows) loop
    v_row_number:=coalesce((item->>'row_number')::integer,0); v_source:=coalesce(item->'source_data','{}'::jsonb); v_mapped:=coalesce(item->'mapped_data','{}'::jsonb);
    if v_row_number<=0 then raise exception 'Número de linha inválido.'; end if;
    if jsonb_typeof(v_source)<>'object' or jsonb_typeof(v_mapped)<>'object' then raise exception 'Conteúdo de linha inválido.'; end if;
    v_errors:=public.import_validate_row_v1(target_club,v_import.target,v_mapped);
    insert into public.import_rows(import_id,row_number,source_data,mapped_data,validation_errors) values(p_import,v_row_number,v_source,v_mapped,v_errors);
  end loop;
  if v_import.target='members' then
    update public.import_rows r set validation_errors=array_append(r.validation_errors,'Número de membro duplicado no ficheiro.'),updated_at=now()
    where r.import_id=p_import and nullif(btrim(r.mapped_data->>'member_number'),'') is not null
      and r.mapped_data->>'member_number' in (select mapped_data->>'member_number' from public.import_rows where import_id=p_import and nullif(btrim(mapped_data->>'member_number'),'') is not null group by mapped_data->>'member_number' having count(*)>1)
      and not ('Número de membro duplicado no ficheiro.'=any(r.validation_errors));
  end if;
  select count(*),count(*) filter(where cardinality(validation_errors)>0) into v_total,v_invalid from public.import_rows where import_id=p_import;
  update public.imports set total_rows=v_total,valid_rows=v_total-v_invalid,invalid_rows=v_invalid,applied_rows=0,error_code=null,status=case when v_invalid=0 then 'ready' else 'draft' end,updated_at=now() where id=p_import;
  insert into public.audit_log(club_id,actor_id,entity_type,entity_id,action,after_data,data) values(target_club,auth.uid(),'import',p_import::text,'import_staged',jsonb_build_object('total_rows',v_total,'valid_rows',v_total-v_invalid,'invalid_rows',v_invalid),jsonb_build_object('import_id',p_import));
  return jsonb_build_object('total_rows',v_total,'valid_rows',v_total-v_invalid,'invalid_rows',v_invalid,'status',case when v_invalid=0 then 'ready' else 'draft' end);
end; $function$

CREATE OR REPLACE FUNCTION public.start_document_ocr_v1(p_document uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_doc public.documents%rowtype; v_id uuid;
begin
  select * into v_doc from public.documents where id=p_document;
  if not found then raise exception 'Documento não acessível.'; end if;
  if not public.has_club_permission(v_doc.club_id,'runDocumentOcr') then raise exception 'Sem permissão para executar OCR.'; end if;
  if v_doc.current_version_id is null then raise exception 'Documento sem versão para OCR.'; end if;
  insert into public.document_ocr(club_id,document_id,version_id,status,provider,model,created_by)
  values(v_doc.club_id,p_document,v_doc.current_version_id,'pending','google_cloud_vision','DOCUMENT_TEXT_DETECTION',(select auth.uid())) returning id into v_id;
  update public.documents set ocr_status='pending',updated_at=now(),updated_by=(select auth.uid()) where id=p_document;
  return v_id;
end; $function$

CREATE OR REPLACE FUNCTION public.start_financial_document_ocr_v1(target_club uuid, p_document uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.financial_transaction_documents%rowtype; j public.financial_ocr_jobs%rowtype; v_id uuid;
begin
  if auth.uid() is null or not (public.has_club_permission(target_club,'createTreasuryMovement') or public.has_club_permission(target_club,'approveExpenseRequests')) then raise exception 'Sem autorização para executar OCR financeiro.'; end if;
  select * into d from public.financial_transaction_documents where id=p_document and club_id=target_club;
  if not found then raise exception 'Documento financeiro não encontrado.'; end if;
  if lower(coalesce(d.mime_type,'')) not in ('image/jpeg','image/png','image/webp','application/pdf') then raise exception 'Formato OCR não suportado. Usa JPG, PNG, WEBP ou PDF.'; end if;
  select * into j from public.financial_ocr_jobs where club_id=target_club and document_id=p_document and status in ('pending','processing','ready','reviewed','unconfigured') order by created_at desc limit 1;
  if found then
    if j.status='unconfigured' then update public.financial_ocr_jobs set status='pending',error_message=null,started_at=null,completed_at=null where id=j.id; end if;
    return j.id;
  end if;
  insert into public.financial_ocr_jobs(club_id,source_kind,document_id,transaction_id,storage_path,original_file_name,mime_type,file_size,status,provider)
  values(target_club,'transaction_document',d.id,d.transaction_id,d.storage_path,d.original_file_name,d.mime_type,d.file_size,'pending','openai') returning id into v_id;
  return v_id;
end; $function$

CREATE OR REPLACE FUNCTION public.submit_charge_proof_v1(target_club uuid, p_request uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.financial_requests%rowtype; own_member uuid; member_name text;
begin
  select * into r from public.financial_requests where id=p_request and club_id=target_club for update;
  if not found or r.request_type<>'charge' or r.status<>'awaiting_payment' then raise exception 'Cobrança não está disponível para envio de comprovativo.'; end if;
  own_member:=public.current_financial_member_v1(target_club);
  if r.member_id is distinct from own_member then raise exception 'Sem autorização.'; end if;
  if not exists(select 1 from public.financial_request_attachments a where a.request_id=p_request and a.kind='member_payment_proof') then raise exception 'Anexa o comprovativo de pagamento.'; end if;
  update public.financial_requests set status='awaiting_validation',submitted_at=now(),review_note=null where id=p_request;
  select coalesce(nullif(m.nickname,''),m.full_name) into member_name from public.members m where m.id=r.member_id;
  perform public.notify_financial_managers_v1(target_club,p_request,'Pagamento para validar',coalesce(member_name,'Membro')||' enviou comprovativo de '||to_char(r.amount,'FM999999990.00')||' €.','high');
  perform public.financial_activity_v1(target_club,p_request,'Comprovativo submetido',coalesce(member_name,'Membro')||' · '||to_char(r.amount,'FM999999990.00')||' €');
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_event_proposal_v1(target_club uuid, p_name text, p_description text DEFAULT NULL::text, p_location text DEFAULT NULL::text, p_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_event_kind text DEFAULT 'general'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
begin
  if (select auth.uid()) is null then raise exception 'Autenticação necessária.'; end if;
  if not public.has_club_access(target_club) or not public.has_club_permission(target_club, 'proposeEvents') then
    raise exception 'Sem permissão para propor eventos.';
