CREATE OR REPLACE FUNCTION public.submit_reimbursement_v1(target_club uuid, p_request uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.financial_requests%rowtype; own_member uuid; member_name text;
begin
  select * into r from public.financial_requests where id=p_request and club_id=target_club for update;
  if not found or r.request_type<>'reimbursement' then raise exception 'Pedido não encontrado.'; end if;
  if r.status not in ('draft','needs_info') then raise exception 'Este pedido não pode ser submetido.'; end if;
  own_member:=public.current_financial_member_v1(target_club);
  if not public.financial_manager_v1(target_club) and r.member_id is distinct from own_member then raise exception 'Sem autorização.'; end if;
  if not exists(select 1 from public.financial_request_attachments a where a.request_id=p_request and a.kind='receipt') then raise exception 'Adiciona pelo menos um talão ou recibo.'; end if;
  update public.financial_requests set status='pending_review',submitted_at=now(),review_note=null where id=p_request;
  select coalesce(nullif(m.nickname,''),m.full_name) into member_name from public.members m where m.id=r.member_id;
  perform public.financial_activity_v1(target_club,p_request,'Pedido de reembolso submetido',coalesce(member_name,'Membro')||' submeteu um pedido de '||to_char(r.amount,'FM999999990.00')||' €.');
  perform public.notify_financial_managers_v1(target_club,p_request,'Novo pedido de reembolso',coalesce(member_name,'Membro')||' pediu reembolso de '||to_char(r.amount,'FM999999990.00')||' €.','high');
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_dinner_fee_setting_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_amount numeric;
begin
  if new.key <> 'dinner_fee_amount' then
    return new;
  end if;

  begin
    v_amount := replace(btrim(new.value), ',', '.')::numeric;
  exception when others then
    raise exception 'O valor do jantar tem de ser numérico.';
  end;

  if v_amount <= 0 then
    raise exception 'O valor do jantar tem de ser superior a zero.';
  end if;

  update public.bar_sale_presets
  set unit_price = v_amount,
      updated_by = coalesce(new.updated_by, auth.uid()),
      updated_at = now()
  where club_id = new.club_id
    and lower(name) = lower('Jantar');

  return new;
end;
$function$

