CREATE OR REPLACE FUNCTION public.treasury_operational_reference_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v jsonb := to_jsonb(new);
  v_id uuid;
begin
  if nullif(v->>'account_id','') is not null then
    v_id := (v->>'account_id')::uuid;
    if not exists(select 1 from public.treasury_accounts a where a.id=v_id and a.club_id=new.club_id) then
      raise exception 'A conta financeira não pertence ao clube.';
    end if;
  end if;

  if nullif(v->>'cost_center_id','') is not null then
    v_id := (v->>'cost_center_id')::uuid;
    if not exists(select 1 from public.cost_centers c where c.id=v_id and c.club_id=new.club_id) then
      raise exception 'O centro de custo não pertence ao clube.';
    end if;
  end if;

  if nullif(v->>'event_id','') is not null then
    v_id := (v->>'event_id')::uuid;
    if not exists(select 1 from public.events e where e.id=v_id and e.club_id=new.club_id) then
      raise exception 'O evento não pertence ao clube.';
    end if;
  end if;

  if nullif(v->>'budget_id','') is not null then
    v_id := (v->>'budget_id')::uuid;
    if not exists(select 1 from public.budgets b where b.id=v_id and b.club_id=new.club_id) then
      raise exception 'O orçamento não pertence ao clube.';
    end if;
  end if;

  if nullif(v->>'reconciliation_id','') is not null then
    v_id := (v->>'reconciliation_id')::uuid;
    if not exists(select 1 from public.bank_reconciliations r where r.id=v_id and r.club_id=new.club_id) then
      raise exception 'A reconciliação não pertence ao clube.';
    end if;
  end if;

  if nullif(v->>'transaction_id','') is not null then
    v_id := (v->>'transaction_id')::uuid;
    if not exists(select 1 from public.treasury_transactions t where t.id=v_id and t.club_id=new.club_id) then
      raise exception 'O movimento não pertence ao clube.';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_event_guest_attendance_v1(p_event uuid, p_guest uuid, p_status text, p_notes text, p_checked_in_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_club uuid;
begin
  if p_status not in ('confirmed', 'pending') then
    raise exception 'guest_status_invalid' using errcode = 'P0001';
  end if;

  if p_status <> 'confirmed' and p_checked_in_at is not null then
    raise exception 'guest_checkin_requires_confirmed_status' using errcode = 'P0001';
  end if;

  select e.club_id
    into v_club
  from public.event_registration_guests g
  join public.event_registrations er on er.id = g.registration_id
  join public.events e on e.id = er.event_id
  where g.id = p_guest
    and er.event_id = p_event;

  if v_club is null then
    raise exception 'guest_not_found_for_event' using errcode = 'P0001';
  end if;

  if not public.has_club_permission(v_club, 'manageEventParticipants') then
    raise exception 'guest_attendance_permission_denied' using errcode = '42501';
  end if;

  update public.event_registration_guests
  set status = p_status,
      notes = nullif(btrim(coalesce(p_notes, '')), ''),
      checked_in_at = p_checked_in_at
  where id = p_guest;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_fee_settings_v1(target_club uuid, p_due_day integer, p_monthly_amount numeric, p_registration_amount numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or not public.has_club_permission(target_club,'manageFees') then raise exception 'Sem autorização para alterar as definições de quotas.'; end if;
  if p_due_day<1 or p_due_day>28 then raise exception 'O dia de vencimento deve estar entre 1 e 28.'; end if;
  if p_monthly_amount<0 or p_registration_amount<0 then raise exception 'Os valores não podem ser negativos.'; end if;
  insert into public.club_settings(club_id,key,value,updated_by) values
    (target_club,'fee_due_day',p_due_day::text,auth.uid()),(target_club,'monthly_fee_amount',p_monthly_amount::text,auth.uid()),(target_club,'registration_fee_amount',p_registration_amount::text,auth.uid())
  on conflict(club_id,key) do update set value=excluded.value,updated_by=excluded.updated_by,updated_at=now();
  update public.fee_plans set due_day=p_due_day,amount=p_monthly_amount where club_id=target_club and active=true and frequency='monthly';
end;
$function$

CREATE OR REPLACE FUNCTION public.update_import_row_v1(target_club uuid, p_import uuid, p_row uuid, p_mapped_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_import public.imports%rowtype; v_errors text[]; v_total integer; v_invalid integer;
begin
  if auth.uid() is null then raise exception 'Autenticação necessária.'; end if;
  select * into v_import from public.imports where id=p_import and club_id=target_club and requested_by=auth.uid() for update;
  if not found then raise exception 'Importação não encontrada.'; end if;
  if not public.import_target_allowed_v1(target_club,v_import.target) then raise exception 'Sem permissão.'; end if;
  if v_import.status not in ('draft','ready','failed') then raise exception 'Esta importação já não pode ser editada.'; end if;
  if p_mapped_data is null or jsonb_typeof(p_mapped_data)<>'object' then raise exception 'Dados mapeados inválidos.'; end if;
  v_errors:=public.import_validate_row_v1(target_club,v_import.target,p_mapped_data);
  update public.import_rows set mapped_data=p_mapped_data,validation_errors=v_errors,updated_at=now() where id=p_row and import_id=p_import;
  if not found then raise exception 'Linha não encontrada.'; end if;
  if v_import.target='members' then
    update public.import_rows r set validation_errors=array_remove(r.validation_errors,'Número de membro duplicado no ficheiro.'),updated_at=now() where r.import_id=p_import;
    update public.import_rows r set validation_errors=array_append(r.validation_errors,'Número de membro duplicado no ficheiro.'),updated_at=now()
      where r.import_id=p_import and nullif(btrim(r.mapped_data->>'member_number'),'') is not null and r.mapped_data->>'member_number' in (select mapped_data->>'member_number' from public.import_rows where import_id=p_import and nullif(btrim(mapped_data->>'member_number'),'') is not null group by mapped_data->>'member_number' having count(*)>1);
  end if;
  select count(*),count(*) filter(where cardinality(validation_errors)>0) into v_total,v_invalid from public.import_rows where import_id=p_import;
  update public.imports set total_rows=v_total,valid_rows=v_total-v_invalid,invalid_rows=v_invalid,status=case when v_invalid=0 then 'ready' else 'draft' end,error_code=null,updated_at=now() where id=p_import;
  select validation_errors into v_errors from public.import_rows where id=p_row;
  return jsonb_build_object('validation_errors',to_jsonb(v_errors),'status',case when v_invalid=0 then 'ready' else 'draft' end,'valid_rows',v_total-v_invalid,'invalid_rows',v_invalid);
end; $function$

CREATE OR REPLACE FUNCTION public.update_reimbursement_draft_v1(target_club uuid, p_request uuid, p_amount numeric, p_description text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.financial_requests%rowtype; own_member uuid;
begin
  if p_amount is null or p_amount<=0 then raise exception 'O valor deve ser superior a zero.'; end if;
  if nullif(btrim(p_description),'') is null then raise exception 'A descrição é obrigatória.'; end if;
  select * into r from public.financial_requests where id=p_request and club_id=target_club for update;
  if not found or r.request_type<>'reimbursement' then raise exception 'Pedido não encontrado.'; end if;
  if r.status not in ('draft','needs_info') then raise exception 'Este pedido já não pode ser editado.'; end if;
  own_member:=public.current_financial_member_v1(target_club);
  if not public.financial_manager_v1(target_club) and r.member_id is distinct from own_member then raise exception 'Sem autorização.'; end if;
  update public.financial_requests set amount=round(p_amount,2),description=btrim(p_description),review_note=null where id=p_request;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_event_advanced_relation_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_event uuid;
  v_club uuid;
  v_member_club uuid;
begin
  if tg_table_name = 'event_guests' then
    select m.club_id into v_member_club
    from public.members m
    where m.id = new.host_member_id;
    if v_member_club is distinct from new.club_id then
      raise exception 'O membro anfitrião não pertence ao clube do evento.';
    end if;
    if new.registration_id is not null then
      select r.event_id into v_event
      from public.event_registrations r
      where r.id = new.registration_id
        and r.member_id = new.host_member_id;
      if v_event is distinct from new.event_id then
        raise exception 'A inscrição não corresponde ao membro e evento indicados.';
      end if;
    end if;
  elsif tg_table_name = 'event_route_stops' then
    select r.event_id, r.club_id into v_event, v_club
    from public.event_routes r
    where r.id = new.route_id;
    if v_event is distinct from new.event_id or v_club is distinct from new.club_id then
      raise exception 'A paragem não pertence ao roadbook deste evento.';
    end if;
  elsif tg_table_name = 'event_volunteers' then
    select e.id, e.club_id into v_event, v_club
    from public.events e
    where e.id = new.event_id;
    if v_event is distinct from new.event_id or v_club is distinct from new.club_id then
      raise exception 'O voluntário não pertence a este evento.';
    end if;
    if new.member_id is not null then
      select m.club_id into v_member_club
      from public.members m
      where m.id = new.member_id;
      if v_member_club is distinct from new.club_id then
        raise exception 'O membro voluntário não pertence ao clube do evento.';
      end if;
    elsif new.guest_id is not null then
      select er.event_id, e.club_id into v_event, v_club
      from public.event_registration_guests g
      join public.event_registrations er on er.id = g.registration_id
      join public.events e on e.id = er.event_id
      where g.id = new.guest_id;
      if v_event is distinct from new.event_id or v_club is distinct from new.club_id then
        raise exception 'O acompanhante voluntário não pertence a este evento.';
      end if;
    end if;
  elsif tg_table_name = 'event_task_assignees' then
    select t.event_id, t.club_id into v_event, v_club
    from public.event_tasks t
    where t.id = new.task_id;
    if v_event is distinct from new.event_id or v_club is distinct from new.club_id then
      raise exception 'A tarefa não pertence a este evento.';
    end if;
    if new.member_id is not null then
      select m.club_id into v_member_club
      from public.members m
      where m.id = new.member_id;
      if v_member_club is distinct from new.club_id then
        raise exception 'O membro atribuído não pertence ao clube do evento.';
      end if;
    elsif new.guest_id is not null then
      select er.event_id, e.club_id into v_event, v_club
      from public.event_registration_guests g
      join public.event_registrations er on er.id = g.registration_id
      join public.events e on e.id = er.event_id
      where g.id = new.guest_id;
      if v_event is distinct from new.event_id or v_club is distinct from new.club_id then
        raise exception 'O acompanhante atribuído não pertence a este evento.';
      end if;
    end if;
    if not exists (
      select 1
      from public.event_volunteers v
      where v.event_id = new.event_id
        and v.club_id = new.club_id
        and (
          (new.member_id is not null and v.member_id = new.member_id)
          or (new.guest_id is not null and v.guest_id = new.guest_id)
        )
    ) then
      raise exception 'A pessoa atribuída não está registada como voluntária neste evento.';
    end if;
  elsif tg_table_name = 'event_shift_members' then
    select s.event_id, s.club_id into v_event, v_club
    from public.event_shifts s
    where s.id = new.shift_id;
    if v_event is distinct from new.event_id or v_club is distinct from new.club_id then
      raise exception 'O turno não pertence a este evento.';
    end if;
    if new.member_id is not null then
      select m.club_id into v_member_club
      from public.members m
      where m.id = new.member_id;
      if v_member_club is distinct from new.club_id then
        raise exception 'O membro atribuído não pertence ao clube do evento.';
      end if;
    elsif new.guest_id is not null then
      select er.event_id, e.club_id into v_event, v_club
      from public.event_registration_guests g
      join public.event_registrations er on er.id = g.registration_id
      join public.events e on e.id = er.event_id
      where g.id = new.guest_id;
      if v_event is distinct from new.event_id or v_club is distinct from new.club_id then
        raise exception 'O acompanhante atribuído não pertence a este evento.';
      end if;
    end if;
    if not exists (
      select 1
      from public.event_volunteers v
      where v.event_id = new.event_id
        and v.club_id = new.club_id
        and (
          (new.member_id is not null and v.member_id = new.member_id)
          or (new.guest_id is not null and v.guest_id = new.guest_id)
        )
    ) then
      raise exception 'A pessoa atribuída não está registada como voluntária neste evento.';
    end if;
  elsif tg_table_name = 'event_program' then
    if new.responsible_member_id is not null then
      select m.club_id into v_member_club
      from public.members m
      where m.id = new.responsible_member_id;
      if v_member_club is distinct from new.club_id then
        raise exception 'O responsável não pertence ao clube do evento.';
      end if;
    end if;
  elsif tg_table_name = 'event_incidents' then
    if new.reported_by_member_id is not null then
      select m.club_id into v_member_club
      from public.members m
      where m.id = new.reported_by_member_id;
      if v_member_club is distinct from new.club_id then
        raise exception 'O membro que reportou não pertence ao clube do evento.';
      end if;
    end if;
    if new.assigned_member_id is not null then
      select m.club_id into v_member_club
      from public.members m
      where m.id = new.assigned_member_id;
      if v_member_club is distinct from new.club_id then
        raise exception 'O membro responsável não pertence ao clube do evento.';
      end if;
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_treasury_transaction_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  source_account public.treasury_accounts%rowtype;
  destination_account public.treasury_accounts%rowtype;
  source_balance numeric;
begin
  if new.amount is null or new.amount <= 0 then
    raise exception 'O valor do movimento deve ser superior a zero.';
  end if;

  select * into source_account
  from public.treasury_accounts
  where id = new.account_id
    and club_id = new.club_id
    and active = true;

  if not found then
    raise exception 'A conta de origem não existe, está inativa ou pertence a outro clube.';
  end if;

  if new.kind = 'transfer' then
    if new.destination_account_id is null then
      raise exception 'A transferência exige uma conta de destino.';
    end if;
    if new.destination_account_id = new.account_id then
      raise exception 'As contas de origem e destino têm de ser diferentes.';
    end if;

    select * into destination_account
    from public.treasury_accounts
    where id = new.destination_account_id
      and club_id = new.club_id
      and active = true;

    if not found then
      raise exception 'A conta de destino não existe, está inativa ou pertence a outro clube.';
    end if;
  elsif new.destination_account_id is not null then
    raise exception 'A conta de destino só pode ser usada numa transferência.';
  end if;

  if new.kind in ('expense', 'transfer') and not coalesce(source_account.allows_negative, false) then
    source_balance := public.treasury_account_balance_v1(new.account_id);
    if coalesce(source_balance, 0) < new.amount then
      raise exception 'Saldo insuficiente na conta %.', source_account.name;
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.weekly_dinner_finance_v1(target_club uuid, p_dinner uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare f public.weekly_dinner_finances%rowtype; result jsonb; revisions jsonb; begin
  perform bob_dinner_private.require_access(target_club);
  if not exists(select 1 from public.weekly_dinners where id=p_dinner and club_id=target_club) then
    raise exception 'Jantar não encontrado.'; end if;
  select * into f from public.weekly_dinner_finances where dinner_id=p_dinner and club_id=target_club;
  result:=case when f.financial_status='closed' then f.snapshot
    else bob_dinner_private.live_result(target_club,p_dinner) end;
  select coalesce(jsonb_agg(jsonb_build_object('revision',revision,'closed_at',closed_at,'snapshot',snapshot)
    order by revision desc),'[]'::jsonb) into revisions from public.weekly_dinner_financial_snapshots
    where dinner_id=p_dinner and club_id=target_club;
  return result||jsonb_build_object('dinner_id',p_dinner,'financial_status',coalesce(f.financial_status,'none'),
    'meal_mode',coalesce(f.meal_mode,'automatic'),'manual_meal_quantity',coalesce(f.manual_meal_quantity,0),
    'manual_meal_revenue',coalesce(f.manual_meal_revenue,0),'food_cost_manual',coalesce(f.food_cost_manual,0),
    'other_cost_manual',coalesce(f.other_cost_manual,0),'notes',f.notes,'closed_at',f.closed_at,'closed_by',f.closed_by,
    'revision',coalesce(f.revision,0),'previous_snapshots',revisions);
end $function$

CREATE OR REPLACE FUNCTION public.weekly_officer_member_append_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_order integer;
begin
  if not exists(select 1 from public.weekly_officer_rotation r where r.club_id=new.club_id and r.member_id=new.id) then
    select coalesce(max(r.rotation_order),0)+10 into v_order from public.weekly_officer_rotation r where r.club_id=new.club_id;
    insert into public.weekly_officer_rotation(club_id,member_id,rotation_order) values(new.club_id,new.id,v_order) on conflict (club_id,member_id) do nothing;
  end if; return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.weekly_officer_notify_member_v1(target_club uuid, p_member uuid, p_title text, p_body text, p_entity_type text, p_entity_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_profile uuid; v_in_app boolean;
begin
  select m.profile_id into v_profile from public.members m where m.id=p_member and m.club_id=target_club;
  if v_profile is null then return; end if;
  select np.in_app_enabled into v_in_app from public.notification_preferences np
  where np.club_id=target_club and np.profile_id=v_profile and np.module_code='weekly_officer';
  if coalesce(v_in_app,true)=false then return; end if;
  insert into public.notifications(club_id,profile_id,title,body,notification_type,module_code,priority,entity_type,entity_id,action_route,metadata)
  values(target_club,v_profile,p_title,p_body,'info','weekly_officer','normal',p_entity_type,p_entity_id,'weekly_officer',jsonb_build_object('module_code','weekly_officer'));
end;
$function$

CREATE OR REPLACE FUNCTION public.withdraw_event_proposal_v1(p_proposal uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v public.event_proposals%rowtype;
begin
  if (select auth.uid()) is null then raise exception 'Autenticação necessária.'; end if;
  select * into v from public.event_proposals where id = p_proposal for update;
  if not found then raise exception 'Proposta não encontrada.'; end if;
  if v.proposed_by <> (select auth.uid()) then raise exception 'Só o autor pode retirar a proposta.'; end if;
  if v.status <> 'submitted' then raise exception 'A proposta já foi processada.'; end if;
  update public.event_proposals
  set status='withdrawn', updated_at=now(), updated_by=(select auth.uid())
  where id=p_proposal;
end;
$function$
